[84864] = {"力量之路","力量之路专注于造成沉重打击和护甲穿透攻击，对板甲使用者尤为有利。\n\n@ext:使你获得额外力量，每点力量还会提高你的|cFFFFFFFF攻击强度|r和|cFFFFFFFF招架|r。:ext@\n@ext:@s:986203:0@:ext@\n@ext:@s:986202:0@:ext@","汉化"},
[84865] = {"敏捷之路","敏捷之路专注于快速攻击与爆击，特别有利于皮甲和锁甲使用者。\n\n@ext:使你获得额外敏捷，每点敏捷还会提高你的|cFFFFFFFF攻击强度|r、|cFFFFFFFF爆击率|r和|cFFFFFFFF爆击伤害|r。:ext@\n@ext:@s:986201:0@:ext@\n@ext:@s:986200:0@:ext@","汉化"},
[84866] = {"智慧之道","智慧之道专注于强化法术伤害，提升法力值上限，尤其对依赖法术强度和智力的玩家收益显著。\n\n@ext:使你获得额外|cFFFFFFFF法术强度|r、智力、精神，且装备和效果提供的|cFFFFFFFF法术强度|r加成翻倍。:ext@\n@ext:@s:92839:0@:ext@\n@ext:@s:92840:0@:ext@","汉化"},
[84867] = {"修复之路","修复之路使你能胜任|cFFFFFFFF治疗职责|r。此主属性会提高你的|cFFFFFFFF治疗强度|r，并使你能使用独有的强力治疗法术。\n\n@ext:获得以下属性加成：|cFFFFFFFF治疗强度|r、|cFFFFFFFF智力|r、|cFFFFFFFF精神|r，且每点|cFFFFFFFF法术强度|r现在也会提高你的|cFFFFFFFF治疗强度|r:ext@\n@ext:@s:92842:0@:ext@\n@ext:@s:92843:0@:ext@","汉化"},
[92839] = {"魔法加速","当你装备双手武器时，你的法术急速提高%。","汉化"},
[92840] = {"毁灭法术","当你装备单手武器时，你的法术伤害提高%。","汉化"},
[92842] = {"精神加速","装备一把双手武器时，你的法术急速提高，爆击率提高%。","汉化"},
[92843] = {"增强治疗","装备一把单手武器时，你的治疗效果提高%。","汉化"},
[93534] = {"火焰陷阱精通","学会任意火焰陷阱时，你将获得火焰陷阱精通。\n\n该精通会在你达到相应职业点数要求时，自动解锁额外的火焰陷阱，且无需消耗额外的技能精华。\n@ext:@s:120147:0@~@s:120147:-1@:ext@\n@ext:@s:120148:0@~@s:120148:-1@:ext@","汉化"},
[93535] = {"图腾召唤精通","学会任意图腾召唤法术时，你将获得图腾召唤精通。\n\n该精通会在你达到相应职业点数要求时，自动解锁额外的图腾召唤法术，且无需消耗额外的技能精华。\n@ext:@s:66842:0@~@s:66842:-1@:ext@\n@ext:@s:66843:0@~@s:66843:-1@:ext@\n@ext:@s:66844:0@~@s:66844:-1@:ext@","汉化"},
