[1100017] = {"真言术：盾","汲取队友的灵魂之力为其加上护盾，可吸取点伤害，持续d。护盾能保护施法不会被伤害打断。目标在被加上护盾后的1106788d内无法再次加上护盾。","汉化"},
[1100053] = {"背刺","背刺目标，造成m2%武器伤害外加m1*1.5点伤害。必须在目标背后发动。主手需装备匕首。奖励个连击点数。","汉化"},
[1100066] = {"隐形术","立即使施法者隐形。降低所有威胁。施法者在1100066d后隐形，每秒降低威胁。隐形时，你只能看到其他隐形目标和能看到隐形目标的人，使用时会消除无敌状态，持续1132612d。","汉化"},
[1100072] = {"盾击","用你的盾牌重击目标，使其眩晕并打断法术施放。使其在d内无法施放该系法术。","汉化"},
[1100078] = {"英勇打击","强力的攻击。使近战伤害提高，并产生大量威胁值。","汉化"},
[1100099] = {"挫志咆哮","德鲁伊发出咆哮，使附近所有敌人的近战攻击强度降低点，持续d。","汉化"},
[1100100] = {"冲锋","冲向敌人，获得/10;s2点怒气，并使其昏迷1107922d。不能在战斗中使用。","汉化"},
[1100116] = {"寒冰箭","向敌人发射一枚寒冰箭，造成m2*mult到M2*mult点冰霜伤害，并使其移动速度减少%，持续d。","汉化"},
[1100118] = {"变形术","将敌人变成绵羊，使其在周围到处闲逛，最多持续d。在此期间，绵羊无法攻击或施法，但会以极快的速度恢复生命力，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。","汉化"},
[1100120] = {"冰锥术","施法者前方锥形区域内的目标受到m2*mult到M2*mult点冰霜伤害，并且速度降低%，持续d。","汉化"},
[1100122] = {"冰霜新星","冲击施法者附近的所有敌人，造成m1*mult到M1*mult点冰霜伤害，并将其冻结在原地，最多持续d。对被冻结的目标造成伤害可能打断这个效果。","汉化"},
[1100126] = {"基尔罗格之眼","召唤一基尔罗格之眼，并让你以它的视角观察世界。基尔罗格之眼的移动速度很快，但也非常脆弱。","汉化"},
[1100130] = {"缓落术","减缓友方小队或团队目标的掉落速度，持续d。","汉化"},
[1100131] = {"水下呼吸","使目标可以在水下呼吸，持续d。","汉化"},
[1100132] = {"侦测隐形","让友方目标能够侦查到次级隐形术，持续d。","汉化"},
[1100133] = {"火球术","投掷火球，造成M1+ppl1至M1+ppl1的火焰伤害，以及超过d的额外o2火焰伤害。","汉化"},
[1100136] = {"治疗宠物","在d内为你的宠物治疗total点生命值。","汉化"},
[1100139] = {"恢复","在d内治疗目标total点生命值。","汉化"},
[1100143] = {"火球术","投掷一枚火球，造成m1+ppl1到M1+ppl1点火焰伤害，并在d内额外造成o2点火焰伤害。","汉化"},
[1100145] = {"火球术","投掷一枚火球，造成m1+ppl1到M1+ppl1点火焰伤害，并在d内额外造成o2点火焰伤害。","汉化"},
[1100168] = {"霜甲术","护甲提高点。若敌人攻击施法者，其移动速度可能降低1106136s1%，攻击间隔延长1106136s2%，持续1106136d。法师同时只能激活一类护甲法术，持续d。","汉化"},
[1100172] = {"腐蚀术","腐蚀目标，在d内造成o1点暗影伤害。","汉化"},
[1100205] = {"寒冰箭","向敌人发射一枚寒冰箭，造成m2*mult到M2*mult点冰霜伤害，并使其移动速度减少%，持续d。","汉化"},
