[1100421] = {"闪电链","向敌人射出一支闪电箭，对其造成点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少30%，最多可攻击x1个目标。","汉化"},
