[1100465] = {"虔诚光环","为a1码内的小队和团队成员提供点额外护甲。每位圣骑士同时只能开启一种光环。","汉化"},
[1100467] = {"荆棘术","使友方目标身上环绕着荆棘，对任何命中其的攻击者造成点自然伤害，持续d。","汉化"},
[1100469] = {"命令怒吼","使a1码范围内的所有小队和团队成员的最大生命值提高点。持续d。","汉化"},
[1100475] = {"解除诅咒","从一个友方目标身上驱散m1个诅咒。","汉化"},
