[1100602] = {"心灵之火","圣洁的能量充满施法者的体内，提高护甲值点和法术能量点。每次近战或远程伤害击中牧师，将消耗1层能量。可持续d，或者直到n层能量消耗完毕。","汉化"},
[1100603] = {"厄运诅咒","对目标施加终极的诅咒，在d后造成点暗影伤害。如果目标在死于该伤害且可以为你提供经验或荣誉值，则会召唤出一个末日守卫。无法对玩家施放。","汉化"},
[1100604] = {"魔法抑制","抑制目标小队成员受到的魔法，使其受到的魔法伤害最多减少，受到的治疗效果最多减少，持续d。","汉化"},
[1100605] = {"精神控制","控制一个最多级的人型生物的思维，但会使其攻击间隔延长%，最多持续d。","汉化"},
[1100633] = {"圣疗术","为一名友方目标治疗相当于圣骑士最大生命值的生命值。若对自身使用，圣骑士在1125771d内将无法再次成为以下技能的目标：圣盾术、圣佑术、保护之手或自我施放的圣疗术，且在使用复仇之怒后的1161987d内无法对自身使用该技能。","汉化"},
