[1100642] = {"圣盾术","使圣骑士免疫所有伤害和法术，持续d，但造成的所有伤害降低%。受到保护后，目标在25771d内无法再次受到圣盾术、保护之手或圣佑术保护。在使用复仇之怒后的61987d内无法使用该技能。","汉化"},
