[1100686] = {"暗影箭","向敌人射出一支黑暗魔法箭，造成m1+ppl1到M1+ppl1点暗影伤害。","汉化"},
[1100687] = {"恶魔皮肤","保护施法者，护甲值提高点，并使法术效果产生的生命值提高%。术士同一时间只能激活一种护甲法术。持续d。","汉化"},
