[1100691] = {"召唤地狱猎犬","召唤一只地狱猎犬听命于术士。","汉化"},
[1100693] = {"制造灵魂石","制造一个初级灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死亡。他可以依靠灵魂石复活，并恢复1103026s1点生命值和1103026q1点法力值。\n制造的物品会在登出游戏超过15分钟之后消失。","汉化"},
[1100694] = {"惩戒痛击","嘲讽攻击，造成中等程度的威胁，并迫使目标集中攻击你，持续d。如果目标是可嘲讽的，还会造成武器伤害。（此技能必中）","汉化"},
[1100695] = {"暗影箭","向敌人射出一支黑暗魔法箭，造成m1+ppl1到M1+ppl1点暗影伤害。","汉化"},
[1100696] = {"恶魔皮肤","保护施法者，护甲值提高点，并使法术效果产生的生命值提高%。术士同一时间只能激活一种护甲法术。持续d。","汉化"},
[1100697] = {"召唤虚空行者","召唤一个虚空行者为术士作战。","汉化"},
[1100698] = {"召唤仪式","开启一个召唤传送门的仪式。该传送门需要2名小队或团队成员完成仪式，用于召唤指定的小队或团队成员。完成此仪式需要施法者与另外2名小队或团队成员共同参与。所有参与者必须脱离战斗状态，右键点击传送门并保持静止直至仪式完成。","汉化"},
[1100699] = {"吸取生命","每t1秒吸取目标点生命值，并将其转移给施法者，持续d。","汉化"},
[1100702] = {"虚弱诅咒","目标的近战攻击力减少，护甲减少%,持续d。每个术士只能对一个目标使用一个诅咒。","汉化"},
[1100703] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值受攻击强度加成。必须处于潜行状态并位于目标身后。获得个连击l点。","汉化"},
[1100705] = {"暗影箭","向敌人射出一支黑暗魔法箭，造成m1+ppl1到M1+ppl1点暗影伤害。","汉化"},
[1100706] = {"恶魔护甲","保护施法者，护甲值提高点，法术和效果产生的生命值恢复效果提高点，法术和效果产生的生命值恢复效果提高%。同一时间内术士只能激活一种护甲类法术。持续d。","汉化"},
[1100707] = {"献祭","造成m1+ppl1点火焰伤害，随后在d内额外造成o1点火焰伤害。","汉化"},
[1100709] = {"吸取生命","每t1秒吸取目标点生命值，并将其转移给施法者，持续d。","汉化"},
[1100710] = {"放逐术","放逐敌方目标，使其无法行动但处于无敌状态，持续d。同一时间只能放逐一个目标。对已放逐目标再次施放将取消该效果。仅对恶魔和元素生物生效。","汉化"},
[1100712] = {"召唤魅魔","召唤一个魅魔协助术士作战。","汉化"},
[1100724] = {"光明之泉","制造一个神圣光明之泉。友方玩家可以点击光明之泉，在1107001d内恢复1107001m1*3*mult点生命值，对你造成的攻击相当于你生命总值的30%将取消该效果。光明之泉持续d或10次使用次数。","汉化"},
[1100740] = {"宁静","每t2秒使附近所有小队成员的生命值恢复点。持续d。德鲁伊必须引导维持此法术。","汉化"},
[1100755] = {"生命通道","施法者引导期间，每秒为宠物恢复点生命值，持续d。","汉化"},
[1100759] = {"制造法力宝石","制造一颗魔法玛瑙，使用后可以立刻恢复1105405s1点法力值。","汉化"},
[1100760] = {"治疗龙族","只要施法者保持引导法术的状态，每秒就能治疗被驯服的龙族m1+ppl1+SP*0.538点生命值，持续d。","汉化"},
[1100761] = {"治疗龙族","只要施法者保持引导法术的状态，每秒就能治疗被驯服的龙族m1+ppl1+SP*0.538点生命值，持续d。","汉化"},
[1100762] = {"治疗龙族","只要施法者保持引导法术的状态，每秒就能治疗被驯服的龙族m1+ppl1+SP*0.538点生命值，持续d。","汉化"},
[1100763] = {"治疗龙族","只要施法者保持引导法术的状态，每秒就能治疗被驯服的龙族m1+ppl1+SP*0.538点生命值，持续d。","汉化"},
[1100764] = {"治疗龙族","只要施法者保持引导法术的状态，每秒就能治疗被驯服的龙族m1+ppl1+SP*0.538点生命值，持续d。","汉化"},
