[1100890] = {"奴役恶魔","教会你奴役一只恶魔同伴需要的技能。\n\n教会你奴役恶魔、召唤恶魔、解散恶魔、复活恶魔和恶魔学识。\n\n@ext:@s:1100896:0@:ext@","汉化"},
