[1100974] = {"大地之盾","一层大地之盾保护目标，使其因受到伤害而损失的施法或引导时间缩短%。被大地之盾保护的目标在受到攻击时可以恢复heal。该效果每几秒只能出现一次，可使用n次，持续d。大地之盾一次只能作用于一个目标。一个目标一次只能激活一个元素护盾。","汉化"},
