[1100980] = {"痛苦诅咒","对目标施加痛苦诅咒，使其在d内受到o1点暗影伤害。这种伤害在初期会缓慢生效，但是会在作用效果期间不断加速，直到结束。每个术士对同一个目标只能施加一种诅咒。","汉化"},
