[1101004] = {"惩击","惩击敌人，并造成m1+ppl1toM1+ppl1点神圣伤害。","汉化"},
[1101006] = {"心灵之火","圣洁的能量充满施法者的体内，提高护甲值点和法术能量点。每次近战或远程伤害击中牧师，将消耗1层能量。可持续d，或者直到n层能量消耗完毕。","汉化"},
[1101008] = {"魔法增效","魔法增效对目标小队成员使用时，使其受到的魔法伤害提高，受到的治疗效果提高，持续d。","汉化"},
[1101014] = {"痛苦诅咒","对目标施加痛苦诅咒，使其在d内受到o1点暗影伤害。这种伤害在初期会缓慢生效，但是会在作用效果期间不断加速，直到结束。每个术士对同一个目标只能施加一种诅咒。","汉化"},
[1101022] = {"保护之手","使一名小队或团队成员免疫所有物理攻击，持续d，但期间该目标无法攻击或使用物理技能。每位圣骑士同时只能对目标施加一种圣手。受到保护后，目标在1125771d内无法再次受到圣盾术、保护祝福或保护之手的影响。对最近1161987d内使用过复仇之怒的玩家无效。","汉化"},
