[1101064] = {"治疗链","为友方目标恢复点生命值，然后跳跃治疗其他附近的目标。如果施放对象是小队成员，则治疗仅会跳跃至小队其他成员。每次跳跃会使治疗效果降低40%。总共治疗x1个目标。","汉化"},
[1101066] = {"水栖形态","变形为水栖形态，游泳速度提高1105421s1%并允许德鲁伊在水下呼吸。同时保护施法者免受变形术效果影响。\n\n变形行为将使施法者摆脱变形术和移动限制效果。","汉化"},
