[1101079] = {"割裂（豹）","终结技，使目标在一段时间内受到持续的伤害。根据连击点数和你的攻击强度决定伤害量:\n1点：d内(m1+b1*1+0.01*AP)*dur点伤害。\n2点：d内(m1+b1*2+0.02*AP)*dur点伤害。\n3点：d内(m1+b1*3+0.03*AP)*dur点伤害。\n4点：d内(m1+b1*4+0.04*AP)*dur点伤害。\n5点：d内(m1+b1*5+0.05*AP)*dur点伤害。","汉化"},
[1101082] = {"爪击","爪击敌人，造成额外点额外伤害。奖励个连击点数。","汉化"},
[1101086] = {"恶魔护甲","保护施法者，护甲值提高点，法术和效果产生的生命值恢复效果提高点，法术和效果产生的生命值恢复效果提高%。同一时间内术士只能激活一种护甲类法术。持续d。","汉化"},
[1101088] = {"暗影箭","向敌人射出一支黑暗魔法箭，造成m1+ppl1到M1+ppl1点暗影伤害。","汉化"},
[1101094] = {"献祭","造成m1+ppl1点火焰伤害，随后在d内额外造成o1点火焰伤害。","汉化"},
[1101098] = {"临时奴役恶魔","奴役目标恶魔，最高等级为m1，强迫其服从你的命令。奴役期间，恶魔的攻击间隔延长%，施法速度降低%。持续d。","汉化"},
[1101106] = {"暗影箭","向敌人射出一支黑暗魔法箭，造成m1+ppl1到M1+ppl1点暗影伤害。","汉化"},
[1101108] = {"虚弱诅咒","目标的近战攻击力减少，护甲减少%,持续d。每个术士只能对一个目标使用一个诅咒。","汉化"},
[1101120] = {"灵魂吸取","吸取目标的灵魂，在d内造成o2点暗影伤害。若目标生命值处于或低于25%，则造成的伤害提高至四倍。如果目标在被吸取期间死亡，并且该目标可提供经验值或荣誉，则施法者将获得一块灵魂碎片。每次“吸取灵魂”对目标造成伤害时，都有一定几率生成一块灵魂碎片。灵魂碎片是施放其他法术所需的材料。","汉化"},
[1101122] = {"地狱火","从扭曲虚空中召唤一颗陨石，造成22699s1点火焰伤害并使区域内所有敌方目标昏迷20310d。一个地狱火将从陨石坑中复活，受施法者控制20882d。","汉化"},
