[1101130] = {"猎人印记","猎人对目标施加猎人印记，使所有攻击者对该目标的远程攻击强度提高点。此外，无论目标潜行或隐身，猎人都能始终看到该目标，并且目标也会出现在小地图上，持续d。","汉化"},
