[1106768] = {"佯攻","施展佯攻，不会造成任何伤害，但大幅降低你的仇恨值，使敌人不太可能攻击你。此外，在d内，减少你受到的范围攻击伤害%。","汉化"},
[1106770] = {"闷棍","使目标瘫痪最多d。必须在潜行状态下使用，只能作用于非作战状态下的人型，野兽，恶魔和龙类目标。任何对目标造成伤害的行为都会使其苏醒。同时只能闷棍一个目标。","汉化"},
[1106774] = {"切割","终结技，提升近战攻击速度%。持续时间随连击点数增加：\n1点:(9+glyph)*(100+mult)/100秒\n2点:(12+glyph)*(100+mult)/100秒\n3点:(15+glyph)*(100+mult)/100秒\n4点:(18+glyph)*(100+mult)/100秒\n5点:(21+glyph)*(100+mult)/100秒","汉化"},
