[1106800] = {"撕碎","对目标进行撕碎，造成%伤害外加72点伤害。必须在目标背后施放。获得连击点数。增加流血伤害的效果也会增加撕碎伤害。","汉化"},
[1106807] = {"重殴","强力攻击，使近战攻击伤害提高点，并造成大量的威胁值。所有提高流血伤害的效果可同时提高重殴伤害。","汉化"},
