[1106934] = {"闪避守护（姿态）","进入熊形态，近战攻击强度提高1101178s3，由布甲和皮甲装备获得的护甲值提高1101178s1%，耐力值提高1101178s2%。免疫变形魔法效果，并可使用多种熊形态下专有技能。\n\n变身可以解除施法者身上的所有变形和移动限制效果。","汉化"},
[1106937] = {"巧击","@req:1106934:req@\n连击点终结技每消耗一个连击点有10%几率使你受到的所有伤害降低8%，持续12秒。\n\n还击会额外攻击一个目标，且成功躲闪任何攻击时有25%几率允许使用还击。","汉化"},
[1106938] = {"巧击","@req:1106934:req@\n连击点终结技每消耗一个连击点有10%几率使你受到的所有伤害降低8%，持续12秒。\n\n还击会额外攻击一个目标，且成功躲闪任何攻击时有25%几率允许使用还击。","汉化"},
[1106940] = {"牺牲之手","在小队或团队成员身上施放法术。将受到的%伤害转移给施法者，持续d或直到施法者转移了其最大生命值的%。每名圣骑士只能同时在每名玩家身上施加一种圣手效果","汉化"},
