[1108184] = {"抗火图腾","在施法者脚下召唤一个拥有生命值的火焰抗性图腾，持续d。使1108185a1码范围内的所有队伍和团队成员提高1108185s1点火焰抗性。","汉化"},
[1108190] = {"熔岩图腾","在施法者脚下召唤一个具有点生命值的熔岩图腾，持续d-1秒。图腾每1108188t1秒对1108187a1码范围内的生物造成1108187s1点火焰伤害。","汉化"},
[1108198] = {"雷霆一击","轰击附近的敌人，使其攻击间隔延长%并造成点伤害，持续d。伤害值受攻击强度加成，且此技能会产生额外威胁值。","汉化"},
[1108204] = {"雷霆一击","轰击附近的敌人，使其攻击间隔延长%并造成点伤害，持续d。伤害值受攻击强度加成，且此技能会产生额外威胁值。","汉化"},
[1108205] = {"雷霆一击","轰击附近的敌人，使其攻击间隔延长%并造成点伤害，持续d。伤害值受攻击强度加成，且此技能会产生额外威胁值。","汉化"},
[1108227] = {"火舌图腾","召唤一根具有点生命值的火舌图腾于施法者脚下，使图腾周围1152109a1码范围内的小队和团队成员法术伤害和治疗效果提高1152109s1点，持续d。","汉化"},
[1108232] = {"风怒武器","为萨满的武器灌注强风之力。每次命中有15%的几率触发额外伤害，相当于两次额外攻击（每次造成100%武器伤害+点攻击强度加成）。此效果持续2小时，且每2秒最多触发一次。","汉化"},
[1108235] = {"风怒武器","为萨满的武器灌注强风之力。每次攻击有20%的几率造成额外伤害，造成两次额外攻击外加点攻击强度的伤害。持续30分钟。","汉化"},
[1108249] = {"火舌图腾","召唤一根具有点生命值的火舌图腾于施法者脚下，使图腾周围1152110a1码范围内的小队和团队成员法术伤害和治疗效果提高1152110s1点，持续d。","汉化"},
[1108288] = {"灵魂吸取","吸取目标的灵魂，在d内造成o2点暗影伤害。若目标生命值处于或低于25%，则造成的伤害提高至四倍。如果目标在被吸取期间死亡，并且该目标可提供经验值或荣誉，则施法者将获得一块灵魂碎片。每次“吸取灵魂”对目标造成伤害时，都有一定几率生成一块灵魂碎片。灵魂碎片是施放其他法术所需的材料。","汉化"},
[1108289] = {"灵魂吸取","吸取目标的灵魂，在d内造成o2点暗影伤害。若目标生命值处于或低于25%，则造成的伤害提高至四倍。如果目标在被吸取期间死亡，并且该目标可提供经验值或荣誉，则施法者将获得一块灵魂碎片。每次“吸取灵魂”对目标造成伤害时，都有一定几率生成一块灵魂碎片。灵魂碎片是施放其他法术所需的材料。","汉化"},
[1108400] = {"火球术","投掷一枚火球，造成m1+ppl1到M1+ppl1点火焰伤害，并在d内额外造成o2点火焰伤害。","汉化"},
