[1108623] = {"剔骨","终结技，根据连击点数造成伤害：\n1点：m1+((b1*1)+AP*0.03)*mult-M1+((b1*1)+AP*0.07)*mult点伤害值\n2点：m1+((b1*2)+AP*0.06)*mult-M1+((b1*2)+AP*0.14)*mult点伤害值\n3点：m1+((b1*3)+AP*0.09)*mult-M1+((b1*3)+AP*0.21)*mult点伤害值\n4点：m1+((b1*4)+AP*0.12)*mult-M1+((b1*4)+AP*0.28)*mult点伤害值\n5点：m1+((b1*5)+AP*0.15)*mult-M1+((b1*5)+AP*0.35)*mult点伤害值","汉化"},
[1108624] = {"剔骨","终结技，根据连击点数造成伤害：\n1点：m1+((b1*1)+AP*0.03)*mult-M1+((b1*1)+AP*0.07)*mult点伤害值\n2点：m1+((b1*2)+AP*0.06)*mult-M1+((b1*2)+AP*0.14)*mult点伤害值\n3点：m1+((b1*3)+AP*0.09)*mult-M1+((b1*3)+AP*0.21)*mult点伤害值\n4点：m1+((b1*4)+AP*0.12)*mult-M1+((b1*4)+AP*0.28)*mult点伤害值\n5点：m1+((b1*5)+AP*0.15)*mult-M1+((b1*5)+AP*0.35)*mult点伤害值","汉化"},
[1108631] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值随攻击强度提高。必须处于潜行状态并位于目标背后。获得个连击l点。","汉化"},
[1108632] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值随攻击强度提高。必须处于潜行状态并位于目标背后。获得个连击l点。","汉化"},
