[1108639] = {"割裂","终结技，对目标造成持续伤害，伤害量随你的攻击强度提高。持续时间会根据连击点数量延长：\n1点连击点：在dur1秒内造成(m1+b1*1+0.015*AP)*4点伤害\n2点连击点：在dur2秒内造成(m1+b1*2+0.024*AP)*5点伤害\n3点连击点：在dur3秒内造成(m1+b1*3+0.03*AP)*6点伤害\n4点连击点：在dur4秒内造成(m1+b1*4+0.03428571*AP)*7点伤害\n5点连击点：在dur5秒内造成(m1+b1*5+0.0375*AP)*8点伤害","汉化"},
[1108640] = {"割裂","终结技，对目标造成持续伤害，伤害量随你的攻击强度提高。持续时间会根据连击点数量延长：\n1点连击点：在dur1秒内造成(m1+b1*1+0.015*AP)*4点伤害\n2点连击点：在dur2秒内造成(m1+b1*2+0.024*AP)*5点伤害\n3点连击点：在dur3秒内造成(m1+b1*3+0.03*AP)*6点伤害\n4点连击点：在dur4秒内造成(m1+b1*4+0.03428571*AP)*7点伤害\n5点连击点：在dur5秒内造成(m1+b1*5+0.0375*AP)*8点伤害","汉化"},
