[1122568] = {"凶猛撕咬","终结技。根据连击点造成伤害，并将每点额外能量值(最多额外能量值)转化为f1+AP/410.1点额外伤害。伤害随攻击强度会提高。\n1点：m1+b1*1+0.07*AP-M1+b1*1+0.07*AP点伤害\n2点：m1+b1*2+0.14*AP-M1+b1*2+0.14*AP点伤害\n3点：m1+b1*3+0.21*AP-M1+b1*3+0.21*AP点伤害\n4点：m1+b1*4+0.28*AP-M1+b1*4+0.28*AP点伤害\n5点：m1+b1*5+0.35*AP-M1+b1*5+0.35*AP点伤害","汉化"},
[1122570] = {"割碎","终结技，对目标造成伤害并令其昏迷，且中断非玩家目标正在施放的法术，持续1132747d。根据连击点决定伤害和持续时间：\n1点:b1*1+m1+mw-b1*1+M1+MW点伤害，1秒\n2点:b1*2+m1+mw-b1*2+M1+MW点伤害，2秒\n3点:b1*3+m1+mw-b1*3+M1+MW点伤害，3秒\n4点:b1*4+m1+mw-b1*4+M1+MW点伤害，4秒\n5点:b1*5+m1+mw-b1*5+M1+MW点伤害，5秒","汉化"},
[1122782] = {"法师护甲","使你的所有魔法抗性提高点，在施法时仍保持%的法力恢复速度。有害法术的持续时间降低%。法师同时只能激活一类护甲法术，持续d。","汉化"},
[1122783] = {"法师护甲","使你的所有魔法抗性提高点，在施法时仍保持%的法力恢复速度。有害法术的持续时间降低%。法师同时只能激活一类护甲法术，持续d。","汉化"},
