[1125331] = {"神圣新星","制造一次以施法者为中心的神圣能量爆炸，对半径1125331a1码范围内的所有敌对目标造成1125331s1点神圣伤害，并为半径1125329a1码范围内的所有小队成员恢复1125329s1点生命值。这些效果不产生任何威胁值。","汉化"},
