[1125422] = {"治疗链","为友方目标恢复点生命值，然后跳跃治疗其他附近的目标。如果施放对象是小队成员，则治疗仅会跳跃至小队其他成员。每次跳跃会使治疗效果降低40%。总共治疗x1个目标。","汉化"},
[1125423] = {"治疗链","为友方目标恢复点生命值，然后跳跃治疗其他附近的目标。如果施放对象是小队成员，则治疗仅会跳跃至小队其他成员。每次跳跃会使治疗效果降低40%。总共治疗x1个目标。","汉化"},
[1125431] = {"心灵之火","圣洁的能量充满施法者的体内，提高护甲值点和法术能量点。每次近战或远程伤害击中牧师，将消耗1层能量。可持续d，或者直到n层能量消耗完毕。","汉化"},
