[1125457] = {"烈焰震击","立即灼烧目标，立刻造成点火焰伤害，并在d内额外造成o2点火焰伤害。该持续伤害可以造成爆击，且其触发频率会随施法者的法术急速提升而加快。","汉化"},
[1125464] = {"冰霜震击","立即用冰霜震击目标，造成点冰霜伤害，并使其移动速度降低%，持续d。并产生大量威胁值。","汉化"},
[1125467] = {"噬灵疫病","使目标患上疾病,在d内造成o1点暗影伤害。噬灵疫病伤害的15%治疗施法者，此法术同时只能影响1个目标。","汉化"},
[1125469] = {"闪电之盾","施法者被n个闪电球环绕。当施法者受到法术、近战或远程攻击时，攻击者将受到1126371s1点自然伤害，并消耗一个闪电球。每隔几秒只能触发一次。持续d。萨满一次只能激活一个元素护盾。","汉化"},
[1125472] = {"闪电之盾","施法者被n个闪电球环绕。当施法者受到法术、近战或远程攻击时，攻击者将受到1126372s1点自然伤害，并消耗一个闪电球。每隔几秒只能触发一次。持续d。萨满一次只能激活一个元素护盾。","汉化"},
[1125489] = {"火舌武器","为萨满的武器附魔火焰，使其法术伤害提高1116313s2，并使法术爆击几率提高1155451s1%..每次攻击会根据武器速度造成额外的/77;25488m1到/25;25488M1点火焰伤害，武器越慢造成的火焰伤害越高。此效果持续30分钟。","汉化"},
[1125500] = {"冰封武器","将冰霜注入你的武器，每次命中都有几率造成1125501s2点额外的冰霜伤害，并使目标的移动速度减慢1125501s1%，持续1125501d。该效果持续30分钟，","汉化"},
[1125505] = {"风怒武器","为萨满的武器灌注强风之力。每次攻击有20%的几率造成额外伤害，造成两次额外攻击外加点攻击强度的伤害。持续30分钟。","汉化"},
[1125508] = {"石肤图腾","在施法者脚下召唤一个拥有点生命值的石肤图腾。该图腾保护1125506a1码范围内的小队和团队成员，使其护甲值提高1125506s1点，持续d。","汉化"},
[1125509] = {"石肤图腾","在施法者脚下召唤一个拥有点生命值的石肤图腾。该图腾保护1125507a1码范围内的小队和团队成员，使其护甲值提高1125507s1点，持续d。","汉化"},
[1125525] = {"石爪图腾","在施法者脚下召唤一个具有点生命值的石爪图腾，持续d，嘲讽1125512a1码范围内的生物攻击它。攻击石爪图腾的敌人有1125513h%的几率被击晕1139796d。石爪图腾还保护所有你的图腾，使它们吸收1155278s1点伤害。","汉化"},
[1125528] = {"大地之力图腾","在施法者脚下召唤一个生命值为的大地之力图腾。该图腾会使1125527a1码范围内所有团队和小队成员的力量和敏捷提高1125527s2。持续d。","汉化"},
[1125533] = {"灼热图腾","在你脚下召唤一个具有点生命值的灼热图腾，持续d，它会不断攻击1125530r1码范围内的敌人，造成1125530s1点火焰伤害。","汉化"},
[1125546] = {"火焰新星","使你当前激活的火焰图腾释放出一道火焰波，对图腾1125535a1码范围内的敌人造成1125535s1点火焰伤害。","汉化"},
[1125547] = {"火焰新星","使你当前激活的火焰图腾释放出一道火焰波，对图腾1125537a1码范围内的敌人造成1125537s1点火焰伤害。","汉化"},
[1125552] = {"熔岩图腾","在施法者脚下召唤一个具有点生命值的熔岩图腾，持续d-1秒。图腾每1125551t1秒对1125550a1码范围内的生物造成1125550s1点火焰伤害。","汉化"},
[1125557] = {"火舌图腾","召唤一根具有点生命值的火舌图腾于施法者脚下，使图腾周围1152113a1码范围内的小队和团队成员法术伤害和治疗效果提高1152113s1点，持续d。","汉化"},
[1125560] = {"抗寒图腾","在施法者脚下召唤一个拥有生命值的冰霜抗性图腾，持续d。如果该图腾在1125559a1码范围内，则会为团队和小队成员增加1125559s1的冰霜抗性。","汉化"},
[1125563] = {"抗火图腾","在施法者脚下召唤一个拥有生命值的火焰抗性图腾，持续d。使1125562a1码范围内的所有队伍和团队成员提高1125562s1点火焰抗性。","汉化"},
[1125567] = {"治疗之泉图腾","在施法者脚下召唤一个拥有点生命值的治疗之泉图腾，持续d，每1125566t1秒为1152050a1码范围内的小队成员恢复1125566s1点生命值。","汉化"},
