[1125894] = {"强效智慧祝福","为团队或小队中与目标属于同一职业的所有成员施加强效智慧祝福，在d内每5秒恢复点法力值。\n\n每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1125898] = {"强效王者祝福","使小队或团队中所有与目标职业相同的玩家都获得强效王者祝福的效果，使其所有属性提高%，持续d。每位圣骑士在同时只能给目标施加一种祝福。","汉化"},
[1125899] = {"强效庇护祝福","为团队或小队中与目标属于同一职业的所有成员施加强效庇护祝福，使其在d内所受所有来源的伤害降低%，并使力量和耐力提高%。此外，当目标格挡、招架或躲闪一次近战攻击时，将恢复其最大法力值的1157319s1%。每位圣骑士同时只能对玩家施加一种祝福。","汉化"},
[1125916] = {"强效力量祝福","为与目标同职业的团队或小队所有成员施加强效力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1125918] = {"强效智慧祝福","为团队或小队中与目标属于同一职业的所有成员施加强效智慧祝福，在d内每5秒恢复点法力值。\n\n每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1125956] = {"强化审判","使你的审判法术冷却时间缩短/1000;s1秒。","汉化"},
[1125957] = {"强化审判","使你的审判法术冷却时间缩短/1000;s1秒。","汉化"},
[1125988] = {"以眼还眼","所有对你造成爆击的攻击都会对攻击者造成%的伤害，但最大数值不会超过圣骑士生命值总量的50%。","汉化"},
[1126016] = {"辩护","使圣骑士的伤害性攻击有几率使目标的攻击强度降低1126017s1点，持续1126017d。","汉化"},
[1126022] = {"正义追击","所有缴械效果的持续时间缩短%，并使移动速度和坐骑移动速度提高%。此效果不与其他提高移动速度的效果叠加。","汉化"},
[1126023] = {"正义追击","所有缴械效果的持续时间缩短%，并使移动速度和坐骑移动速度提高%。此效果不与其他提高移动速度的效果叠加。","汉化"},
[1126669] = {"闪避","盗贼的躲闪几率提高%，并使远程攻击命中盗贼的几率降低%持续d。","汉化"},
[1126679] = {"致命投掷","终结技：使目标的移动速度降低%，持续d，并提升投掷武器的伤害：\n1点:m1+(b1*1)+rwb-M1+(b1*1)+RWB点伤害\n2点:m1+(b1*2)+rwb-M1+(b1*2)+RWB点伤害\n3点:m1+(b1*3)+rwb-M1+(b1*3)+RWB点伤害\n4点:m1+(b1*4)+rwb-M1+(b1*4)+RWB点伤害\n5点:m1+(b1*5)+rwb-M1+(b1*5)+RWB点伤害","汉化"},
[1126839] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值随攻击强度提高。必须处于潜行状态并位于目标背后。获得个连击l点。","汉化"},
[1126861] = {"邪恶攻击","立即攻击，造成m1点伤害，并额外造成%正常武器伤害。奖励个连击点数。","汉化"},
[1126862] = {"邪恶攻击","立即攻击，造成m1点伤害，并额外造成%正常武器伤害。奖励个连击点数。","汉化"},
[1126863] = {"背刺","背刺目标，造成m2%武器伤害外加m1*1.5点伤害。必须在目标背后发动。主手需装备匕首。奖励个连击点数。","汉化"},
[1126864] = {"出血","立刻对目标造成%武器伤害（若装备匕首则为m2*1.45%），并使目标出血，使其受到的物理伤害最多提高bonus。效果持续n次触发或d。获得1个连击点。","汉化"},
[1126865] = {"剔骨","终结技，根据连击点数造成伤害：\n1点：m1+((b1*1)+AP*0.03)*mult-M1+((b1*1)+AP*0.07)*mult点伤害值\n2点：m1+((b1*2)+AP*0.06)*mult-M1+((b1*2)+AP*0.14)*mult点伤害值\n3点：m1+((b1*3)+AP*0.09)*mult-M1+((b1*3)+AP*0.21)*mult点伤害值\n4点：m1+((b1*4)+AP*0.12)*mult-M1+((b1*4)+AP*0.28)*mult点伤害值\n5点：m1+((b1*5)+AP*0.15)*mult-M1+((b1*5)+AP*0.35)*mult点伤害值","汉化"},
[1126867] = {"割裂","终结技，对目标造成持续伤害，伤害量随你的攻击强度提高。持续时间会根据连击点数量延长：\n1点连击点：在dur1秒内造成(m1+b1*1+0.015*AP)*4点伤害\n2点连击点：在dur2秒内造成(m1+b1*2+0.024*AP)*5点伤害\n3点连击点：在dur3秒内造成(m1+b1*3+0.03*AP)*6点伤害\n4点连击点：在dur4秒内造成(m1+b1*4+0.03428571*AP)*7点伤害\n5点连击点：在dur5秒内造成(m1+b1*5+0.0375*AP)*8点伤害","汉化"},
[1126884] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值随攻击强度提高。必须处于潜行状态并位于目标背后。获得个连击l点。","汉化"},
[1126889] = {"消失","使盗贼消失并进入强化的潜行状态，持续1111329d。并且移除移动限制效果。比消失（等级2）更有效。","汉化"},
[1126978] = {"治疗之触","治疗一名友方目标min到max点生命值。","汉化"},
[1126979] = {"治疗之触","治疗一名友方目标min到max点生命值。","汉化"},
[1126980] = {"愈合","为一名友方目标治疗点生命值，并在d内额外治疗m2*7*mult点生命值。","汉化"},
[1126981] = {"回春术","治疗目标m1*5*mult点生命值，持续d。","汉化"},
[1126982] = {"回春术","治疗目标m1*5*mult点生命值，持续d。","汉化"},
[1126983] = {"宁静","每t2秒使附近所有小队成员的生命值恢复点。持续d。德鲁伊必须引导维持此法术。","汉化"},
[1126984] = {"愤怒","对目标造成点自然伤害。","汉化"},
[1126985] = {"愤怒","对目标造成点自然伤害。","汉化"},
[1126986] = {"星火术","对目标造成点奥术伤害。","汉化"},
[1126987] = {"月火术","灼烧敌人造成点奥术伤害，并在d内额外造成m1*4*mult点奥术伤害。","汉化"},
[1126988] = {"月火术","灼烧敌人造成点奥术伤害，并在d内额外造成m1*4*mult点奥术伤害。","汉化"},
[1126989] = {"纠缠根须","将目标定在原地，并在d内造成o2点自然伤害。造成的伤害可能会中断此效果。","汉化"},
[1126990] = {"野性印记","使友方目标的护甲值提高点，所有属性提高点，所有抗性提高点，持续d。","汉化"},
[1126991] = {"野性赐福","使所有队伍和团队成员获得野性赐福的效果，护甲值提高点，所有属性提高点，所有抗性提高点。持续d。","汉化"},
[1126992] = {"荆棘术","使友方目标身上环绕着荆棘，对任何命中其的攻击者造成点自然伤害，持续d。","汉化"},
[1126994] = {"复生","让死去的目标复活，并恢复点生命值和q点法力值。","汉化"},
[1126995] = {"安抚动物","安抚目标野兽，使其警戒范围减少码。仅影响85级或以下的野兽和龙类目标。持续d。","汉化"},
[1126996] = {"重殴","强力攻击，使近战攻击伤害提高点，并造成大量的威胁值。所有提高流血伤害的效果可同时提高重殴伤害。","汉化"},
[1126997] = {"横扫（熊）","横扫附近的敌人，造成点伤害。伤害随攻击强度提高。","汉化"},
[1126998] = {"挫志咆哮","德鲁伊发出咆哮，使附近所有敌人的近战攻击强度降低点，持续d。","汉化"},
[1127000] = {"爪击","爪击敌人，造成额外点额外伤害。奖励个连击点数。","汉化"},
[1127001] = {"撕碎","对目标进行撕碎，造成%伤害外加236点伤害。必须在目标背后施放。获得连击点数。增加流血伤害的效果也会增加撕碎伤害。","汉化"},
[1127002] = {"撕碎","对目标进行撕碎，造成%伤害外加m1*m3/100点伤害。必须在目标背后施放。获得连击点数。增加流血伤害的效果也会增加撕碎伤害。","汉化"},
[1127003] = {"斜掠","斜掠目标，造成AP/100+m1点流血伤害，并在d内额外造成m2*3+AP*0.18点伤害。奖励个连击点数。","汉化"},
[1127004] = {"畏縮","畏缩，不造成任何伤害，但会大幅降低你的威胁值，使敌人更不容易攻击你。","汉化"},
[1127005] = {"毁灭","毁灭目标，对其造成%伤害加上m1*m2/100额外伤害。必须处于潜伏状态并且位于目标背后。奖励点连击点数。","汉化"},
[1127006] = {"突袭","突袭敌人，使目标昏迷1127006d，并在1127007d内造成1127007o1点伤害。必须处于潜伏状态。奖励1127006s3点连击点数。","汉化"},
[1127008] = {"割裂（豹）","终结技，使目标在一段时间内受到持续的伤害。根据连击点数和你的攻击强度决定伤害量：\n1点：d内(m1+b1*1+0.01*AP)*dur点伤害。\n2点：d内(m1+b1*2+0.02*AP)*dur点伤害。\n3点：d内(m1+b1*3+0.03*AP)*dur点伤害。\n4点：d内(m1+b1*4+0.04*AP)*dur点伤害。\n5点：d内(m1+b1*5+0.05*AP)*dur点伤害。","汉化"},
[1127009] = {"自然之握","激活时，每当敌人攻击施法者，都有h%几率被纠缠根须（等级7）影响。可生效n次。持续d。","汉化"},
[1127012] = {"飓风","在目标区域召唤一场猛烈风暴，每1127012t3秒对敌人造成1142230s1点自然伤害，并减少其移动速度1154831s1%，同时使敌人的攻击间隔延长1127012s2%。持续1127012d。德鲁伊必须引导以维持该法术。","汉化"},
[1127013] = {"虫群","敌人被飞虫围绕，使其近战和远程攻击命中率降低%，并在d内受到总计o1点自然伤害。","汉化"},
[1127014] = {"猛禽一击","强力攻击，使近战攻击造成的伤害提高点。","汉化"},
[1127016] = {"毒蛇钉刺","钉刺目标，在d内对其造成RAP*0.2+m1*d/3点自然伤害。每位猎人同时只能对一个目标使用一种钉刺。","汉化"},
[1127019] = {"奥术射击","一次瞬发射击，造成RAP*0.15+m1点奥术伤害。","汉化"},
[1127021] = {"多重射击","发射数枚弹药，命中x1个目标，每个目标额外受到点伤害。","汉化"},
[1127023] = {"献祭陷阱","放置一个火焰陷阱，燃烧第一个接近的敌人，在1127024d内对其造成(RAP*(mult/100)+1127024m1)*duration点火焰伤害。陷阱存在d。同一时间只能激活一个陷阱。","汉化"},
[1127025] = {"爆炸陷阱","放置一个火焰陷阱，当敌人接近时会爆炸，造成RAP*0.1+1127026m1到RAP*0.1+1127026M1点火焰伤害，并对1127026a1码范围内的所有敌人在1127026d内额外造成1127026m2*10+RAP点火焰伤害。陷阱持续d。同时只能激活一个陷阱。","汉化"},
[1127044] = {"雄鹰守护","猎人获得雄鹰的守护，提高远程攻击强度点。同时只能激活一种守护。","汉化"},
[1127045] = {"野性守护","猎人和a1码内的小队和团队成员获得野性守护，使自然抗性提高点。同时只能激活一种守护。","汉化"},
[1127046] = {"治疗宠物","在d内为你的宠物治疗total点生命值。","汉化"},
[1127065] = {"瞄准射击","一次瞄准射击，造成m3%远程武器伤害外加点伤害，并使目标受到的治疗效果降低%，持续d。","汉化"},
[1127067] = {"反击","在招架敌人的攻击后触发的一次打击。此攻击造成AP*0.5+m1点伤害，并在触发招架时使目标无法移动，持续d。此攻击无法被格挡、躲闪或招架。","汉化"},
[1127068] = {"翼龙钉刺","钉刺射击，使目标沉睡d。任何伤害都会取消效果。目标醒来时，毒刺会在1127069d内造成1127069o1点自然伤害。每个猎人每次只能对目标激活一个钉刺。","汉化"},
[1127070] = {"火球术","投掷一枚火球，造成的火焰伤害，并在d内额外造成o2火焰伤害。","汉化"},
[1127071] = {"寒冰箭","向敌人发射一枚寒冰箭，造成m2*mult到M2*mult点冰霜伤害，并使其移动速度减少%，持续d。","汉化"},
[1127072] = {"寒冰箭","向敌人发射一枚寒冰箭，造成m2*mult到M2*mult点冰霜伤害，并使其移动速度减少%，持续d。","汉化"},
[1127073] = {"灼烧","灼烧敌人，对其造成点火焰伤害。","汉化"},
[1127074] = {"灼烧","灼烧敌人，对其造成点火焰伤害。","汉化"},
[1127078] = {"火焰冲击","施放火焰冲击敌人，对其造成点火焰伤害。","汉化"},
[1127079] = {"火焰冲击","施放火焰冲击敌人，对其造成点火焰伤害。","汉化"},
[1127080] = {"奥爆术","制造一次以施法者为中心的魔法爆炸，对半径a1码范围内的所有目标造成点奥术伤害。","汉化"},
[1127082] = {"奥爆术","制造一次以施法者为中心的魔法爆炸，对半径a1码范围内的所有目标造成点奥术伤害。","汉化"},
[1127087] = {"冰锥术","施法者前方锥形区域内的目标受到m2*mult到M2*mult点冰霜伤害，并且速度降低%，持续d。","汉化"},
[1127088] = {"冰霜新星","冲击施法者附近的所有敌人，造成m1*mult到M1*mult点冰霜伤害，并将其冻结在原地，最多持续d。对被冻结的目标造成伤害可能打断这个效果。","汉化"},
[1127090] = {"造水术","用魔法合成m1+ppl1瓶魔法冰川水以供法师和盟友饮用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。","汉化"},
[1127101] = {"制造法力宝石","制造一颗魔法玉石，使用后可以立刻恢复1127103s1点法力值，可使用3次。","汉化"},
[1127124] = {"冰甲术","增加1s的护甲和的冰霜抗性。如果敌人攻击施法者，他们的移动速度会减慢1107321s1%，攻击间隔时间会增加1107321s2%，持续1107321d。法师在任何时候只能激活一种护甲法术。持续d。","汉化"},
[1127125] = {"法师护甲","使你的所有魔法抗性提高点，在施法时仍保持%的法力恢复速度。有害法术的持续时间降低%。法师同时只能激活一类护甲法术，持续d。","汉化"},
[1127126] = {"奥术智慧","使目标的智力提高点，持续d。","汉化"},
[1127127] = {"奥术光辉","魔法的光辉笼罩着所有小队和团队成员，使他们的智力提高点，持续d。","汉化"},
[1127128] = {"防护火焰结界","吸收点火焰伤害，持续d。","汉化"},
[1127130] = {"魔法增效","魔法增效对目标小队成员使用时，使其受到的魔法伤害提高，受到的治疗效果提高，持续d。","汉化"},
[1127131] = {"法力护盾","吸收点伤害，同时消耗法力。每吸收1点伤害，就消耗e点法力，持续d。","汉化"},
[1127132] = {"炎爆术","发射一枚巨大的火球，对目标造成点火焰伤害，并且额外在d内造成o2点火焰伤害。","汉化"},
[1127133] = {"冲击波","施法者放出一道火焰冲击波，所有被冲击波触及的敌人都会受到点火焰伤害，并将他们击退和晕眩，持续d。","汉化"},
[1127134] = {"寒冰护体","立即为你加上魔法护盾，吸收点伤害，持续d。护盾持续期间，施法时间不会因受到伤害而延迟。","汉化"},
[1127135] = {"圣光术","治疗友方目标点生命值。","汉化"},
[1127136] = {"圣光术","治疗友方目标点生命值。","汉化"},
[1127137] = {"圣光闪现","治疗一名友方目标点生命值。","汉化"},
[1127138] = {"驱邪术","对敌方目标造成M1+0.15*SPH+0.15*AP至M1+0.15*SPH+0.15*AP的神圣伤害。如果目标是亡灵或恶魔，则始终会暴击。","汉化"},
[1127139] = {"神圣愤怒","向四面八方发射神圣能量箭，造成m1+0.07*SPH+0.07*AP到M1+0.07*SPH+0.07*AP点神圣伤害，并使a1码范围内的所有亡灵和恶魔目标昏迷d。","汉化"},
[1127140] = {"力量祝福","对友方目标施加祝福，使其攻击强度提高，持续d。每名圣骑士在同一时间只能对玩家施加一种祝福。","汉化"},
[1127141] = {"强效力量祝福","为与目标同职业的团队或小队所有成员施加强效力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1127142] = {"智慧祝福","为友方目标施加祝福，在d内每5秒恢复点法力值。每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1127143] = {"强效智慧祝福","为团队或小队中与目标属于同一职业的所有成员施加强效智慧祝福，在d内每5秒恢复点法力值。\n\n每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1127149] = {"虔诚光环","为a1码内的小队和团队成员提供点额外护甲。每位圣骑士同时只能开启一种光环。","汉化"},
[1127150] = {"惩戒光环","对任何攻击a1码范围内队伍或团队成员的敌人造成点神圣伤害。每名圣骑士在同一时间只能对玩家施加一种光环。","汉化"},
[1127151] = {"暗影抗性光环","为a1码范围内的所有小队和团队成员提供点额外暗影抗性。每位圣骑士同时只能开启一种光环。","汉化"},
[1127152] = {"冰霜抗性光环","为a1码范围内的所有小队和团队成员提供点额外冰霜抗性。每位圣骑士在同一时间内只能对玩家施加一种光环。","汉化"},
[1127153] = {"火焰抗性光环","为a1码范围内的所有队伍和团队成员提供点额外火焰抗性。每个圣骑士在同一时间内只能开启一种光环。","汉化"},
[1127154] = {"圣疗术","治疗一个友方目标，恢复相当于圣骑士最大生命值的生命值，并恢复其点法力值。若对自身使用，圣骑士在1125771d内将无法再次成为圣盾术、圣佑术、保护之手或自我施放的圣疗术的目标，且在使用复仇之怒后的1161987d内无法对自身使用该技能。","汉化"},
[1127174] = {"神圣震击","用神圣能量轰击目标，对敌人造成1127176s1点神圣伤害，或对盟友治疗1127175s1点生命值。","汉化"},
[1127179] = {"神圣之盾","格挡几率提高%，持续d。并在激活期间每次格挡攻击造成点神圣伤害。每次格挡消耗一次充能。有n次充能。","汉化"},
[1127180] = {"愤怒之锤","投掷一把锤子打击敌人，造成m1+0.15*SPH+0.15*AP至M1+0.15*SPH+0.15*AP点神圣伤害。仅能对生命值低于20%的敌人使用。","汉化"},
[1127209] = {"暗影箭","向敌人射出一支暗影箭，造成点暗影伤害。","汉化"},
[1127210] = {"灼热之痛","对敌方目标施加灼热之痛，造成点火焰伤害。该技能会产生大量仇恨值。","汉化"},
[1127213] = {"地狱烈焰","点燃施法者周围的区域，每1127213t2秒对自身造成1127213s2点火焰伤害，并对附近所有敌人造成1127214s1点火焰伤害，持续1127213d。","汉化"},
[1127215] = {"献祭","立即对敌人造成点火焰伤害，并在d内造成额外o1点火焰伤害。","汉化"},
[1127216] = {"腐蚀术","腐蚀目标，在d内造成o1点暗影伤害。","汉化"},
[1127217] = {"灵魂吸取","吸取目标的灵魂，在d内造成o2点暗影伤害。若目标生命值处于或低于25%，则造成的伤害提高至四倍。如果目标在被吸取期间死亡，并且该目标可提供经验值或荣誉，则施法者将获得一块灵魂碎片。每次“吸取灵魂”对目标造成伤害时，都有一定几率生成一块灵魂碎片。灵魂碎片是施放其他法术所需的材料。","汉化"},
[1127218] = {"痛苦诅咒","对目标施加痛苦诅咒，使其在d内受到o1点暗影伤害。这种伤害在初期会缓慢生效，但是会在作用效果期间不断加速，直到结束。每个术士对同一个目标只能施加一种诅咒。","汉化"},
[1127219] = {"吸取生命","每t1秒吸取目标点生命值，并将其转移给施法者，持续d。","汉化"},
[1127220] = {"吸取生命","每t1秒吸取目标点生命值，并将其转移给施法者，持续d。","汉化"},
[1127222] = {"生命分流","将m1+ppl1点生命值转化为m1*mult+SPS*.5*mult+ppl1点法力值。法术强度会提高所转化的法力值。","汉化"},
[1127223] = {"死亡缠绕","使敌方目标在恐惧中奔跑d，并造成暗影伤害。造成伤害时，自身恢复100*e1%的生命。","汉化"},
[1127224] = {"虚弱诅咒","目标的近战攻击力减少，护甲减少%,持续d。每个术士只能对一个目标使用一个诅咒。","汉化"},
[1127228] = {"元素诅咒","诅咒目标d，降低奥术，火焰，冰霜，自然和暗影的抗性，并增加魔法伤害。每个术士只能对一个目标施放一个诅咒。","汉化"},
[1127230] = {"制造治疗石","制造一块极效治疗石，使用后可立即恢复1127235s1点生命值。\n\n召唤出的物品若下线超过15分钟将会消失。","汉化"},
[1127238] = {"制造灵魂石","制造一个极效灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死亡。他可以依靠灵魂石复活，并恢复1127240s1点生命值和1127240q1点法力值。\n制造的物品会在登出游戏超过15分钟之后消失。","汉化"},
[1127243] = {"腐蚀之种","向敌方目标植入恶魔种子，对其造成1127243o1点暗影伤害，持续1127243d。当目标受到总计1127243s2伤害或死亡时，种子会对目标周围1127285a1码内的所有敌人造成1127285s1的暗影伤害。每个术士只能对一个目标施放一个腐化法术。","汉化"},
[1127250] = {"制造火焰石","附魔目标武器后，直接法术伤害提高1%，法术暴击等级提高1154718s3，持续1小时。","汉化"},
[1127259] = {"生命通道","施法者引导期间，每秒为宠物恢复点生命值，持续d。","汉化"},
[1127260] = {"恶魔护甲","保护施法者，护甲值提高点，法术和效果产生的生命值恢复效果提高点，法术和效果产生的生命值恢复效果提高%。同一时间内术士只能激活一种护甲类法术。持续d。","汉化"},
[1127263] = {"暗影灼烧","立即对目标造成点暗影烈焰伤害。若目标在1129341d内死亡且提供经验或荣誉值，施法者将获得一块灵魂碎片。","汉化"},
[1127265] = {"黑暗契约","吸取你所召唤恶魔的m1+sp*0.96点法力值，并100%返还给你。","汉化"},
[1127441] = {"伏击","伏击目标，对其造成m2%武器伤害再加m1*2.75点伤害。必须处于潜行状态并位于目标背后。需要主手装备匕首。奖励个连击点。","汉化"},
[1127448] = {"佯攻","施展佯攻，不会造成任何伤害，但大幅降低你的仇恨值，使敌人不太可能攻击你。此外，在d内，减少你受到的范围攻击伤害%。","汉化"},
[1127681] = {"精神祷言","圣洁的能量充满目标的小队与团队成员，使其精神属性提高点，持续d。","汉化"},
[1127683] = {"防护暗影祷言","能量灌注目标所在小队和团队成员，使其暗影抗性提高，持续d。","汉化"},
[1127789] = {"神圣延伸","使你的惩击和神圣之火法术的射程增加，并使治疗祷言、神圣新星、神圣赞美诗和治疗之环法术的作用半径扩大%。","汉化"},
[1127790] = {"神圣延伸","使你的惩击和神圣之火法术的射程增加，并使治疗祷言、神圣新星、神圣赞美诗和治疗之环法术的作用半径扩大%。","汉化"},
[1127799] = {"神圣新星","制造一次以施法者为中心的神圣能量爆炸，对半径1127799a1码范围内的所有敌对目标造成1127799s1点神圣伤害，并为半径1127803a1码范围内的所有小队成员恢复1127803s1点生命值。这些效果不产生任何威胁值。","汉化"},
[1127800] = {"神圣新星","制造一次以施法者为中心的神圣能量爆炸，对半径1127800a1码范围内的所有敌对目标造成1127800s1点神圣伤害，并为半径1127804a1码范围内的所有小队成员恢复1127804s1点生命值。这些效果不产生任何威胁值。","汉化"},
