[1127811] = {"神恩回复","在遭受近战或远程爆击之后，神恩回复会为你恢复所受伤害的%，持续1127818d。效果期间再次受到爆击会提高治疗量。","汉化"},
[1127815] = {"神恩回复","在遭受近战或远程爆击之后，神恩回复会为你恢复所受伤害的%，持续1127818d。效果期间再次受到爆击会提高治疗量。","汉化"},
