[1148492] = {"丛林之王","在熊形态或巨熊形态中使用你的激怒时，你的伤害提高%，同时你的猛虎之怒也会立即恢复点能量值。此外，熊形态、豹形态和巨熊形态的法力值消耗降低%。","汉化"},
