[1148500] = {"生命之种","当你使用迅捷治愈，愈合，滋养或治疗之触法术对目标进行重伤治疗时，你有h%的几率在目标身上种下一个生命之种，治疗量为%。生命之种会在目标下次受到攻击时绽放。持续1148504d。","汉化"},
