[1148516] = {"月蚀","当你的星火术打出爆击之后，有h1%的几率令愤怒的伤害提高1148517s1%。当你的愤怒打出爆击之后，有h*0.6%的几率令星火术的爆击几率提高1148518s1%。每个效果持续1148518d，并且有秒的分隔冷却时间，两种效果不能同时触发。","汉化"},
