[1148572] = {"撕碎","对目标进行撕碎，造成%伤害外加m1*m3/100点伤害。必须在目标背后施放。获得连击点数。增加流血伤害的效果也会增加撕碎伤害。","汉化"},
[1148573] = {"斜掠","斜掠目标，造成AP/100+m1点流血伤害，并在d内额外造成m2*3+AP*0.18点伤害。奖励个连击点数。","汉化"},
