[1148578] = {"毁灭","毁灭目标，对其造成%伤害加上m1*m2/100额外伤害。必须处于潜伏状态并且位于目标背后。奖励点连击点数。","汉化"},
[1148579] = {"毁灭","毁灭目标，对其造成%伤害加上m1*m2/100额外伤害。必须处于潜伏状态并且位于目标背后。奖励点连击点数。","汉化"},
