[1148637] = {"邪恶攻击","立即攻击，造成m1点伤害，并额外造成%正常武器伤害。奖励个连击点数。","汉化"},
[1148638] = {"邪恶攻击","立即攻击，造成m1点伤害，并额外造成%正常武器伤害。奖励个连击点数。","汉化"},
[1148656] = {"背刺","背刺目标，造成m2%武器伤害外加m1*1.5点伤害。必须在目标背后发动。主手需装备匕首。奖励个连击点数。","汉化"},
[1148657] = {"背刺","背刺目标，造成m2%武器伤害外加m1*1.5点伤害。必须在目标背后发动。主手需装备匕首。奖励个连击点数。","汉化"},
[1148658] = {"佯攻","施展佯攻，不会造成任何伤害，但大幅降低你的仇恨值，使敌人不太可能攻击你。此外，在d内，减少你受到的范围攻击伤害%。","汉化"},
[1148659] = {"佯攻","施展佯攻，不会造成任何伤害，但大幅降低你的仇恨值，使敌人不太可能攻击你。此外，在d内，减少你受到的范围攻击伤害%。","汉化"},
[1148660] = {"出血","立刻对目标造成%武器伤害（若装备匕首则为m2*1.45%），并使目标出血，使其受到的物理伤害最多提高bonus。效果持续n次触发或d。获得1个连击点。","汉化"},
[1148663] = {"毁伤","立即用两把武器进行攻击，造成percent%的武器伤害，并且每把武器额外增加1148662s1点伤害。对中毒目标的伤害提高20%。获得2个连击点数。","汉化"},
[1148666] = {"毁伤","立即用两把武器进行攻击，造成percent%的武器伤害，并且每把武器额外增加1148665m1点伤害。对中毒目标的伤害提高20%。获得2个连击点数。","汉化"},
[1148667] = {"剔骨","终结技，根据连击点数造成伤害：\n1点：m1+((b1*1)+AP*0.03)*mult-M1+((b1*1)+AP*0.07)*mult点伤害值\n2点：m1+((b1*2)+AP*0.06)*mult-M1+((b1*2)+AP*0.14)*mult点伤害值\n3点：m1+((b1*3)+AP*0.09)*mult-M1+((b1*3)+AP*0.21)*mult点伤害值\n4点：m1+((b1*4)+AP*0.12)*mult-M1+((b1*4)+AP*0.28)*mult点伤害值\n5点：m1+((b1*5)+AP*0.15)*mult-M1+((b1*5)+AP*0.35)*mult点伤害值","汉化"},
[1148668] = {"剔骨","终结技，根据连击点数造成伤害：\n1点：m1+((b1*1)+AP*0.03)*mult-M1+((b1*1)+AP*0.07)*mult点伤害值\n2点：m1+((b1*2)+AP*0.06)*mult-M1+((b1*2)+AP*0.14)*mult点伤害值\n3点：m1+((b1*3)+AP*0.09)*mult-M1+((b1*3)+AP*0.21)*mult点伤害值\n4点：m1+((b1*4)+AP*0.12)*mult-M1+((b1*4)+AP*0.28)*mult点伤害值\n5点：m1+((b1*5)+AP*0.15)*mult-M1+((b1*5)+AP*0.35)*mult点伤害值","汉化"},
[1148671] = {"割裂","终结技，对目标造成持续伤害，伤害量随你的攻击强度提高。持续时间会根据连击点数量延长：\n1点连击点：在dur1秒内造成(m1+b1*1+0.015*AP)*4点伤害\n2点连击点：在dur2秒内造成(m1+b1*2+0.024*AP)*5点伤害\n3点连击点：在dur3秒内造成(m1+b1*3+0.03*AP)*6点伤害\n4点连击点：在dur4秒内造成(m1+b1*4+0.03428571*AP)*7点伤害\n5点连击点：在dur5秒内造成(m1+b1*5+0.0375*AP)*8点伤害","汉化"},
[1148672] = {"割裂","终结技，对目标造成持续伤害，伤害量随你的攻击强度提高。持续时间会根据连击点数量延长：\n1点连击点：在dur1秒内造成(m1+b1*1+0.015*AP)*4点伤害\n2点连击点：在dur2秒内造成(m1+b1*2+0.024*AP)*5点伤害\n3点连击点：在dur3秒内造成(m1+b1*3+0.03*AP)*6点伤害\n4点连击点：在dur4秒内造成(m1+b1*4+0.03428571*AP)*7点伤害\n5点连击点：在dur5秒内造成(m1+b1*5+0.0375*AP)*8点伤害","汉化"},
[1148673] = {"致命投掷","终结技：使目标的移动速度降低%，持续d，并提升投掷武器的伤害：\n1点:m1+(b1*1)+rwb-M1+(b1*1)+RWB点伤害\n2点:m1+(b1*2)+rwb-M1+(b1*2)+RWB点伤害\n3点:m1+(b1*3)+rwb-M1+(b1*3)+RWB点伤害\n4点:m1+(b1*4)+rwb-M1+(b1*4)+RWB点伤害\n5点:m1+(b1*5)+rwb-M1+(b1*5)+RWB点伤害","汉化"},
[1148674] = {"致命投掷","终结技：使目标的移动速度降低%，持续d，并提升投掷武器的伤害：\n1点:m1+(b1*1)+rwb-M1+(b1*1)+RWB点伤害\n2点:m1+(b1*2)+rwb-M1+(b1*2)+RWB点伤害\n3点:m1+(b1*3)+rwb-M1+(b1*3)+RWB点伤害\n4点:m1+(b1*4)+rwb-M1+(b1*4)+RWB点伤害\n5点:m1+(b1*5)+rwb-M1+(b1*5)+RWB点伤害","汉化"},
[1148675] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值随攻击强度提高。必须处于潜行状态并位于目标背后。获得个连击l点。","汉化"},
[1148676] = {"绞喉","用绞喉袭击敌人，使其沉默1101330d，并在d内造成(m1+AP*0.07)*6点伤害，伤害值受攻击强度加成。必须处于潜行状态并位于目标身后。获得个连击l点。","汉化"},
[1148679] = {"肆虐","立即用两把武器进行攻击，造成percent%的武器伤害，并且每把武器额外增加1148678m1点伤害。对中毒目标的伤害提高20%。获得2个连击点数。","汉化"},
[1148689] = {"伏击","伏击目标，对其造成m2%武器伤害再加m1*2.75点伤害。必须处于潜行状态并位于目标背后。需要主手装备匕首。奖励个连击点。","汉化"},
[1148690] = {"伏击","伏击目标，对其造成m2%武器伤害再加m1*2.75点伤害。必须处于潜行状态并位于目标背后。需要主手装备匕首。奖励个连击点。","汉化"},
[1148691] = {"伏击","伏击目标，对其造成m2%武器伤害再加m1*2.75点伤害。必须处于潜行状态并位于目标背后。需要主手装备匕首。奖励个连击点。","汉化"},
[1148707] = {"反魔法护罩","死亡骑士被一个反魔法护罩包围，吸收有害法术造成的伤害（最多可吸收相当于死亡骑士生命值%的伤害），并防止有害魔法效果的附加在死亡骑士身上。反魔法护罩吸收的伤害会为死亡骑士提供额外符文能量。持续1148707d。","汉化"},
[1148721] = {"血液沸腾","使周围半径a1码范围内所有敌人的血液沸腾，造成点暗影伤害。对感染了血之疫病或冰霜疫病的目标造成额外伤害。","汉化"},
[1148743] = {"死亡契约","牺牲一名亡灵爪牙，为死亡骑士恢复%的生命值。这个治疗效果不能爆击。","汉化"},
[1148781] = {"圣光术","治疗友方目标m1+ppl1+BH*1点生命值。","汉化"},
[1148782] = {"圣光术","治疗友方目标m1+ppl1+BH*1点生命值。","汉化"},
[1148784] = {"圣光闪现","治疗一名友方目标m1+ppl1+BH*0.6点生命值。","汉化"},
[1148785] = {"圣光闪现","治疗一名友方目标m1+ppl1+BH*0.6点生命值。","汉化"},
[1148788] = {"圣疗术","治疗一个友方目标，恢复相当于圣骑士最大生命值的生命值，并恢复其点法力值。若对自身使用，圣骑士在1125771d内将无法再次成为圣盾术、圣佑术、保护之手或自我施放的圣疗术的目标，且在使用复仇之怒后的1161987d内无法对自身使用该技能。","汉化"},
[1148792] = {"冰封坚韧","","汉化"},
[1148800] = {"驱邪术","对敌方目标造成M1+0.15*SPH+0.15*AP至M1+0.15*SPH+0.15*AP的神圣伤害。如果目标是亡灵或恶魔，则始终会暴击。","汉化"},
[1148801] = {"驱邪术","对敌方目标造成M1+0.15*SPH+0.15*AP至M1+0.15*SPH+0.15*AP的神圣伤害。如果目标是亡灵或恶魔，则始终会暴击。","汉化"},
[1148805] = {"愤怒之锤","投掷一把锤子打击敌人，造成m1+0.15*SPH+0.15*AP至M1+0.15*SPH+0.15*AP点神圣伤害。仅能对生命值低于20%的敌人使用。","汉化"},
[1148806] = {"愤怒之锤","投掷一把锤子打击敌人，造成m1+0.15*SPH+0.15*AP至M1+0.15*SPH+0.15*AP点神圣伤害。仅能对生命值低于20%的敌人使用。","汉化"},
[1148816] = {"神圣愤怒","向四面八方发射神圣能量箭，造成m1+0.07*SPH+0.07*AP到M1+0.07*SPH+0.07*AP点神圣伤害，并使a1码范围内的所有亡灵和恶魔目标昏迷d。","汉化"},
[1148817] = {"神圣愤怒","向四面八方发射神圣能量箭，造成m1+0.07*SPH+0.07*AP到M1+0.07*SPH+0.07*AP点神圣伤害，并使a1码范围内的所有亡灵和恶魔目标昏迷d。","汉化"},
[1148824] = {"神圣震击","用神圣能量轰击目标，对敌人造成1148822s1点神圣伤害，或对盟友治疗1148820s1点生命值。","汉化"},
[1148825] = {"神圣震击","用神圣能量轰击目标，对敌人造成1148823s1点神圣伤害，或对盟友治疗1148821s1点生命值。","汉化"},
[1148826] = {"复仇者之盾","向敌人投掷一枚神圣之盾，造成m1+0.07*SPH+0.07*AP到M1+0.07*SPH+0.07*AP点神圣伤害，使其眩晕，然后弹射到附近的其他敌人身上。总共影响x1个目标。持续d。","汉化"},
[1148827] = {"复仇者之盾","向敌人投掷一枚神圣之盾，造成m1+0.07*SPH+0.07*AP到M1+0.07*SPH+0.07*AP点神圣伤害，使其眩晕，然后弹射到附近的其他敌人身上。总共影响x1个目标。持续d。","汉化"},
[1148931] = {"力量祝福","对友方目标施加祝福，使其攻击强度提高，持续d。每名圣骑士在同一时间只能对玩家施加一种祝福。","汉化"},
[1148932] = {"力量祝福","对友方目标施加祝福，使其攻击强度提高，持续d。每名圣骑士在同一时间只能对玩家施加一种祝福。","汉化"},
[1148933] = {"强效力量祝福","为与目标同职业的团队或小队所有成员施加强效力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1148934] = {"强效力量祝福","为与目标同职业的团队或小队所有成员施加强效力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1148935] = {"智慧祝福","为友方目标施加祝福，在d内每5秒恢复点法力值。每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1148936] = {"智慧祝福","为友方目标施加祝福，在d内每5秒恢复点法力值。每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1148937] = {"强效智慧祝福","为团队或小队中与目标属于同一职业的所有成员施加强效智慧祝福，在d内每5秒恢复点法力值。\n\n每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1148938] = {"强效智慧祝福","为团队或小队中与目标属于同一职业的所有成员施加强效智慧祝福，在d内每5秒恢复点法力值。\n\n每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1148941] = {"虔诚光环","为a1码内的小队和团队成员提供点额外护甲。每位圣骑士同时只能开启一种光环。","汉化"},
[1148942] = {"虔诚光环","为a1码内的小队和团队成员提供点额外护甲。每位圣骑士同时只能开启一种光环。","汉化"},
[1148943] = {"暗影抗性光环","为a1码范围内的所有小队和团队成员提供点额外暗影抗性。每位圣骑士同时只能开启一种光环。","汉化"},
[1148945] = {"冰霜抗性光环","为a1码范围内的所有小队和团队成员提供点额外冰霜抗性。每位圣骑士在同一时间内只能对玩家施加一种光环。","汉化"},
[1148947] = {"火焰抗性光环","为a1码范围内的所有队伍和团队成员提供点额外火焰抗性。每个圣骑士在同一时间内只能开启一种光环。","汉化"},
[1148949] = {"救赎","复活一名死去的玩家，复活后该玩家拥有点生命值和q1点法力值。无法在战斗中施放。","汉化"},
[1148950] = {"救赎","复活一名死去的玩家，复活后该玩家拥有点生命值和q1点法力值。无法在战斗中施放。","汉化"},
[1148951] = {"神圣之盾","格挡几率提高%，持续d。并在激活期间每次格挡攻击造成点神圣伤害。每次格挡消耗一次充能。有n次充能。","汉化"},
[1148952] = {"神圣之盾","格挡几率提高%，持续d。并在激活期间每次格挡攻击造成点神圣伤害。每次格挡消耗一次充能。有n次充能。","汉化"},
[1148962] = {"恶毒","使你法术的命中率提高%，并使你的持续伤害疾病被驱散的几率降低%。","汉化"},
[1148963] = {"病变","凋零缠绕的伤害和治疗效果提高%，死亡凋零的冷却时间减少/1000;s2秒。","汉化"},
[1148965] = {"贪婪亡者","使你的力量总值提高%，你的食尸鬼从你的力量和耐力中获得的加成提高%。","汉化"},
[1148977] = {"血腥打击","使你的鲜血打击造成的伤害提高%，心脏打击造成的伤害提高%，血液沸腾造成的伤害提高%。","汉化"},
[1148978] = {"刀锋护甲","每m1*m2点护甲值使你的近战攻击强度提高。","汉化"},
[1148979] = {"屠宰","你每次杀死一个可以为你提供经验值或荣誉值的目标之后，都可以获得最多10符文能量。此外，你在战斗中每5秒获得1点符文能量值。","汉化"},
[1148982] = {"符文分流","将1枚鲜血符文转化为你的生命值上限的%。","汉化"},
[1148985] = {"强化符文分流","符文分流恢复的生命值提高%，冷却时间缩短/1000;s2秒。","汉化"},
[1148987] = {"黑暗定罪","使你的武器、法术和技能的爆击率提高%。","汉化"},
[1148988] = {"血腥复仇","在你武器挥砍、施放法术或技能造成爆击后，你造成的物理伤害提高1150447s1%，持续1120050d。此效果最多叠加1150447u次。","汉化"},
[1148989] = {"治疗宠物","在d内为你的宠物治疗total点生命值。","汉化"},
[1148990] = {"治疗宠物","在d内为你的宠物治疗total点生命值。","汉化"},
[1148995] = {"猛禽一击","强力攻击，使近战攻击造成的伤害提高点。","汉化"},
[1148996] = {"猛禽一击","强力攻击，使近战攻击造成的伤害提高点。","汉化"},
[1148997] = {"瓦解","鲜血打击、天灾打击、心脏打击和湮没的爆击率提高%，并使鲜血或邪恶灵气下产生的威胁值降低%。","汉化"},
[1148998] = {"反击","在招架敌人的攻击后触发的一次打击。此攻击造成AP*0.5+m1点伤害，并在触发招架时使目标无法移动，持续d。此攻击无法被格挡、躲闪或招架。","汉化"},
[1148999] = {"反击","在招架敌人的攻击后触发的一次打击。此攻击造成AP*0.5+m1点伤害，并在触发招架时使目标无法移动，持续d。此攻击无法被格挡、躲闪或招架。","汉化"},
[1149000] = {"毒蛇钉刺","钉刺目标，在d内对其造成RAP*0.2+m1*d/3点自然伤害。每位猎人同时只能对一个目标使用一种钉刺。","汉化"},
[1149001] = {"毒蛇钉刺","钉刺目标，在d内对其造成RAP*0.2+m1*d/3点自然伤害。每位猎人同时只能对一个目标使用一种钉刺。","汉化"},
[1149004] = {"血之气息","你有h%的几率在招架、躲闪或受到直接伤害后，获得血之气息效果，使你接下来的3次近战攻击每次获得10点符文能量。","汉化"},
[1149005] = {"鲜血印记","在一名敌人身上放置鲜血印记。每当被标记的敌人对目标造成伤害时，该目标的最大生命值就会被治疗值1149005s2%，持续1149005d或被击中1149005n次命中。","汉化"},
[1149006] = {"战争精英","使你的力量总值提高%，耐力提高%，所有法术和技能的命中率提高%。","汉化"},
[1149011] = {"翼龙钉刺","钉刺射击，使目标沉睡d。任何伤害都会取消效果。目标醒来时，毒刺会在1149009d内造成1149009o1点自然伤害。每个猎人每次只能对目标激活一个钉刺。","汉化"},
[1149012] = {"翼龙钉刺","钉刺射击，使目标沉睡d。任何伤害都会取消效果。目标醒来时，毒刺会在1149010d内造成1149010o1点自然伤害。每个猎人每次只能对目标激活一个钉刺。","汉化"},
[1149013] = {"爆发","瘟疫打击的伤害提高%，天灾打击的伤害提高%。","汉化"},
[1149015] = {"仇杀","当你杀死一个可以为你提供经验值或荣誉值的目标之后，为你恢复最多生命值上限%的生命值。","汉化"},
[1149016] = {"狂乱","诱导一个友方单位陷入杀戮狂乱，持续d，目标会受到%的物理伤害，但每秒会损失相当于最大生命值%的生命值。","汉化"},
[1149018] = {"末日突降","你的鲜血打击和心脏打击有h%的几率对目标施放一个无消耗的凋零缠绕。","汉化"},
[1149020] = {"湮没","野蛮的瞬发攻击，造成%武器伤害外加m1*m2/100点伤害，目标身上每有一种你的疾病效果，总伤害就提高m3/2.1%，但会消耗这些疾病效果。","汉化"},
[1149023] = {"莫格莱尼之力","使你的血液沸腾、鲜血打击、死亡打击和心脏打击的爆击伤害加成提高%。","汉化"},
[1149024] = {"无情的战斗","你的冰冷触摸，凛风冲击，湮灭和冰霜打击在攻击生命值低于35%的目标时会造成额外的%伤害。","汉化"},
[1149027] = {"血虫","你的武器攻击命中目标之后有h%的几率使目标身上钻出2到4条血虫。血虫会攻击你的敌人，并将它们造成的伤害转化为你的生命值，最多持续20秒或者直到被杀掉。","汉化"},
[1149028] = {"符文舞刃","召唤第二件符文武器，它能独立作战，持续d。攻击方式与死亡骑士相同，但伤害降低1151906s3%。","汉化"},
[1149032] = {"墓穴热疫","你的疾病还会导致墓穴热疫，使目标受到的疾病伤害提高1150508s1%。","汉化"},
[1149036] = {"流行病","血之疫病和冰霜疫病的持续时间延长/1000;s1秒。","汉化"},
[1149039] = {"巫妖之躯","吸取邪恶能量变为亡灵，持续d。在亡灵状态下，你对魅惑、恐惧和催眠效果免疫。","汉化"},
[1149042] = {"坚韧","使你因装备而获得的护甲值提高%，你的移动限制效果持续时间缩短%。","汉化"},
[1149044] = {"奥术射击","一次瞬发射击，造成RAP*0.15+m1点奥术伤害。","汉化"},
[1149045] = {"奥术射击","一次瞬发射击，造成RAP*0.15+m1点奥术伤害。","汉化"},
[1149047] = {"多重射击","发射数枚弹药，命中x1个目标造成额外点伤害。\n\n此技能与瞄准射击共享冷却时间。","汉化"},
[1149048] = {"多重射击","发射数枚弹药，命中x1个目标造成额外点伤害。\n\n此技能与瞄准射击共享冷却时间。","汉化"},
[1149049] = {"瞄准射击","一次瞄准射击，造成m3%远程武器伤害外加点伤害，并使目标受到的治疗效果降低%，持续d。\n\n此技能与多重射击共享冷却时间。","汉化"},
