[1149055] = {"献祭陷阱","放置一个火焰陷阱，燃烧第一个接近的敌人，在1149053d内对其造成(RAP*(mult/100)+1149053m1)*duration点火焰伤害。陷阱存在d。同一时间只能激活一个陷阱。","汉化"},
