[1149066] = {"爆炸陷阱","放置一个火焰陷阱，当敌人接近时会爆炸，造成RAP*0.1+1149064m1到RAP*0.1+1149064M1点火焰伤害，并对1149064a1码范围内的所有敌人在1149064d内额外造成1149064m2*10+RAP点火焰伤害。陷阱持续d。同时只能激活一个陷阱。","汉化"},
[1149067] = {"爆炸陷阱","放置一个火焰陷阱，当敌人接近时会爆炸，造成RAP*0.1+1149065m1到RAP*0.1+1149065M1点火焰伤害，并对1149065a1码范围内的所有敌人在1149065d内额外造成1149065m2*10+RAP点火焰伤害。陷阱持续d。同时只能激活一个陷阱。","汉化"},
