[1149202] = {"苔原猎手","你的法术和技能对受到冰霜疫病效果影响的目标造成的伤害提高%冰霜疫病。另外，你所有法术和技能命中几率提高%。","汉化"},
[1149203] = {"饥饿之寒","吸收死亡骑士附近地面上的热量，将周围半径1151209a1码范围内的所有敌人困在冰中（算作冻结效果），无法进行任何动作，并受到冰霜疫病效果的影响，持续1151209d。除了疾病之外的任何伤害都会打断这种冻结效果。","汉化"},
[1149206] = {"召唤石像鬼","一只石像鬼飞入战场并轰炸目标，对其造成自然伤害(此伤害值受到死亡骑士的攻击强度加成影响)。石像鬼会持续存在1161777d。","汉化"},
[1149208] = {"收割","每当你的鲜血打击或传染技能命中目标，就有h%的几率使你的鲜血符文在激活时变成死亡符文。死亡符文可以作为鲜血符文、冰霜符文或邪恶符文使用，","汉化"},
