[1149799] = {"割裂（豹）","终结技，使目标在一段时间内受到持续的伤害。根据连击点数和你的攻击强度决定伤害量：\n1点：d内(m1+b1*1+0.01*AP)*dur点伤害。\n2点：d内(m1+b1*2+0.02*AP)*dur点伤害。\n3点：d内(m1+b1*3+0.03*AP)*dur点伤害。\n4点：d内(m1+b1*4+0.04*AP)*dur点伤害。\n5点：d内(m1+b1*5+0.05*AP)*dur点伤害。","汉化"},
