[1157960] = {"水之护盾","施法者被1157960n个水球包围，每5秒恢复1157960s2点法力值。当施法者被法术，近战或远程攻击命中时，消耗一个水球恢复1157961s1点法力值。每隔数秒只能消耗一个水球。持续1157960d。萨满同时只能激活一种元素护盾。","汉化"},
[1157992] = {"毒伤","终结技，消耗目标身上的致命毒药层数并造成速效毒药伤害。施放毒伤后，你在1秒内（每连击点数额外增加1秒）获得额外%几率施加致命毒药，速效毒药触发频率提高%。每个连击点数消耗1层毒药：\n1层：(m1-1)*1+AP*0.09点伤害\n2层：(m1-1)*2+AP*0.18点伤害\n3层：(m1-1)*3+AP*0.27点伤害\n4层：(m1-1)*4+AP*0.36点伤害\n5层：(m1-1)*5+AP*0.45点伤害","汉化"},
