[1164901] = {"希望圣歌","每1164901t1秒为1164901s2附近的低法力值友方或小队目标恢复1164904s1%法力值，持续1164901d。并在1164904d内使其完全最大法力值增加1164904s2%。最多恢复*4;s2点法力值。牧师必须引导此法术。","汉化"},
