[1180060] = {"群兽奔腾","召唤兽群从你周围的荒野中奔袭而出，在6秒内对敌人造成(1180065m1*scalingbp+RAP*0.15)*4点物理伤害。兽群会向你前方奔袭最多30码距离。\n\n被兽群击中的敌人受到来自你和宠物的伤害提高1180068s1%，持续1180068d，可叠加1180070u层。敌人移动速度同时降低1180070s1%，持续290070d。\n\n@ext:若你的宠物处于狂野怒火状态，伤害提高50%。:ext@\n\n@ext:奔踏的冷却时间可被资历天赋降低。:ext@","汉化"},
[1180080] = {"吸血鬼之灭","@req:1134914:req@\n暗言术：灭会消耗目标身上的吸血鬼之触，造成吸血鬼之触总伤害%的伤害。此外，你因暗言术：灭而受到的伤害降低%。","汉化"},
[1180090] = {"祷言之环","@req:1134861:req@\n治疗祷言有/1000;s2秒冷却时间，使用时会重置治疗之环的冷却时间。","汉化"},
