[1180110] = {"恶魔旋风","@req:1130146:req@\n暗影箭或烧尽造成伤害会使你的恶魔卫士施放旋风斩，对8码范围内的敌人造成伤害。\n\n此效果每3秒只能触发1次。","汉化"},
