[1180141] = {"艾露恩之触","对一名敌人施加艾露恩之触。接下来的d内，对其它目标施放的愤怒、星火术和星涌术，也会同时对艾露恩之触标记的目标造成伤害。","汉化"},
[1180150] = {"繁盛自然","对盟友施放愈合或滋养会使其从你的持续治疗效果中获得的治疗量提高1180151s1%，持续1180151d，最多叠加1180151u次。","汉化"},
