[1180200] = {"精确撞击","你的流星对受到火球术或炎爆术持续伤害效果影响的目标造成的伤害提高%。\n\n你的火球术和炎爆术对受到流星持续伤害效果影响的目标造成的伤害提高%。","汉化"},
