[1180271] = {"战旗","在你脚下插下一面战旗，集结你的盟友。\n\n使1180272a1码范围内的所有盟友移动速度提高1180272s1%，并缩短所有受到的控制效果持续时间1180272s2%。持续1180272d。\n\n你可以援护战旗。","汉化"},
[1180280] = {"黑暗专注","暗言术：痛、精神鞭笞或精神灼烧造成伤害有h%几率使你的下一个心灵震爆无冷却时间且不消耗法力值。\n\n此效果每6秒只能触发1次。","汉化"},
[1180290] = {"迅捷处决","使用十字军打击会使处决宣判的冷却时间缩短1180291m1/-1000秒。\n\n对生命值低于35%的目标，十字军打击造成的伤害提高%。","汉化"},
[1180300] = {"圣光闪烁","圣光闪现会为被治疗的友方目标留下一道|cFFFFFFFF圣光闪烁|r，持续1180302d。\n\n@s:1180302:0@","汉化"},
[1180310] = {"圣光协同","施放圣光闪现会使你下一个圣光术的爆击率提高1180312s1%，法力消耗降低1180312s2%。\n\n施放圣光术会使神圣震击的冷却时间缩短1秒。","汉化"},
[1180320] = {"无情凶暴","使你的凶猛撕咬造成的伤害提高5%。\n\n你的终结技每个连击点数有20%的几率获得1180320s1%能量。","汉化"},
[1180330] = {"野蛮狂乱","你的每层野性狂乱流血效果，使你对目标造成的技能伤害提高%。\n\n使用狂暴技能会重置野性狂乱的冷却时间。","汉化"},
[1180340] = {"熔火弹药","@req:1153301:req@\n使用爆炸射击会使你下一个瞄准射击、稳固射击或多重射击造成额外1180341s1%火焰伤害。","汉化"},
[1180360] = {"流血之刃","当你的绞喉或割裂造成伤害获得3点能量。若目标生命值低于35%，则获得6点能量。","汉化"},
[1180370] = {"圣洁之光","@req:1153569@\n使你的圣光闪现对带有圣洁护盾的目标额外治疗50%，持续12秒。","汉化"},
[1180380] = {"战斗熟练","@req:1135541:req@\n战斗熟练天赋的触发几率提高%。\n@ext:@s:1135548:0@:ext@","汉化"},
[1180390] = {"邪恶终结","使用邪恶攻击会使你的终结技伤害提高1180391s1%，最多叠加1180391u次，持续1180391d。","汉化"},
[1180400] = {"血溅十方","@req:1151662:req@\n使用血之饥渴会使你的流血伤害提高1180401s1%，持续1180401d，并使目标在1180403d内额外承受30%的流血伤害。此效果每1180402d只能触发一次。\n\n此外，你的血之饥渴不再消耗能量。\n\n@ext:受到的额外流血伤害不与类似效果叠加。:ext@","汉化"},
[1180410] = {"大地之赐","对受到你大地生命武器持续治疗效果影响的盟友，你的自然治疗效果提高%。","汉化"},
[1180420] = {"元素洪流","当你的水元素用水箭造成伤害会使你的急速提高1180423s1%，持续1180423d，最多叠加1180423u层。","汉化"},
[1180430] = {"新的黎明","使你的下一个圣光闪现、圣光术或神圣震击对受到黎明之光治疗的目标的治疗效果提高1180431s1%。\n\n治疗受此效果影响的目标会使黎明之光的冷却减少1秒。","汉化"},
[1180440] = {"虚空传送门","教会你：虚空传送门。\n\n@s:1180441:-32@","汉化"},
[1180441] = {"虚空传送门","撕开一道虚空传送门，持续1180443d。施放暗影箭或烧尽会召唤1个恶魔为你作战，施放灵魂之火会召唤2个恶魔。","汉化"},
[1180450] = {"永恒折磨","@req:1148181:req@\n对受到鬼影缠身影响的目标再次施放鬼影缠身时，鬼影缠身必爆。\n\n你的鬼影缠身会使暗影系持续伤害效果额外提高%。","汉化"},
[1180460] = {"信仰扭曲","当正义圣印、命令圣印、复仇圣印或腐蚀圣印中的一种已激活时，切换使用另一种此类圣印会使之前激活的圣印效果持续1180462d。\n\n这些圣印不再消耗法力值，但有10秒冷却时间。","汉化"},
[1180470] = {"痛苦缠绕","使用死亡缠绕会对目标施加痛苦诅咒并收割其精华，使你的法术爆击率提高1180471s1%，持续1180471d。\n\n死亡缠绕的冷却时间缩短60秒，但不再使目标因恐惧而逃跑。","汉化"},
[1180480] = {"灵魂侵蚀","使用吸取灵魂时，你的鬼影缠身、痛苦无常和暗影之拥在目标身上的持续时间不会减少。\n\n痛苦无常和痛苦诅咒造成伤害时，有h%的几率使你下一个吸取灵魂的伤害提高200%，但其持续时间缩短至6秒。此效果每8秒只能触发1次。\n\n@ext:若目标生命值低于25%，则伤害仅提高25%。:ext@","汉化"},
[1180490] = {"厄运召唤者之怒","@req:1147197:req@\n从根除天赋获得的急速提高%。使用厄运诅咒会使你获得根除。","汉化"},
[1180500] = {"灾变爆裂","烧尽造成伤害会使你的献祭持续时间延长2秒，并使献祭的持续伤害提高1180501s1%，最多叠加4次。此效果在施放燃烧时会被消耗。","汉化"},
[1180510] = {"兽王豪赌","当你使用倒刺射击造成伤害有h%几率恢复1次倒刺射击的使用次数，并使你的倒刺射击造成的伤害提高1180511s2%，持续1180511d。","汉化"},
[1180520] = {"真言术：屏障","教会你：真言术：屏障。\n\n@s:1180523:-32@","汉化"},
[1180523] = {"真言术：屏障","在目标位置召唤一个神圣屏障，保护所有盟友d。屏障内的盟友受到的所有伤害降低1180522s1%，且在施法时因受到伤害而产生的延迟减少1180522s2%。","汉化"},
[1180530] = {"投掷掌握","@s:1572741:0@\n使用风暴之锤会强化你接下来的2个英勇投掷，使其不触发冷却时间，并使|cFFFFFFFF风暴护盾（由风暴之锤获得）|r的持续时间延长/1000;1180531s1秒。\n\n另外，风暴之锤和英勇投掷会施加2层破甲。","汉化"},
[1180540] = {"星界校准","对一名敌人施放月火术、星火术或星涌术会使他们受到你愤怒的伤害提高1180541s1%，持续1180541d。对受此效果影响的目标施放愤怒会恢复1180542s1%基础法力值。","汉化"},
[1180560] = {"复苏之潮","当治疗生命值低于50%的盟友时，你的次级治疗波和治疗波额外获得%爆击率，并恢复1180561s1%基础法力值。","汉化"},
[1180570] = {"治疗之潮","施放治疗之泉图腾后的6秒内，其治疗效果提高1180571s1%，但冷却时间增加/1000;s1秒。","汉化"},
[1180580] = {"无尽虚空","你的心灵震爆会使虚空爆发的持续暗影伤害延长/1000;1180581s1秒。\n@s:2110185:0:s@","汉化"},
