[1180600] = {"震击战术","使你的震击法术爆击率提高%。","汉化"},
[1180610] = {"圣光溢出","次级治疗术、治疗术或强效治疗术将盟友生命值治疗满时，会恢复1180611s2%的基础法力值，并使你下一次次级治疗术、治疗术或强效治疗术的治疗效果提高1180611s1%。","汉化"},
[1180620] = {"无情之怒","当任何激怒效果激活时，你的英勇打击和顺劈斩造成的伤害额外提高%。血性狂暴的生命值消耗降低%。\n\n击杀可获得经验值或荣誉的敌人后，血性狂暴的冷却时间减少10秒。","汉化"},
