[1180640] = {"灼热烈焰","你的灼热之痛对受到献祭影响的目标造成的伤害提高%。\n\n击杀可获得经验或荣誉的敌人后，你下一个献祭的伤害提高1180641s1%。","汉化"},
[1180650] = {"凯旋","你的乘胜追击造成额外%伤害，并治疗你1180651s1%生命值。","汉化"},
