[1180670] = {"暗影储备","你的精神分流效果还会使暗言术：痛和噬灵疫病的伤害提高1180671s2%，法力消耗降低1180671s1%。","汉化"},
[1180680] = {"复仇格挡","复仇造成伤害时，每命中一个目标会使盾牌格挡的冷却时间减少/1000;1180681s1秒。","汉化"},
[1180690] = {"稳定射击","在施放稳固射击后立刻再次施放，将使施法时间缩短1180691s1%，法力消耗降低1180691s2%。","汉化"},
[1180700] = {"十字军审判","你的十字军打击对受到审判效果影响的目标造成%额外伤害。","汉化"},
[1180710] = {"正义裁决","使用审判会使你下一个圣光术的爆击率提高1180711s1%，并降低其法力消耗。","汉化"},
[1180720] = {"极度专注","心灵专注的冷却时间缩短/1000;s2秒。\n\n施放快速治疗、次级治疗术、治疗术、强效治疗术或真言术：盾会使该冷却时间额外缩短3秒。","汉化"},
[1180730] = {"无怨无悔","@req:1314148:req@@req:1114148:req@\n无情攻击使对应技能的爆击率提高1180731s1%，并使其能量消耗降低1180731s2%。","汉化"},
[1180740] = {"爆裂烈焰","施放闪电箭、闪电链或任意震击法术会使火焰新星的冷却时间减少/1000;1180741s1秒，并使你下一个火焰新星的伤害提高1180742s1%，此效果最多叠加1180742u次。","汉化"},
[1180750] = {"能量涌动","对怪物使用凿击时，在凿击持续期间你的能量恢复速度提高100%。\n\n另外，你对受凿击影响的怪物施放的下一个直接伤害技能造成的伤害提高%。","汉化"},
[1180760] = {"冰冷屠杀","冰冷血脉激活期间，冰锥术的法力值消耗降低1180762s1%，伤害提高1180762s2%。\n\n击杀可获得经验或荣誉的敌人会使冰冷血脉的冷却时间缩短10秒。此效果每5秒只能触发1次。","汉化"},
[1180780] = {"暮光收割者","@req:1318095:req@@req:1118094:req@\n夜幕效果的暗影幻象现在还会使你的暗影箭法力消耗降低100%。\n\n击杀可获得经验或荣誉的目标后会触发暗影幻象。","汉化"},
[1180790] = {"共生自然","当目标受到你的回春术影响时，愈合的治疗效果提高%；当目标受到你的愈合影响时，回春术的治疗效果提高%。","汉化"},
[1180800] = {"自然的丰饶","使你的治疗之触的法力消耗降低%。\n\n当你的回春术或愈合进行持续治疗时，会恢复你基础法力值的1180801s1%。此效果每秒只能触发1次。","汉化"},
[1180810] = {"凶猛清晰","重殴的伤害提高%。此外，对受到你斜掠影响的目标，爪击的伤害提高%。\n\n击杀可获得经验值或荣誉的敌人后，你将触发清晰预兆。","汉化"},
[1180820] = {"猎杀狂乱","当目标带有你的猎人印记时，你的宠物特殊技能的伤害提高%。\n\n击杀可获得经验值或荣誉的敌人后，宠物下2次特殊技能的爆击率提高1180821s1%且不消耗集中值。","汉化"},
[1180830] = {"光辉之星","神圣之星的效果提高10%，且施放神圣之星会重置神圣之火的冷却时间。\n\n当你的神圣之火造成持续伤害时，神圣之星的冷却时间缩短0.5秒。","汉化"},
[1180840] = {"光与影","你的惩击对受到暗言术：痛影响的目标的爆击率提高%。另外，暗言术：痛的持续时间延长/1000;s2秒。","汉化"},
