[1180860] = {"烈焰校准","你的灼烧对受到你的火球术影响的目标造成的伤害提高%。","汉化"},
[1180870] = {"冻结导体","施放寒冰箭会使你的下一个暴风雪的法力消耗减少1180871s1%，最多叠加1180871u次。","汉化"},
[1180880] = {"杀戮疾跑","在疾跑激活期间击杀可获得经验或荣誉的敌人会刷新疾跑的持续时间，并使你下一个直接伤害技能的伤害提高1180881s2%。","汉化"},
[1180890] = {"追猎者的印记","你的猫鼬撕咬和反击对受到猎人印记影响的目标造成的伤害提高%。","汉化"},
[1180900] = {"暗影通道","当你对虚空行者引导生命通道时，其自动攻击会触发虚空新星，对5码范围内的敌人造成暗影伤害。","汉化"},
[1180910] = {"神圣恩赦","你的神圣恳求只会使圣光闪现、圣光术和神圣震击的治疗效果降低25%，并额外使这些法术的治疗爆击率提高1180911s1%。","汉化"},
[1180920] = {"恢复之潮","施放次级治疗波会强化你的下一个治疗波，使其法力消耗降低1180921s1%，爆击率提高1180921s2%。此效果最多叠加1180921u层，持续1180921d。","汉化"},
[1180930] = {"优雅复苏","@req:1116880:req@\n使你对生命值低于35%的目标施放的愤怒、星火术和星涌术的伤害提高%。\n\n击杀可获得经验值或荣誉的敌人会使你获得自然之赐，使你的施法速度提高1116886s1%，持续1116886d。","汉化"},
[1180940] = {"即刻清算","@req:1118119:req@\n对非战斗状态的怪物施放献祭会触发清算天赋，使其移动速度降低1118118s1%，持续1118118d。另外，你的清算会使献祭的伤害提高%。","汉化"},
[1180950] = {"黑暗收割","腐蚀术、痛苦诅咒、腐蚀之种或痛苦无常造成持续伤害会使你的下一个吸取生命的伤害提高1180951s1%，最多叠加1180951u层。\n\n击杀可获得经验或荣誉的敌人会获得3层。","汉化"},
[1180960] = {"正义之光","正义盾击的伤害提高%。\n\n使用正义盾击会使你的下一次光明审判为你恢复1180961s1%已损失生命值，最多叠加3次。","汉化"},
[1180970] = {"法网难逃","清算之手造成伤害会使你的移动速度提高1180971s1%，持续1180971d。\n\n激活时，审判效果造成伤害会使其持续时间延长/1000;1180973s1秒。","汉化"},
[1180980] = {"野蛮斩杀","斩杀击杀敌人会返还30点怒气值，并造成血腥爆炸，对5码内的敌人造成AP*0.25点伤害。","汉化"},
[1180990] = {"心灵灌注","对受到暗言术：痛影响的目标使用心灵尖啸会使你恢复1180991s1%的法力值。","汉化"},
