[1181020] = {"刺骨冰霜","@req:1111071:req@\n寒冰箭、冰枪术或冰锥术击杀敌人后，你下一个能触发寒冰指的法术将必定触发该效果。\n\n此效果每15秒只能触发1次。","汉化"},
[1181030] = {"炎爆奇袭","对非战斗状态的目标施放炎爆术必爆。","汉化"},
[1181050] = {"英勇猛击","使用猛击会移除你的下一个英勇打击或顺劈斩的怒气消耗。","汉化"},
[1181060] = {"引爆印记","当你首次对生命值高于75%的目标施加猎人印记时，你对目标施放的下一个远程技能必爆。","汉化"},
[1181070] = {"震荡创伤","你的震荡射击使目标受到你的远程和近战技能的伤害提高%。\n\n此外，震荡射击不再消耗法力值。","汉化"},
[1181080] = {"重雷轰击","当你使用一把双手武器时，你的雷霆一击造成额外%的伤害。","汉化"},
[1181090] = {"恢复誓言","对生命值高于75%的盟友施放恢复会使你下一个直接治疗法术的法力消耗降低1181091s1%，爆击率提高1181091s2%。","汉化"},
[1181100] = {"圣光爆裂","施放神圣之火会使你的下一个神圣新星充能，使其造成的伤害和治疗效果提高1181101s1%，法力消耗降低1181101s2%。","汉化"},
[1181110] = {"猛虎本能","使用爪击或裂伤（豹）会使猛虎之怒的冷却时间减少/1000;1181111s1秒。","汉化"},
[1181120] = {"利爪扫击","使用斜掠会使你的下一个爪击或裂伤（豹）额外攻击一个附近的敌人。\n\n用爪击或裂伤（豹）命中2个目标时，你会恢复10点能量。","汉化"},
[1181140] = {"奥术征伐","你的奥术冲击会对目标施加1层奥术充能。对受影响的敌人用奥爆术造成伤害会引爆充能，在短暂延迟后对附近敌人造成奥术伤害。","汉化"},
[1181150] = {"致命反击","还击的伤害提高%。\n\n击杀可获得经验或荣誉的敌人后，可在1181151d内使用1次还击。","汉化"},
[1181160] = {"狂乱挥击","使用横扫（熊）或痛击会使你的攻击速度提高1181161s1%，持续1181161d。此效果每10秒只能触发1次。","汉化"},
[1181170] = {"幻影刺杀","使用鬼魅攻击会使你下一个背刺的伤害提高1181171s2%，且无需在目标背后即可使用。\n\n使用背刺会使鬼魅攻击的冷却时间缩短/1000;1181173s1秒。","汉化"},
[1181180] = {"熔岩引燃","你的熔岩猛击对受到你烈焰震击影响的目标造成的伤害提高10%。\n\n使用熔岩猛击会使目标身上的烈焰震击持续时间延长/1000;1181181s1秒。","汉化"},
[1181190] = {"电流奔涌","@req:1116256:req@\n施放闪电箭或闪电链会触发你学会的最高等级的乱舞天赋。\n\n@s:1116256:0:s@","汉化"},
[1181200] = {"元素之势","@req:1116164:req@\n击杀可以获得经验值或荣誉值的敌人会触发你的元素集中天赋。","汉化"},
[1181210] = {"元素和谐","将一名盟友的生命值治疗满会使你的下一个闪电箭或闪电链不消耗法力值。","汉化"},
[1181220] = {"元素汇聚","冰封武器或火舌武器造成伤害会使你的下一个震击法术的直接伤害提高1181221s1%，此效果最多叠加1181221u层。若在5层时使用，你的下一个震击法术冷却时间缩短1秒。","汉化"},
