[1181250] = {"怨灵织造者：暗影回响","@req:1544910:req@\n当你拥有3个暗影宝珠时施放心灵震爆会重置其冷却时间。此外，施放暗言术：痛、噬灵疫病或吸血鬼之触会使你获得1个暗影宝珠。","汉化"},
[1181270] = {"圣光净化","你的神圣之火还会对8码范围内的最多3名敌人造成%的直接伤害，并对每个命中的敌人施加持续伤害效果。","汉化"},
[1181280] = {"愤怒释放","猛虎之怒激活时，你施加的割裂每次造成伤害都会使你恢复6点能量，并且凶猛撕咬的能量消耗降低15点。","汉化"},
[1181290] = {"灵魂恢复","对虚弱灵魂的盟友施放快速治疗或强效治疗术会使其持续时间减少/1000;S1秒。","汉化"},
[1181300] = {"可控侵犯","@req:1180851:req@\n@req:1146951:req@\n你的盾牌猛击提高攻击强度1181301s1%的伤害，且触发剑盾猛攻的几率翻倍。但盾牌猛击的冷却时间增加3秒。","汉化"},
[1181310] = {"群星汇聚","@req:1161346:req@\n星涌术造成伤害会使你的星辰坠落的冷却时间减少/1000;1181311s1秒，并获得自然之赐。","汉化"},
[1181320] = {"唤星者之势","连续施放3次愤怒或星火术后，你的下一个星涌术将变为瞬发。此效果最多储存3次。此外，星涌术的冷却时间减少/1000;s2秒。","汉化"},
[1181330] = {"星空之力","你的星火术会对未受月火术影响的目标施加|cFFFFFFFF星辰之怒|r。此效果不会与月火术叠加。\n\n你的愤怒会对未受虫群影响的目标施加|cFFFFFFFF自然之怒|r。此效果不会与虫群叠加。\n@s:1181332:0@\n@s:1181333:0@","汉化"},
[1181340] = {"铁卫","你成功格挡后，该次攻击对你造成的伤害降低%。","汉化"},
[1181360] = {"风暴本能","施放任意震击法术会使你躲闪下一个攻击的几率提高1181363s1%，并获得1层漩涡武器（需学会）。另外，施放原始打击、闪电箭或闪电链会使你下一个震击法术不触发冷却时间。","汉化"},
[1181370] = {"升腾烈焰","烈焰震击对受烈焰震击影响的目标施放时，其初始伤害翻倍。施放烈焰震击会使烈焰升腾和熔岩爆裂的剩余冷却时间缩短/1000;1181371s1秒。","汉化"},
[1181384] = {"清算之手（清算之拳）","造成1+0.25*AP点神圣伤害。此技能不触发公共冷却。","汉化"},
[1182001] = {"大地守护","受到的所有伤害减少%，但也减少你造成的伤害和治疗%。另外，产生的威胁提高1182006s2%，风剪不再降低你的威胁值。","汉化"},
[1182002] = {"大地尖刺","@req:1182001:0:req@\n原始打击不再消耗法力值，并在目标位置召唤一根大地尖刺，对附近敌人造成高威胁值物理伤害，并使你恢复1182003s2%基础法力值。\n\n另外，原始打击的冷却时间缩短2秒。","汉化"},
[1182010] = {"释地","嘲讽目标，使其向你发起攻击，但是对已经在攻击你的目标无效。","汉化"},
[1182030] = {"盾牌专精","使你的格挡几率提高%，并且被近战攻击爆击的几率减少%。","汉化"},
