[1277670] = {"圣光之赐","@req:1131836:req@\n你的光之优雅每15秒自动刷新。刷新时，你会获得1层圣光之赐，强化你的神恩术并且不会触发冷却时间。你在获得下一次圣光之赐前无法再次使用神恩术。","汉化"},
[1300006] = {"心灵支配","@req:15407@\n你的精神鞭笞将穿透敌人的灵魂，引导期间使暗言术：痛和吸血鬼之触对其造成的伤害提高30%。","汉化"},
