[1312296] = {"愤怒掌控","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得愤怒掌控天赋。此魔咒将无法生效。|r\n\n每3秒获得1点怒气值。\n\n此魔咒不与愤怒掌控天赋叠加。","汉化"},
