[1316164] = {"元素专注","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得元素集中天赋。此魔咒将不会生效。|r\n\n当你的火焰、冰霜或自然伤害法术造成非持续伤害爆击后，你会进入节能施法状态。该状态会使你接下来的1116246n个伤害或治疗法术的法力消耗降低1116246s1%。\n\n此魔咒无法与元素集中天赋叠加。","汉化"},
[1316198] = {"强化水之护盾","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化水之护盾天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化水之护盾天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化水之护盾天赋。此魔咒将无法生效。|r\n\n当你的治疗波或激流爆击时，有%几率立即获得消耗一个水之护盾能量球的法力值。次级治疗波爆击时有m1*0.6%几率、治疗链爆击时有m1*0.3%几率。\n\n此魔咒不与强化水之护盾天赋叠加。","汉化"},
[1316206] = {"恢复图腾","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得恢复图腾天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得恢复图腾天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得恢复图腾天赋。此魔咒将无法生效。|r\n\n使你的法力之泉图腾的效果提高%，治疗之泉图腾的治疗量提高%。\n\n此魔咒不与恢复图腾天赋叠加。","汉化"},
[1316209] = {"强化复生","使你的复生法术的冷却时间缩短/60000.s1分钟,并使你在重生后所获得的生命值和法力值提高%.","汉化"},
[1316217] = {"潮汐集中","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得潮汐集中天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得潮汐集中天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得潮汐集中天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得潮汐集中天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得潮汐集中天赋。此魔咒将无法生效。|r\n\n使你的治疗法术的法力消耗降低%。\n\n此魔咒不与潮汐集中天赋叠加。","汉化"},
