[1316272] = {"预知","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得预知天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得预知天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得预知天赋。此魔咒将无法生效。|r\n\n使你的躲闪几率额外提高%，并缩短所有对你使用的缴械效果持续时间%。该效果不与其他减少缴械持续时间的效果叠加。\n\n此魔咒不与预知天赋叠加。","汉化"},
