[1316864] = {"清晰预兆","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得清晰预兆天赋。此魔咒将无法生效。|r\n\n德鲁伊的伤害、治疗法术和自动攻击有几率使施法者进入节能施法状态。该状态使你下一个伤害或治疗法术/攻击技能的法力、怒气或能量消耗降低1116870s1%。\n\n此魔咒不与清晰预兆天赋叠加。","汉化"},
[1316913] = {"复仇","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得复仇天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得复仇天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得复仇天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得复仇天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得复仇天赋。此魔咒将无法生效。|r\n\n使你的星辰坠落、月火术和愤怒的爆击伤害加成提高%。\n\n此魔咒不与复仇天赋叠加。","汉化"},
