[1316938] = {"凶暴","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得凶暴天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得凶暴天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得凶暴天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得凶暴天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得凶暴天赋。此魔咒将无法生效。|r\n\n使你的重殴、横扫、爪击、斜掠和裂伤消耗的怒气或能量降低/10;s1点。\n\n此魔咒不与凶暴天赋叠加。","汉化"},
