[1316949] = {"野性本能","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得野性本能天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得野性本能天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得野性本能天赋。此魔咒将无法生效。|r\n\n使你的横扫造成的伤害提高%，并降低你在潜伏时被敌人发现的几率。\n\n此魔咒不与野性本能天赋叠加。","汉化"},
[1316968] = {"撕碎攻击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得撕碎攻击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得撕碎攻击天赋。此魔咒将无法生效。|r\n\n使你的撕碎的能量消耗降低点，割伤的怒气消耗降低/10;s2点。\n\n此魔咒不与撕碎攻击天赋叠加。","汉化"},
[1316975] = {"猛兽攻击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得猛兽攻击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得猛兽攻击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得猛兽攻击天赋。此魔咒将无法生效。|r\n\n使你在猎豹形态、熊形态和巨熊形态下的近战攻击强度提高等级的%加武器攻击强度的%。此外，你的终结技每消耗一个连击点数有b3%的几率使下一个基础施法时间低于10秒的自然法术变为瞬发。\n\n此魔咒不与猛兽攻击天赋叠加。","汉化"},
