[1317061] = {"激怒","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得激怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得激怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得激怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得激怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得激怒天赋。此魔咒将无法生效。|r\n\n你有%的几率在变形为熊形态或巨熊形态时获得/10;17057s1点怒气，在变形为猎豹形态时保留最多点能量，并使你在枭兽形态下的智力总值提高%。\n\n此魔咒不与激怒天赋叠加。","汉化"},
