[1318127] = {"恶魔之能","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得恶魔之能天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得恶魔之能天赋。此魔咒将无法生效。|r\n\n使你的魅魔的痛苦鞭笞冷却减少/1000;s2秒，小鬼的火球术施法减少0-m1/1000.2秒。\n\n此魔咒效果不与恶魔之能天赋叠加。","汉化"},
[1318136] = {"强烈","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强烈天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强烈天赋。此魔咒将无法生效。|r\n\n使你在施放或引导任何毁灭系法术时，因受到伤害而导致的施法推迟减少%。\n\n此魔咒不与强烈天赋叠加。","汉化"},
[1318176] = {"镇压","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得镇压天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得镇压天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得镇压天赋。此魔咒将无法生效。|r\n\n使你的法术命中率提高%，并使你的痛苦系法术的法力消耗降低%。\n\n此魔咒不与镇压天赋叠加。","汉化"},
[1318180] = {"强化虚弱诅咒","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化虚弱诅咒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化虚弱诅咒天赋。此魔咒将无法生效。|r\n\n使你的虚弱诅咒降低的攻击强度效果提高%。\n\n此魔咒不与强化虚弱诅咒天赋叠加。","汉化"},
[1318183] = {"强化生命分流","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化生命分流天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化生命分流天赋。此魔咒将无法生效。|r\n\n使你的生命分流法术所转化的法力值提高%。\n\n此魔咒不与强化生命分流天赋叠加。","汉化"},
[1318219] = {"无情延伸","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得无情延伸天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得无情延伸天赋。此魔咒将无法生效。|r\n\n使你的痛苦系法术的射程增加%。\n\n此魔咒不与无情延伸天赋叠加。","汉化"},
[1318221] = {"灵魂行者的恩赐","教会你：灵魂行者的恩赐。\n@s:1318222:-32@","汉化"},
[1318222] = {"灵魂行者的恩赐","召唤先祖之魂的指引，持续d，使你能在移动时施放萨满法术。可在施法时施放。","汉化"},
[1318288] = {"诅咒增幅","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得诅咒增幅天赋。此魔咒将无法生效。|r\n\n使你的诅咒的公共冷却时间缩短m2/-1000.1秒。\n\n此魔咒不与诅咒增幅天赋叠加。","汉化"},
[1318372] = {"强化灵魂吸取","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化吸取灵魂天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化吸取灵魂天赋。此魔咒将无法生效。|r\n\n若目标在你吸取其灵魂时被你击杀，返还你最大法力值的%。另外，你的痛苦系法术产生的威胁值降低%。\n\n此魔咒不与强化吸取灵魂天赋叠加。","汉化"},
[1318464] = {"奥术冥想","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得奥术冥想天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得奥术冥想天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得奥术冥想天赋。此魔咒将无法生效。|r\n\n使你在施法时仍保持%的法力恢复速度。\n\n此魔咒不与奥术冥想天赋叠加。","汉化"},
[1318535] = {"神圣之怒","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得神圣之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得神圣之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得神圣之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得神圣之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得神圣之怒天赋。此魔咒将无法生效。|r\n\n使你的惩击、神圣之火、治疗术和强效治疗术的施法时间缩短/1000;S1秒。\n\n此魔咒不与神圣之怒天赋叠加。","汉化"},
[1318693] = {"强化治疗石","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化治疗石天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化治疗石天赋。此魔咒将无法生效。|r\n\n使你的治疗石所恢复的生命值增加%。\n\n此魔咒不与强化治疗石天赋叠加。","汉化"},
[1318696] = {"强化小鬼","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化小鬼天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化小鬼天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化小鬼天赋。此魔咒将无法生效。|r\n\n使你的小鬼的火焰箭、火焰之盾和血之契印的效果提高%。\n\n此魔咒不与强化小鬼天赋叠加。","汉化"},
[1318699] = {"恶魔之拥","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得恶魔之拥天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得恶魔之拥天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得恶魔之拥天赋。此魔咒将无法生效。|r\n\n使你的耐力总值提高%。\n\n此魔咒不与恶魔之拥天赋叠加。","汉化"},
[1318704] = {"强化生命通道","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化生命通道天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化生命通道天赋。此魔咒将无法生效。|r\n\n使你的生命通道法术转移的生命值提高%，生命消耗降低%。此外，你的召唤恶魔在生命通道效果期间受到的伤害降低1160956s1%。\n\n此魔咒不与强化生命通道天赋叠加。","汉化"},
[1318707] = {"恶魔蛮力","|cFF66DDFF跨界天赋|r\n使你的虚空行者的折磨、吞噬暗影、牺牲和受难法术的效果提高%，并使恶魔卫士的恶魔狂暴的攻击强度加成提高%。\n\n@ext:此魔咒不与恶魔蛮力天赋叠加。:ext@","汉化"},
[1318710] = {"召唤大师","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得召唤大师天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得召唤大师天赋。此魔咒将无法生效。|r\n\n使你的小鬼、虚空行者、魅魔、地狱猎犬和恶魔卫士的召唤时间缩短/1000;s1秒，法力消耗降低%。\n\n此魔咒不与召唤大师天赋叠加。","汉化"},
[1318744] = {"邪能活力","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得邪能活力天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得邪能活力天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得邪能活力天赋。此魔咒将无法生效。|r\n\n使你的小鬼、虚空行者、魅魔、地狱犬和恶魔卫士的耐力与智力提高%，并使你的生命值和法力值上限提高%。\n\n此魔咒不与邪能活力天赋叠加。","汉化"},
[1318756] = {"强化魅魔","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化魅魔天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化魅魔天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化魅魔天赋。此魔咒将无法生效。|r\n\n使你的魅魔的诱惑的施法时间缩短%，并使你的魅魔的诱惑和次级隐形术的持续时间延长%。\n\n此魔咒不与强化魅魔天赋叠加。","汉化"},
[1318773] = {"邪恶强化","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得邪恶强化天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得邪恶强化天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得邪恶强化天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得邪恶强化天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得邪恶强化天赋。此魔咒将无法生效。|r\n\n使你的虚空行者、魅魔、地狱猎犬和恶魔卫士的近战攻击以及小鬼的火焰箭造成的伤害提高%。\n\n此魔咒不与邪恶强化天赋叠加。","汉化"},
[1318829] = {"强化痛苦诅咒","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化痛苦诅咒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化痛苦诅咒天赋。此魔咒将无法生效。|r\n\n使你的痛苦诅咒造成的伤害提高%。\n\n此魔咒不与强化痛苦诅咒天赋叠加。","汉化"},
[1319160] = {"野蛮打击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得野蛮打击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已掌握野蛮打击天赋。此魔咒将无法生效。|r\n\n猛禽一击、猫鼬撕咬和反击的爆击率提高%。\n\n此魔咒不与野蛮打击天赋叠加。","汉化"},
[1319259] = {"生存专家","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得生存专家天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得生存专家天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得生存专家天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得生存专家天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得生存专家天赋。此魔咒将无法生效。|r\n\n使你的耐力提高%。\n\n此魔咒不与生存专家天赋叠加。","汉化"},
[1319287] = {"生存战术","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得生存战术天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得生存战术天赋。此魔咒将无法生效。|r\n\n使你的假死和所有陷阱被抵抗的几率降低%，并使逃脱的冷却时间缩短/1000;S2秒。\n\n此魔咒不与生存战术天赋叠加。","汉化"},
[1319298] = {"偏斜","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得偏斜天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得偏斜天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得偏斜天赋。此魔咒将无法生效。|r\n\n使你的招架几率提高%，对你使用的所有缴械效果的持续时间缩短%。不与其他缴械持续时间缩短效果叠加。\n\n此魔咒不与偏斜天赋叠加。","汉化"},
[1319388] = {"诱捕","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得诱捕天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得诱捕天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得诱捕天赋。此魔咒将无法生效。|r\n\n当你的冰霜陷阱或毒蛇陷阱被触发时，所有受影响的目标将被诱捕，使其无法移动，持续1164804d。\n\n此魔咒不与诱捕天赋叠加。","汉化"},
[1319412] = {"强化震荡射击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化震荡射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化震荡射击天赋。此魔咒将无法生效。|r\n\n使你震荡射击的眩晕效果持续时间延长/1000;s1秒。\n\n此魔咒不与强化震荡射击天赋叠加。","汉化"},
[1319420] = {"效率","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得效率天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得效率天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得效率天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得效率天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得效率天赋。此魔咒将无法生效。|r\n\n使你的射击和钉刺技能的法力消耗降低%。\n\n此魔咒不与效率天赋叠加。","汉化"},
[1319423] = {"强化猎人印记","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化猎人印记天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化猎人印记天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化猎人印记天赋。此魔咒将无法生效。|r\n\n使你的猎人印记提供的攻击强度加成提高%，并使其法力消耗降低%。\n\n此魔咒不与强化猎人印记天赋叠加。","汉化"},
[1319431] = {"夺命射击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得夺命射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得夺命射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得夺命射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得夺命射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得夺命射击天赋。此魔咒将无法生效。|r\n\n使你的远程武器爆击率提高%。\n\n此魔咒不与夺命射击天赋叠加。","汉化"},
[1319456] = {"强化奥术射击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化奥术射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化奥术射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化奥术射击天赋。此魔咒将无法生效。|r\n\n使你的奥术射击所造成的伤害提高%。\n\n此魔咒不与强化奥术射击天赋叠加。","汉化"},
[1319466] = {"强化钉刺","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化钉刺天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化钉刺天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化钉刺天赋。此魔咒将无法生效。|r\n\n使你的毒蛇钉刺和翼龙钉刺造成的伤害提高%，蝰蛇钉刺的法力吸取效果提高%。此外，使你的钉刺持续伤害效果被驱散的几率降低%。\n\n此魔咒不与强化钉刺天赋叠加。","汉化"},
[1319490] = {"致死射击","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得致死射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得致死射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得致死射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得致死射击天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得致死射击天赋。此魔咒将无法生效。|r\n\n使你的远程技能的爆击伤害加成提高%。\n\n此魔咒不与致死射击天赋叠加。","汉化"},
[1319500] = {"鹰眼","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得鹰眼天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得鹰眼天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得鹰眼天赋。此魔咒将无法生效。|r\n\n使你的远程武器射程延长码。\n\n此魔咒不与鹰眼天赋叠加。","汉化"},
[1319551] = {"强化灵猴守护","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得强化灵猴守护天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化灵猴守护天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得强化灵猴守护天赋。此魔咒将无法生效。|r\n\n使你的灵猴守护和龙鹰守护的躲闪加成提高%。\n\n此魔咒不与强化灵猴守护天赋叠加。","汉化"},
