[1324972] = {"宁静之魂","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得宁静之魂天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得宁静之魂天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得宁静之魂天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得宁静之魂天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得宁静之魂天赋。此魔咒将无法生效。|r\n\n使你的治疗之触、滋养和宁静的法力消耗降低%。\n\n此魔咒不与宁静之魂天赋叠加。","汉化"},
[1325782] = {"圣洁力量祝福","使小队或团队中所有成员获得圣洁力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1325836] = {"不灭信仰","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得不灭信仰天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得不灭信仰天赋。此魔咒将无法生效。|r\n\n所有恐惧和迷惑效果的持续时间缩短%。\n\n此魔咒不与不灭信仰天赋叠加。","汉化"},
[1325894] = {"圣洁智慧祝福","为团队或小队中所有成员施加圣洁智慧祝福，在d内每5秒恢复点法力值。每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1325898] = {"圣洁王者祝福","使小队或团队中所有成员获得强效王者祝福的效果，使其所有属性提高%，持续d。每位圣骑士在同时只能给目标施加一种祝福。","汉化"},
[1325899] = {"圣洁庇护祝福","为团队或小队所有成员施加强效庇护祝福，使其受到的所有伤害降低%，持续d，并使其力量和耐力提高%。此外，当目标格挡、招架或躲闪近战攻击时，将获得1157319s1%的最大显示法力值。每位圣骑士同时只能对玩家施加一种祝福。","汉化"},
