[1327816] = {"神恩回复","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得神恩回复天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得神恩回复天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得神恩回复天赋。此魔咒将无法生效。|r\n\n在遭受近战或远程爆击之后，神恩回复会为你恢复所受伤害的%，持续1127818d。效果期间再次受到爆击会提高治疗量。\n\n此魔咒不与神恩回复天赋叠加。","汉化"},
