[1337117] = {"原始之怒","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得原始狂怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得原始狂怒天赋。此魔咒将无法生效。|r\n\n在巨熊形态和巨熊形态下，你的爆击有1116961h%的几率额外获得/10;16959s1点怒气值。在猎豹形态下，你的可产生连击点的技能爆击时有1116954h%的几率额外获得1个连击点。\n\n此魔咒不与原始狂怒天赋叠加。","汉化"},
[1343338] = {"萨满专注","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得萨满专注天赋。此魔咒将无法生效。|r\n\n使你的震击法术的法力消耗降低%。\n\n此魔咒不与萨满专注天赋叠加。","汉化"},
