[1347231] = {"邪能共效","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得恶魔协同天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得恶魔协同天赋。此魔咒将无法生效。|r\n\n你有h%的几率治疗你的宠物，数值相当于你所造成法术伤害的%。\n\n此魔咒不与邪能共效天赋叠加。","汉化"},
[1348410] = {"原始精准","降低法力值消耗,并使你的法术命中几率提高%.|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得原始精准天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得原始精准天赋。此魔咒将无法生效。|r\n\n使你的精准提高点，且终结技未命中时返还%的能量消耗。\n\n此魔咒不与原始精准天赋叠加。","汉化"},
[1348412] = {"变形大师","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得变形大师天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得变形大师天赋。此魔咒将无法生效。|r\n\n德鲁伊在相应变形形态下获得持续效果：\n\n熊形态-物理伤害提高%\n\n猎豹形态-爆击率提高%\n\n枭兽形态-所有法术伤害提高%\n\n生命之树形态-治疗效果提高%\n\n此魔咒不与变形大师天赋叠加。","汉化"},
[1348933] = {"强效力量祝福","为与目标同职业的团队或小队所有成员施加强效力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1348934] = {"圣洁力量祝福","使小队或团队中所有成员获得圣洁力量祝福，使其攻击强度提高，持续d。每个圣骑士在同一时间只能为玩家施加一个祝福。","汉化"},
[1348937] = {"圣洁智慧祝福","为团队或小队中所有成员施加圣洁智慧祝福，在d内每5秒恢复点法力值。每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
[1348938] = {"圣洁智慧祝福","为团队或小队中所有成员施加圣洁智慧祝福，在d内每5秒恢复点法力值。每位玩家同一时间只能从每个圣骑士身上获得一个祝福效果。","汉化"},
