[1353265] = {"守护掌握","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得守护掌握天赋。此魔咒将无法生效。|r\n\n蝰蛇守护-伤害惩罚降低%\n\n灵猴守护-激活时受到的伤害降低%\n\n雄鹰守护-攻击强度加成提高%\n\n龙鹰守护-结合雄鹰守护和猎鹰守护的加成效果\n\n此魔咒不与守护掌握天赋叠加。","汉化"},
[1353519] = {"淡泊","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得淡泊天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得淡泊天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得淡泊天赋。此魔咒将无法生效。|r\n\n使所有昏迷效果的持续时间额外缩短%，并使你的有益法术和持续伤害效果被驱散的几率额外降低%。\n\n此魔咒不与淡泊天赋叠加。","汉化"},
