[1353622] = {"专注瞄准","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得专注瞄准天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得专注瞄准天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得专注瞄准天赋。此魔咒将无法生效。|r\n\n使你在施放稳固射击时因受到伤害而导致的施法推迟降低%，并使你的命中率提高%。\n\n此魔咒不与专注瞄准天赋叠加。","汉化"},
