[1360188] = {"元素之怒","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得元素之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得元素之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得元素之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得元素之怒天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得元素之怒天赋。此魔咒将无法生效。|r\n\n使你的灼热图腾和熔岩图腾以及火焰、冰霜和自然法术的爆击伤害加成提高%。\n\n此魔咒不与元素之怒天赋叠加。","汉化"},
