[1361331] = {"侵犯","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得侵犯天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得侵犯天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得侵犯天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得侵犯天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得侵犯天赋。此魔咒将无法生效。|r\n\n使你的邪恶攻击、背刺和剔骨造成的伤害提高%。\n\n此魔咒不与侵犯天赋叠加。","汉化"},
[1361346] = {"自然之赐","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得自然之赐天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得自然之赐天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得自然之赐天赋。此魔咒将无法生效。|r\n\n你的任何非持续性法术爆击之后都有h%的几率获得自然的赐福，使你的施法速度提高1116886s1%，持续1116886d。\n\n此魔咒不与自然之赐天赋叠加。","汉化"},
[1363351] = {"熔铸皮肤","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得熔铸皮肤天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得熔铸皮肤天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得熔铸皮肤天赋。此魔咒将无法生效。|r\n\n受到的所有伤害降低%。\n\n此魔咒不与熔铸皮肤天赋叠加。","汉化"},
[1363458] = {"陷阱掌握","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得陷阱掌握天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得陷阱掌握天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得陷阱掌握天赋。此魔咒将无法生效。|r\n\n冰霜陷阱和冰冻陷阱-持续时间延长%\n\n献祭陷阱、爆炸陷阱和黑箭-持续伤害提高%\n\n毒蛇陷阱-召唤的毒蛇数量增加*2;s3条\n\n此魔咒不与陷阱掌握天赋叠加。","汉化"},
[1363650] = {"圣洁","|cFF66DDFF跨界天赋|r\n|cffFF0000你已习得圣洁天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得圣洁天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得圣洁天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得圣洁天赋。此魔咒将无法生效。|r\n\n|cffFF0000你已习得圣洁天赋。此魔咒将无法生效。|r\n\n使你施放的所有治疗效果提高%，同时你受到的所有治疗效果也提高%。\n\n此魔咒不与圣洁天赋叠加。","汉化"},
