[1418500] = {"自然共生","在目标身上激活的每个持续治疗效果都会使你的治疗之触和滋养的治疗效果提高%。","汉化"},
[1435693] = {"龙族知识","根据当前激活的龙类同伴类型获得对应效果：\n\n蓝龙与青铜龙：使你提高你的统率龙类智力12%的急速等级。\n\n红龙与绿龙：使你提高你的统率龙类智力16%的爆击等级。\n\n其他龙类：使你提高你的统率龙类智力16%的法术强度。","汉化"},
[1436378] = {"备战就绪","进入高度防御警戒状态。每次受到法术或技能攻击时，你受到的所有伤害降低1436379s1%，持续1436379d，最多可叠加1436379u次。效果持续d，或未受攻击持续1436379d后消失。","汉化"},
[1436395] = {"灵魂收割","使你的法术和宠物的伤害增加%。持续d，你释放的腐蚀术，痛苦诅咒，献祭，暗言术：痛和噬灵疫病，将使持续时间增加3秒，最多增加至24秒。\n\n不会与其他类似效果叠加。","汉化"},
[1436397] = {"操控时间","扭曲时间的结构，使施法者再次施放该技能或d后会返回到当前所在的位置，并恢复施放时的生命值、法力值及增益效果。\n\n如果施法者在效果生效前死亡、或移动距离过远，则此效果失效。\n\n@ext:对吸收效果无效.:ext@","汉化"},
[1436405] = {"操控时间：回溯","使施法者回到之前的位置。","汉化"},
[1441232] = {"邪恶狂乱","使你的恶魔或者亡灵宠物攻击等级提高%，但每t2秒消耗其%生命值。持续d。","汉化"},
[1441602] = {"召唤元素","召唤你的元素仆从到你身边。","汉化"},
[1441605] = {"复活元素","复活你的元素仆从，使其以%的基础生命值重生。","汉化"},
[1441606] = {"拘束元素","开始拘束一个元素生物作为你的同伴。在专注支配元素时你的护甲值减少91606s3%，持续20秒。如果因任何原因失去元素生物的注意，支配过程将会失败。每种元素生物都拥有独特技能。","汉化"},
[1441631] = {"召唤龙类","召唤你的龙类到身边。","汉化"},
[1441633] = {"复活龙类","复活你的龙类仆从，并使其恢复%的基础生命值。","汉化"},
[1441634] = {"统率龙类","尝试驯服一只龙类，使其成为你的同伴。在这个过程中，你的护甲值降低91634s3%，持续20秒。如果你因为任何原因失去了它的注意力，则驯服过程失败。每种类型的龙类都有其独特的能力，你可以利用它们。","汉化"},
[1459982] = {"龙类学识","收集目标龙类生物的信息。提示信息将显示其伤害、生命值、护甲和特殊抗性。此外，龙类学识会揭示该生物是否可驯服以及驯服后拥有的技能。","汉化"},
[1459983] = {"元素学识","收集目标元素生物的信息。工具提示将显示伤害、生命值、护甲和任何特殊抗性。此外，元素学识将揭示该生物是否可驯服以及驯服后获得的技能。","汉化"},
