[1504646] = {"专注魔法","使目标的法术爆击率提高%。当目标爆击时，施法者的法术爆击率提高1154648s1%，持续1154648d。无法对自身施放。","汉化"},
[1511336] = {"生存本能","激活之后，这个技能使你在熊、猎豹和巨熊形态下暂时获得相当于生命值上限%的生命值，持续d。效果消失后，额外的生命值会被扣除。","汉化"},
[1514205] = {"神圣牺牲","将a1码范围内小队成员受到伤害的%转移给施法者（上限为圣骑士生命值的%乘以小队成员人数）。当施法者生命值低于%时效果解除，持续d。","汉化"},
[1544910] = {"怨灵织造者：暗影宝珠","当暗言术：痛、噬灵疫病或吸血鬼之触造成伤害时，你有h%几率获得1颗暗影宝珠。\n\n每颗暗影宝珠使心灵震爆的伤害提高1544915s2%。同时最多存储3颗暗影宝珠\n\n当层数叠满时，心灵震爆会消耗所有宝珠，向目标发射一个暗影幻象，命中时对5码内所有敌人造成1544915m1*scalingbp)+(SP*0.25点暗影伤害。","汉化"},
[1554908] = {"神圣圣殿骑士","十字军打击和神圣震击使你获得|cFFFFFFFF神圣能量|r。\n\n你可以消耗3点|cFFFFFFFF神圣能量|r来使用圣殿骑士裁决或荣耀圣言。\n\n@s:1554911:0:0:0:-48@\n@s:1554912:0:0:0:-48@","汉化"},
[1554911] = {"圣殿骑士裁决","一次强力攻击造成%武器伤害。","汉化"},
[1554912] = {"荣耀圣言","为一名友方目标治疗m1*scalingbp+SPH*1.2点生命值，并在d内额外治疗m2*scalingbp*3+SPH*0.3点生命值。","汉化"},
[1554916] = {"处决裁决","@req:1554908:req@\n使用愤怒之锤会使你获得一层神圣能量。当目标生命值低于35%时，使用圣殿骑士裁决也会使你获得一层神圣能量。\n\n此外，圣殿骑士裁决对生命值低于35%的目标的爆击率提高%。","汉化"},
[1554922] = {"混乱代理","@req:1150796:req@\n|cFFFFFFFF献祭|r的持续时间延长40%，但造成的伤害降低30%。\n\n|cFFFFFFFF献祭|r的持续伤害受益于法术急速，并使|cFFFFFFFF混乱之箭|r的冷却时间减少0.5秒。","汉化"},
[1554923] = {"神圣复苏","@req:1153385:req@\n自动攻击有12%几率重置神圣风暴的冷却时间。","汉化"},
[1554925] = {"圣光十字军","在12次自动攻击或近战技能后，你的下一次自动攻击会命中两次，并使复仇之怒的冷却减少/1000;1554927S3秒。\n\n当复仇之怒激活时，你会获得2层效果。","汉化"},
[1556000] = {"恐惧咆哮","你的挫志怒吼会以恐惧压制敌人，造成1556001m1*scalingbp+AP*0.12点必中的高威胁物理伤害。\n\n但挫志怒吼的冷却时间增加/1000;s2秒。","汉化"},
[1556002] = {"盾牌大师的决心","生命值低于35%时受到近战或远程伤害会使你获得盾牌格挡，持续/1000;1556003s1秒。此效果每60秒只能触发1次。若盾牌格挡已激活则不会触发。\n\n此外，当你的生命值低于35%时受到的伤害降低%。","汉化"},
[1556004] = {"复苏复仇","复仇会使你的狂怒回复持续时间延长/1000;1556005s1秒。\n\n当狂怒回复激活时，对怪物使用复仇还会为你恢复已损失生命值1556019s1%的生命值。\n\n@ext:每3秒只能触发一次。:ext@","汉化"},
