[1556008] = {"野蛮之势","你的宠物特殊攻击造成爆击时，会使你的瞄准射击和多重射击|r的冷却时间减少/1000;1556009s1秒。","汉化"},
[1556015] = {"深奥能量","奥术冲击现在最多叠加5层。每层使奥术冲击有10%几率对附近的敌人造成%的额外伤害。","汉化"},
[1566844] = {"灵魂的召唤","同时放置图腾栏中的最多4个指定图腾。可以放置与元素的召唤和先祖的召唤不同的图腾。","汉化"},
