[1567776] = {"法术格挡","盾牌格挡还会使受到的所有魔法伤害降低%，但其持续时间减少/1000;s1秒。","汉化"},
[1567777] = {"赎罪","|cFFFFFFFF惩击|r或|cFFFFFFFF神圣之火|r造成伤害时会治疗附近一名盟友。|cFFFFFFFF苦修|r造成伤害时会治疗附近3名盟友。施放这些法术会获得|cFFFFFFFF赎罪|r。\n\n通过赎罪治疗自己时，治疗效果降低30%。\n@s:1567778:0@\n@ext:|cFFFFFFFF赎罪|r的治疗效果受治疗加成影响，并可触发其他效果:ext@","汉化"},
[1567863] = {"胜利冲锋","施放冲锋现在会使你获得|cFFFFFFFF凯旋|r，使你能够施放1次乘胜追击。\n\n@ext:此效果每6秒只能触发一次:ext@","汉化"},
[1567884] = {"战斗冲锋","冲向敌人，造成1567864s1%武器伤害并产生/10;s2点怒气。\n\n@ext:使用冲锋修正值，可在近战范围内使用。:ext@","汉化"},
[1567905] = {"碾压冲锋","用物理近战技能命中受|cFFFFFFFF碾压冲击|r影响的目标，现在会使|cFFFFFFFF战斗冲锋|r的冷却时间减少/1000;270703S1秒。\n\n@ext:此效果每3秒只能触发一次。:ext@","汉化"},
