[1568152] = {"爆炸装药","@req:1153301:req@\n你的爆炸射击会将其造成伤害的%，分摊给5码范围内的其他敌人。","汉化"},
[1568174] = {"疯狂牧师","你的牧师伤害性法术有h%几率无消耗额外施放一个随机牧师法术。","汉化"},
