[1568369] = {"爆裂射击","施放黑箭、爆炸射击、奇美拉射击、瞄准射击或杀戮射击时，还会向目标发射一发|cFFFFFFFF爆裂射击|r，造成(PL-20)*0.7+1568370m2%火焰远程武器伤害。\n\n使用黑箭、活体炸弹和毒蛇钉刺造成伤害时，有h%几率触发|cFFFFFFFF爆裂射击|r。\n\n@ext:爆裂射击使用火焰冲击修正值。:ext@","汉化"},
[1568559] = {"法师的遗产","","汉化"},
[1568699] = {"邪能冲锋","冲锋会留下暗影烈焰路径，每秒造成(PL*1+1568700m2)+(SP*0.03)+(AP*0.03)点暗影烈焰伤害，持续d，并在撞击时对附近敌人造成(PL*2+271374m1)+(SP*0.1)+(AP*0.1)点暗影烈焰伤害。","汉化"},
[1568799] = {"生命之环","施放快速治疗、强效治疗术、治疗祷言和治疗之环会使光晕的冷却时间缩短/1000;1568802s1秒。","汉化"},
[1568910] = {"熔岩扫击","向前方释放炽热熔岩扫击，对主要目标造成相当于主手武器伤害100%的火焰伤害，对其他目标造成一半伤害。\n\n若你的武器附有火舌武器，此伤害提高25%。\n\n若你使用单手武器，此伤害提高25%。\n\n使用熔岩猛击修正值。","汉化"},
[1569011] = {"星界风暴","你召唤先祖之灵，对目标造成(max((PL-59),0)*58+m1)+(SP*1.08)+(AP*0.7)到(max((PL-59),0)*64+M1)+(SP*1.08)+(AP*0.07)点星界伤害。可在移动时施放。\n\n@ext:使用雷霆风暴修正值:ext@","汉化"},
[1569074] = {"太阳之怒","日蚀激活期间，你的愤怒爆击率额外提高1569054s1%。","汉化"},
[1569117] = {"大法师","触发思维冷却的几率额外提高%。","汉化"},
[1569166] = {"稳固步伐","@req:1153224:req@\n你的强化稳固射击有100%几率触发。","汉化"},
[1569208] = {"蝗灾射击","射击造成%武器伤害的自然伤害。可以在移动时施放。\n\n@ext:此技能使用稳固射击修正值。:ext@","汉化"},
[1569366] = {"游击陷捕者","你的震荡射击还会用绳索束缚敌人，2秒后将玩家目标拉向你，但射程减少S3码。\n\n你的|cFFFFFFFF倒刺陷阱|r现在会使受震荡射击影响的敌人昏迷3秒。\n\n@ext:该拉拽效果每1569368d只能触发一次。:ext@","汉化"},
[1569395] = {"倒刺陷阱","发射一支箭矢，在目标位置布置陷阱，一旦触发陷阱，陷阱会困住敌人。降低其30%的移动速度并使其流血。每2秒造成(PL*3.3+860210m1)+(SP*0.13)+(RAP*0.13)点伤害，持续1569396d。\n\n陷阱可存在1569396d。同时只能布置一个陷阱。\n\n@ext:与献祭陷阱和爆炸陷阱共享冷却时间。:ext@","汉化"},
[1569420] = {"巨龙猛击","嗜血和斩杀造成伤害使你获得|cFFFFFFFF巨龙猛击|r。\n@s:1569422:0@","汉化"},
[1569444] = {"巨龙咆哮","发出爆炸性咆哮，对附近敌人造成AP*0.563点穿甲物理伤害，并使其移动速度降低S2%，持续d。","汉化"},
[1569466] = {"巨龙冲锋","以271903s1%的额外速度冲锋，直到撞击敌人或持续d。撞击时在你面前释放锥形火焰，造成(PL*3+954258m1)+(SP*0.1)+(AP*0.1)点火焰伤害，并使敌人减速1569467s3%，持续1569467d。\n\n当撞击永久免疫减速的敌人时，造成300%额外伤害。\n\n@ext:使用拦截修正值。与其他突进技能共享冷却时间。:ext@","汉化"},
[1569490] = {"巨龙战士","你的旋风斩会使巨龙咆哮的冷却时间减少/1000;1569470S1秒，并使你下一个巨龙咆哮的伤害提高1569421s1%，最多叠加1569421u次。","汉化"},
[1569511] = {"巨龙之力","施放冲锋或拦截使你获得|cFFFFFFFF巨龙之力|r。\n@s:1569491:0@","汉化"},
[1569556] = {"冰霜炸弹","在目标身上放置一颗冰霜炸弹，在d后或被驱散时爆炸，造成1569559m1+1569559ppl1+SP*0.7点冰霜伤害，并使10码范围内的敌人减速1569559s2%，持续1569559d。","汉化"},
[1569560] = {"冰霜炸弹","在目标身上放置一颗冰霜炸弹，在d后或被驱散时爆炸，造成1569566m1+1569566ppl1+SP*0.7点冰霜伤害，并使10码范围内的敌人减速1569559s2%，持续1569559d。","汉化"},
