[1569578] = {"冰冻急速","你的冰霜炸弹爆炸会使你的法术急速提高1569579s1%，持续8秒。每额外命中一个目标，持续时间延长1秒，最多持续12秒。","汉化"},
[1569645] = {"禁忌招式","瞬发射击，造成%远程暗影武器伤害。使用此技能后，你会传送至目标位置，在原地留下你的影子，并获得暗影之舞效果。\n\n当暗影之舞结束时，你会传送回你的暗影所在位置。","汉化"},
[1569678] = {"禁忌之舞","使伏击的能量消耗降低S2点，且施放|cFFFFFFFF禁忌招式|r使你获得|cFFFFFFFF禁忌之舞|r。\n\n@s:1569658:0@","汉化"},
[1569696] = {"水法师：水之新星","对敌方目标施放冰霜震击会留下一滩水，持续1569734d，并施加|cFFFFFFFF浸湿|r。此效果有15秒冷却。\n\n使用闪电箭或闪电链造成伤害，使水体带电，在1569735d内持续造成自然伤害。\n@s:1569736:0@","汉化"},
