[1569762] = {"水法师：电击","你的|cFFFFFFFF水之新星|r现在还会召唤一个潮汐池，持续1569736d，对停留在其中的敌人施加浸湿效果。\n@s:1569736:0@\n@s:1569739:0@","汉化"},
[1569785] = {"水法师：导体","水箭或冰霜震击造成伤害会使你触发闪电过载的几率提高1569763s1%，最多叠加3次，持续1569763d。","汉化"},
[1569932] = {"目标锁定","当|cFFFFFFFF战斗降落伞|r生效时，你的猎人射击会施加|cFFFFFFFF目标锁定！|r并立即触发一阵|cFFFFFFFF轨道箭攻击|r。\n\n@ext:逃脱现在也会触发战斗降落伞:ext@\n@s:1569934:0@\n@s:272137:0@","汉化"},
[1569955] = {"伞兵","将你直接向上发射并激活|cFFFFFFFF战斗降落伞|r。\n\n@ext:使用逃脱修正值:ext@\n@s:1569933:0@","汉化"},
[1570000] = {"自动开火","当|cFFFFFFFF战斗降落伞|r结束时你获得|cFFFFFFFF自动开火|r。\n@s:1569935:0@","汉化"},
[1570088] = {"急速闪现","你具有施法时间的伤害性法术会减少闪现术的冷却时间/1000;272182S1秒。\n\n此效果每秒只能触发1次，并且只对生物生效。","汉化"},
[1570109] = {"绽放生长","使用|cFFFFFFFF愈合|r产生爆击治疗时，会为10码范围内的另1名小队或团队成员施加其持续治疗效果。","汉化"},
[1570130] = {"绽放之力","施放迅捷治愈使你获得|cFFFFFFFF自然之赐|r（需学会天赋），并使你下一个愈合或滋养的爆击率提高1570131s1%。","汉化"},
[1570238] = {"自然狂热","当你对敌人施加的割伤叠满层时，使你获得|cFFFFFFFF自然狂热|r。\n@s:1570262:0@","汉化"},
[1570283] = {"热烈撕扯","","汉化"},
[1570306] = {"狂热精灵之火","当对敌人施加满层割伤时，你将获得|cFFFFFFFF自然狂热|r。该增益会随着已掌握的狂热天赋数量获得强化，并在触发时增强相关技能效果。\n@s:1570307:0@","汉化"},
[1570327] = {"狂野突袭","施放直接伤害的猎人技能有50%几率使你获得|cFFFFFFFF狂野突袭|r。\n@s:1570328:0@","汉化"},
[1570349] = {"无情之怒","使你的驯服宠物进入狂暴状态，持续d，造成%额外伤害，威胁值降低%，并重置狂乱射击的冷却时间。\n\n触发|cFFFFFFFF野兽之心|r（需学会），但不会获得控制免疫效果。\n\n最多可储存2层充能，充能恢复时间为2分钟。|cFFFFFFFF野兽突击|r可快速恢复充能。","汉化"},
[1570372] = {"雷克萨的门徒","使你的狂野怒火和|cFFFFFFFF野兽之心|r的持续时间延长/1000;S1秒。","汉化"},
[1570395] = {"鲜血追踪者：致命撕咬","猫鼬撕咬或反击造成伤害会施加|cFFFFFFFF致命撕咬|r。\n\n@s:1570396:0@","汉化"},
[1570417] = {"鲜血追踪者：连锁飞刃","你的飞刃会额外弹射2个目标，且致命撕咬每层使飞刃的伤害提高1570419s1%。\n\n另外，对受致命撕咬影响的敌人使用飞刃会使目标的移动速度降低1570420s1%，持续1570420d。","汉化"},
[1570439] = {"野蛮利刃","你向敌人投掷野蛮利刃，造成%远程武器伤害。","汉化"},
[1570460] = {"尖锐利刃","致命撕咬造成伤害有50%几率获得|cFFFFFFFF尖锐利刃|r。\n\n@s:1570440:0@","汉化"},
[1570482] = {"死亡本能","使用侧翼打击会使你接下来的3个猫鼬撕咬或反击技能造成的伤害提高1570462s1%。","汉化"},
[1570502] = {"燃烧吧！","施放火球术、灼烧、霜火之箭和炎爆术会使你的下一个火焰冲击的爆击率提高1570503s1%，法力消耗降低1570503s2%，最多叠加1570503u次。","汉化"},
[1570523] = {"寒冰弹幕","寒冰箭造成伤害会生成冰刺。最多可储存5枚冰刺。\n\n使用冰枪术造成伤害时会快速发射储存的冰刺，对目标造成1570530m1*scalingbp+SP*0.2点冰霜伤害。\n\n@ext:冰刺发射期间无法获得新冰刺。:ext@","汉化"},
[1570574] = {"圣化打击","你的十字军打击、神圣风暴和正义之锤有50%几率创造|cFFFFFFFF圣化之地|r。","汉化"},
[1570582] = {"圣化武器","你的奉献会强化你的武器，持续1570602d，使你的近战爆击率提高1570602s2%，且攻击有几率恢复1570603s1%基础法力。","汉化"},
[1570674] = {"暗影幻象","使用精神鞭笞造成伤害现在会获得一个|cFFFFFFFF灵魂碎片|r。积累9个碎片后，你将获得|cFFFFFFFF暗影幻象|r。\n\n@s:1570675:0@","汉化"},
[1570695] = {"瘟疫的幻象","","汉化"},
[1570700] = {"暗影幻象","@req:1115407req@\n心灵鞭笞造成伤害会使你获得1个|cFFFFFFFF灵魂碎片|r。累计9个碎片后，你会获得|cFFFFFFFF暗影幻象|r。\n\n@s:1570702:0@","汉化"},
[1570716] = {"自然能量","@req:1101329:req@\n毒伤生效期间，你的毁伤能量消耗降低1570717s1点。","汉化"},
[1570737] = {"溃烂","@req:1101329:req@\n你的毁伤爆击会施加|cFFFFFFFF溃烂|r。此外，你的致命毒药最多叠加8层，且当层数超过5层时，每层使毒伤伤害提高5%。\n@s:1570738:0@","汉化"},
[1570759] = {"雷霆轰鸣","闪电箭或闪电链造成伤害会使你的下一个大地震击的伤害和爆击率提高1570760s1%。最多叠加1570760u次，持续1570760d。\n\n另外，使触发闪电过载的几率提高%。","汉化"},
[1570783] = {"裂响的回声","","汉化"},
[1570865] = {"修葺之潮","@req:1161295:req@\n当你使用激流治疗队友时，会施加修葺之潮。同一时间只能对一名队友生效。\n@s:1570866:0@","汉化"},
[1570887] = {"修复之链","使用|cFFFFFFFF修葺之潮|r进行治疗时，现在会施加|cFFFFFFFF修复锁链|r。\n@s:1570888:0@","汉化"},
[1570908] = {"无尽痛苦","痛苦诅咒造成伤害会施加|cFFFFFFFF无尽痛苦|r。\n\n当你的痛苦诅咒目标死亡时，所有|cFFFFFFFF无尽痛苦|r层数将扩散至附近10码范围内的敌人。\n@s:1570909:0@","汉化"},
[1570974] = {"恶魔统御","@req:1159672:req@\n恶魔变形期间，你的恶魔和野生小鬼造成的伤害提高1570975s1%。","汉化"},
[1570995] = {"恶魔再现","@req:1159672:req@\n恶魔变形的冷却时间缩短/1000;s1秒，但提供的额外护甲降低%，且你不再受益于被爆击几率降低、昏迷和诱捕持续时间缩短。","汉化"},
[1571016] = {"狂野邪火","@req:1150796:req@\n混乱之箭造成伤害会召唤火雨，每秒对附近敌人造成1571017m1*scalingbp+SP*0.04点火焰伤害，持续1571017d。","汉化"},
[1571037] = {"可控混乱","施放有施法时间的法术会减少|cFFFFFFFF混乱之箭|r的冷却/1000;272775S1秒。","汉化"},
[1571058] = {"邪火灌注","|cffffffff野性邪火|r造成伤害使你获得|cffffffff邪火灌注|r。\n@s:1571059:0@","汉化"},
[1571106] = {"暮色之拥","施放暗影之舞会对8码内所有敌人施加5层|cFFFFFFFF暗影印记|r。\n\n对|cFFFFFFFF暗影印记|r目标发动伏击使你获得|cFFFFFFFF暮色之拥|r。\n@s:1571108:0@","汉化"},
[1571129] = {"平息暗影","@req:1151713:req@\n使用暗影之舞会引发暗影爆发，使附近敌人的移动速度降低1571130s1%，持续1571130d，并施加3层暗影标记。\n\n对被标记的敌人使用伏击可使你在1571149d内无视暗影步的冷却时间，并使你的伤害提高1571148s1%，持续1571148d。\n\n使用暗影步会为你恢复1571141s1点能量值。\n\n@ext:对玩家目标仅施加1层标记。:ext@","汉化"},
[1571150] = {"迅捷暗影","使你的|cFFFFFFFF暗影步|r持续时间延长/1000;S2秒。\n\n伏击|cFFFFFFFF暗影印记|r目标会重置暗影步冷却。","汉化"},
[1571172] = {"死亡暗影","对受到你割裂影响的目标使用伏击会对目标周围5码范围内的敌人触发额外%的暗影伤害。","汉化"},
[1571194] = {"回响的战吼","","汉化"},
[1571240] = {"战斗疲劳","你的战士怒吼、战旗和|cFFFFFFFF战嚎|r现在会对10码内的敌人施加|cFFFFFFFF战斗疲劳|r。\n\n@ext:战士怒吼或战旗每30秒只能触发1次此效果。:ext@\n@s:1571220:0@","汉化"},
[1571260] = {"神圣对称","@req:1147540:req@\n苦修造成伤害会使你下一个苦修的治疗效果提高1571261s1%。\n\n苦修进行治疗会使你下一个苦修的伤害提高1571284s1%。","汉化"},
[1571306] = {"古怪法师","你的攻击性法师法术有15%几率无消耗施放一个额外的随机法师法术。","汉化"},
[1571327] = {"虚空先驱：古神低语","暗言术：痛造成伤害时，有33%几率召唤古神触须攻击敌人。\n\n此效果每3秒最多触发一次。","汉化"},
[1571354] = {"黑暗之握","引导黑暗能量，在3秒内造成(m3*scalingbp+SP*0.64)*3点暗影伤害。每次造成伤害，暗影魔的冷却时间就会减少/1000;1571359s1秒。\n\n你控制的每个|cFFFFFFFF古神触须|r都会使你造成的伤害提高1571332s1%，爆击率提高1571332s2%。","汉化"},
[1571358] = {"古神低语：黑暗之握","","汉化"},
[1571378] = {"虚空先知：古神的疯狂","@req:1571327@\n召唤暗影魔时会在目标敌人附近召唤3个古神触须。\n\n每召唤一个|cFFFFFFFF古神触须|r会使你的伤害提高1571329s1%，持续1571329d。","汉化"},
[1571400] = {"神圣光辉","治疗术、强效治疗术或快速治疗为一名盟友治疗时，会为所有受到你恢复影响的盟友触发|cFFFFFFFF神圣辉光|r。\n@s:1571401:0@","汉化"},
[1571422] = {"恢复赦免","@req:1147540:req@\n苦修会消耗你的恢复效果，额外治疗目标1571424m1*scalingbp)+(SP*0.4点神圣治疗量。","汉化"},
[1571465] = {"圣洁祝福","你的圣骑士治疗法术有h%几率触发一个随机祝福效果。此效果每10秒只能触发一次。\n\n@s:1571467:0@\n@s:1571470:0@\n@s:1571471:0@","汉化"},
[1571621] = {"烈焰先驱","你的伤害性法术和技能现在有h%几率触发火焰爆裂，造成(PL*3+1571622m1)+(SP*0.1828)+(AP*0.1828)点火焰伤害，并在1571622d内每秒额外造成(PL*0.5+1571622m2)+(SP*0.0457)+(AP*0.0457)点火焰伤害。","汉化"},
[1571635] = {"重燃","使你对你的神圣之火影响的目标造成的所有伤害提高%，并使其持续时间延长0.6秒。","汉化"},
[1571636] = {"重燃","使你对你的神圣之火影响的目标造成的所有伤害提高%，并使其持续时间延长1.2秒。","汉化"},
