[1571662] = {"绝境曙光","使你的神圣之火和惩击的爆击率提高%。另外，消耗圣光涌动会使你的法术急速提高1581028s1%，持续1581028d，最多叠加1581028u次。","汉化"},
[1571663] = {"圣光涌动雕文","在圣光涌动的效果下，使惩击和快速治疗的效果提高%。","汉化"},
[1571664] = {"神圣飞升","使你的神圣之火的爆击率提高%。施放神圣之火会使你接下来2次惩击的伤害和爆击率提高1571665s1%。\n\n当你对自己施放守护之魂时，你会获得|cFFFFFFFF神圣飞升|r。\n@s:1571681:0@","汉化"},
[1571694] = {"狂热烙印","使你的正义圣印造成的伤害提高%。\n\n使用审判会强化驱邪术、神圣震击和神圣愤怒，使其能够触发你的正义圣印效果，持续1571699d。","汉化"},
[1571727] = {"迅捷飞升","施放惩击会使神圣之火的冷却时间减少/1000;1571729s1秒。","汉化"},
[1571748] = {"神圣之力","|cFFFFFFFF正义决心|r造成伤害时，每击中一个敌人会获得|cFFFFFFFF神圣之力|r。\n@s:1571728:0@","汉化"},
[1571768] = {"关键剑圣","招架攻击现在会使你获得|cFFFFFFFF剑圣|r。\n\n每个激活的剑圣附魔都会进一步强化此增益效果，且该增益效果会被消耗以强化受影响的技能。剑圣处于激活状态时无法再次触发。\n@s:1571771:0@","汉化"},
[1571793] = {"毁灭剑圣","招架一次攻击后，你的下一个毁灭打击造成额外1571795s1%的伤害。","汉化"},
[1571819] = {"战术剑圣","招架攻击现在会使你获得|cFFFFFFFF剑圣|r。每掌握一个剑圣天赋，此增益效果都会进一步增强。\n\n@ext:剑圣处于激活状态时无法再次触发。:ext@\n@s:1571820:0@","汉化"},
[1571842] = {"神圣剑圣","招架攻击会使你获得|cFFFFFFFF剑圣|r。每掌握一个剑圣天赋，此buff的效果都会进一步增强。\n\n@ext:剑圣处于激活状态时无法再次触发。:ext@\n@s:1571843:0@","汉化"},
[1571904] = {"重压","压制造成伤害会获得2层|cFFFFFFFF重压|r，猛击和斩杀会获得1层，最多叠加1571905u层。\n\n达到最大层数后，你的下一个致死打击或雷霆一击将被强化。\n@s:1571905:0@\n@s:1571909:0@","汉化"},
[1571951] = {"溢出","施放滋养或愈合会使你下一个治疗之触的施法时间和法力消耗降低1571953s1%，最多叠加3层。当叠加至3层时，你的下一个治疗之触触发溢出，对目标8码范围内的3名盟友恢复治疗量1571955s2%的生命值，并必定在目标身上触发一颗生命之种。","汉化"},
[1572015] = {"治疗之种","治疗之触现在会在非爆击治疗时施加生命之种（需学会）。","汉化"},
[1572035] = {"原生暗影","施放暗影箭和暗影灼烧会使暗影箭的伤害提高1572037s1%，暗影冲撞伤害提高1572037s3%，暗影之怒伤害提高1572037s2%，持续1572037d，最多叠加5层。","汉化"},
[1572039] = {"暗影冲击","向目标位置投掷一团缓慢移动的暗影能量，对8码范围内的敌人造成暗影伤害，将其拉向爆炸中心并使其移动速度降低1572040s3%，持续1572040d。","汉化"},
[1572043] = {"暗影冲击","向目标位置投掷一团缓慢移动的暗影能量，对8码范围内的敌人造成暗影伤害，将其拉向爆炸中心并使其移动速度降低1572040s3%，持续1572040d。","汉化"},
