[1572102] = {"血色冠军","格挡几率提高%，格挡对攻击者造成((PL-40)*2.2+m2)+(SP*0.045)+(AP*0.045)点神圣伤害。\n\n@ext:使用神圣之盾修正值。此效果每秒只能触发一次。:ext@","汉化"},
[1572131] = {"血色防御","格挡攻击使你获得|cFFFFFFFF血色防御者|r。\n\n@s:1572103:0@","汉化"},
[1572215] = {"左右开弓","你的英勇打击将同时触发副手武器攻击，造成额外武器伤害。\n\n使用英勇打击后，你的副手攻击伤害提高1572217s1%，持续1572217d，最多可叠加1572217u层。","汉化"},
[1572237] = {"左撇子打击","使用嗜血、斩杀和撕裂会立即用你的副手触发一次攻击，造成1572238s1%武器伤害并使你获得|cFFFFFFFF左撇子|r。\n@s:1572239:0@\n@ext:此效果每16秒只能触发1次，并且左撇子无法于统御同时生效:ext@","汉化"},
[1572260] = {"猛兽之怒：愤怒打击","@req:1316975:req@@req:1116975:req@\n你的终结技每消耗一个连击点数有b1%的几率使你获得|cFFFFFFFF愤怒打击|r。\n@s:1572240:0@","汉化"},
[1572285] = {"猛兽打击","施放愤怒使你获得|cFFFFFFFF猛兽打击|r.\n@s:1572262:0@","汉化"},
[1572306] = {"猛兽之怒：集中","施放愤怒恢复1572286s2点能量。","汉化"},
[1572326] = {"泰坦之怒","怒气值高于50时使用旋风斩会使你获得|cFFFFFFFF泰坦之怒|r。怒气值低于50时使用则使你获得|cFFFFFFFF泰坦英勇|r。\n\n@s:1572330:0@\n@s:1572332:0@","汉化"},
[1572351] = {"怒气滔天","使你的最大怒气值提高/10;s1。","汉化"},
[1572374] = {"泰坦打击","使用两把武器发动攻击，造成%武器伤害。并使你下2个技能的爆击率提高1572378s1%。","汉化"},
[1572419] = {"血腥爪击","爪击消耗的能量降低点，并获得相当于你攻击强度%的额外伤害。","汉化"},
[1572439] = {"锋锐利爪","爪击造成伤害使你获得|cFFFFFFFF锋锐利爪|r，\n@s:1572440:0@","汉化"},
[1572527] = {"暮光圣徒","惩击和神圣之火造成直接伤害时，获得|cFFFFFFFF光明圣徒|r。\n@s:1572528:0@\n暗言术：灭会消耗这些层数，根据消耗的层数造成暮光伤害，并使你获得|cFFFFFFFF黑暗圣徒|r。\n@s:1572531:0@","汉化"},
[1572574] = {"粉碎者","你的|cFFFFFFFF致死打击|r会施加|cFFFFFFFF粉碎|r。\n\n|cFFFFFFFF致死打击|r每20秒只能触发一次此效果。\n@s:1572575:0@","汉化"},
[1572620] = {"开膛","终结技，对目标施加开膛效果，造成持续伤害。此流血状态下，目标会受到你的毁伤额外伤害。\n1点：在d内造成(m1+b1*1+0.008*AP)*3点伤害\n2点：在d内造成(m1+b1*2+0.016*AP)*3点伤害\n3点：在d内造成(m1+b1*3+0.024*AP)*3点伤害\n4点：在d内造成(m1+b1*4+0.032*AP)*3点伤害\n5点：在d内造成(m1+b1*5+0.04*AP)*3点伤害\n\n@ext:使用剔骨的修正值。:ext@","汉化"},
