[1572629] = {"开膛","终结技，对目标施加开膛效果，造成持续伤害。此流血状态下，目标会受到你的毁伤额外伤害。\n1点：在d内造成(m1+b1*1+0.008*AP)*3点伤害\n2点：在d内造成(m1+b1*2+0.016*AP)*3点伤害\n3点：在d内造成(m1+b1*3+0.024*AP)*3点伤害\n4点：在d内造成(m1+b1*4+0.032*AP)*3点伤害\n5点：在d内造成(m1+b1*5+0.04*AP)*3点伤害\n\n@ext:使用剔骨的修正值。:ext@","汉化"},
[1572630] = {"开膛","终结技，对目标施加开膛效果，造成持续伤害。此流血状态下，目标会受到你的毁伤额外伤害。\n1点：在d内造成(m1+b1*1+0.008*AP)*3点伤害\n2点：在d内造成(m1+b1*2+0.016*AP)*3点伤害\n3点：在d内造成(m1+b1*3+0.024*AP)*3点伤害\n4点：在d内造成(m1+b1*4+0.032*AP)*3点伤害\n5点：在d内造成(m1+b1*5+0.04*AP)*3点伤害\n\n@ext:使用剔骨的修正值。:ext@","汉化"},
[1572631] = {"开膛","终结技，对目标施加开膛效果，造成持续伤害。此流血状态下，目标会受到你的毁伤额外伤害。\n1点：在d内造成(m1+b1*1+0.008*AP)*3点伤害\n2点：在d内造成(m1+b1*2+0.016*AP)*3点伤害\n3点：在d内造成(m1+b1*3+0.024*AP)*3点伤害\n4点：在d内造成(m1+b1*4+0.032*AP)*3点伤害\n5点：在d内造成(m1+b1*5+0.04*AP)*3点伤害\n\n@ext:使用剔骨的修正值。:ext@","汉化"},
[1572720] = {"精神苦修","@req:1147540:req@\n使苦修的引导时间延长%，使其获得强化额外发射一发圣光箭，但还会使其冷却时间延长/1000;1572721s1秒。","汉化"},
[1572740] = {"风暴之锤","将你的武器投向敌人，造成%武器伤害并使目标昏迷d，使地面带电，对附近的敌人造成1572743m1*scalingbp+AP*0.1点自然伤害。\n\n若目标是怪物，还会使你受到的伤害降低1572741s1%，持续1572741d。","汉化"},
[1572875] = {"时间加速","施放奥术冲击会使你的下一个非奥术冲击的直接伤害法术的施法时间缩短1572846S1%。最多叠加3次，持续d。\n\n@ext:对引导类法术无效:ext@","汉化"},
[1572909] = {"风暴之子","@req:1130823:req@\n当萨满之怒激活时，风暴打击会对你前方的敌人造成额外1572910m1*scalingbp+AP*0.2点自然伤害。\n\n@ext:命中超过5名敌人时，此伤害会被分摊。:ext@","汉化"},
[1572931] = {"侵蚀风暴","当拥有3层或更多|cFFFFFFFF漩涡武器|r时，施放闪电箭或闪电链将使元素掌握和萨满之怒的冷却时间减少/1000;274086S1秒。","汉化"},
[1572975] = {"闪电掌握","闪电箭或闪电链造成伤害会使元素掌握的冷却减少/1000;1572976S1秒。","汉化"},
[1573425] = {"剧毒之刃","毒伤造成伤害会使你的连击点产生技能的爆击率提高1573426s1%，最多叠加1573426u层，持续1573426d。另外，使用君王之灾会触发灭绝天赋（需学会）。","汉化"},
[1573468] = {"血腥攻击","撕裂、绞喉或割裂造成伤害使你获得|cFFFFFFFF血腥攻击|r。\n@s:1573470:0@","汉化"},
[1573538] = {"血毒","消耗10层|cFFFFFFFF剧毒打击|r后，将对目标施加|cFFFFFFFF血毒|r。\n@s:1573518:0@","汉化"},
[1573558] = {"火焰警戒","当你的献祭陷阱或爆炸陷阱触发时，你的猛禽一击、猫鼬撕咬和反击将额外造成1573559s1%的火焰伤害，持续1573559d。\n\n另外，击杀可获得经验值或荣誉的敌人后，献祭陷阱和爆炸陷阱的冷却时间会被重置。","汉化"},
[1573649] = {"焚化","教会你：焚化。\n@s:1573650:-48@","汉化"},
[1573650] = {"焚化","在1573651d内造成1573649m1*scalingbp点火焰伤害，并额外造成你点燃、炎爆术和活体炸弹总持续伤害的2倍伤害，这些持续伤害效果会被消耗。该持续伤害可爆击。","汉化"},
[1574164] = {"飓风打击","立即用双武器发动攻击，造成(PL*2+274832m1)+(AP*0.9)+(SP*0.9)到(PL*2+274832M1)+(AP*0.9)+(SP*0.9)点物理伤害。\n\n获得|cFFFFFFFF飓风之刃|r后可使用1次。你的近战攻击有1574165h%几率获得|cFFFFFFFF飓风之刃|r。最多可储存3层充能，持续274834d。\n\n@ext:使用飓风术修正值:ext@\n@ext:你每6秒只能获得1次|cFFFFFFFF飓风之刃|r:ext@","汉化"},
[1574368] = {"潮汐掌握","@req:1161295:req@\n你的治疗链不再消耗激流。","汉化"},
[1574692] = {"乘胜破釜","@req:1112975:req@\n|cFFFFFFFF乘胜追击|r造成伤害会使|cFFFFFFFF破釜沉舟|r的冷却时间减少/1000;1574693S1秒。\n\n使用|cFFFFFFFF破釜沉舟|r会获得1次|cFFFFFFFF乘胜追击|r的使用次数。","汉化"},
[1574734] = {"壁垒掌握","引导|cFFFFFFFF壁垒|r时，你的精确格挡获得额外8%的伤害减免。","汉化"},
[1574754] = {"壁垒","举起一道强大的壁垒，使你获得%的格挡几率，并每秒对附近敌人造成基于你的盾牌格挡值的物理伤害，但移动速度降低%，持续d。","汉化"},
[1574868] = {"星空恢复","触发|cFFFFFFFF交蚀|r现在会恢复你已损失法力值的1574869s1%。","汉化"},
[1574987] = {"复合射击","终结技，使目标受到的治疗效果降低S2%，持续6秒，并根据连击点造成远程武器伤害加上RAP*0.20+m1：\n1点：m3+(b3*1)%武器伤害。\n2点：m3+(b3*2)%武器伤害。\n3点：m3+(b3*3)%武器伤害。\n4点：m3+(b3*4)%武器伤害。\n5点：m3+(b3*5)%武器伤害。\n\n此技能可在3秒内再次施放发射一发连击射击。\n\n@ext:使用瞄准射击修正值。:ext@","汉化"},
[1575034] = {"光明之王","使你的神圣伤害提高%，但造成的物理伤害降低%。\n\n你的十字军打击、神圣风暴和正义之锤会造成额外神圣伤害。使用法术强度修正值。","汉化"},
[1575104] = {"手感发烫","@req:1111366:req@\n@req:1144445:req@\n炎爆术也能触发|cFFFFFFFF法术连击|r。","汉化"},
[1575124] = {"爆击时刻","@req:1144457:req@\n你的法术对活体炸弹目标的爆击率提高%。","汉化"},
[1575126] = {"引燃","冲击波不再击退，冲击波和龙息术的爆击率提高%。\n\n你的一触即燃天赋使你可以施放2次烈焰风暴。","汉化"},
[1575328] = {"冻结烈焰","你的寒冰箭、冰枪术和冰锥术爆击时会使目标被冻结烈焰灼烧，额外造成(PL*2+1575308m1)+(SP*0.1)+(AP*0.065)点火焰伤害。","汉化"},
[1575770] = {"撕裂风暴","猩红风暴的持续时间延长/1000;S1秒。","汉化"},
[1575790] = {"浴血","剔骨、毒伤、斩击和致命投掷根据目标身上的每个流血效果每消耗一个连击点有20%几率使你获得|cFFFFFFFF浴血|r。\n@s:1575791:0@","汉化"},
[1575880] = {"猛攻","使用巨人打击后，你的下一个斩杀可忽视目标生命值施放。此外，巨人打击的冷却时间减少/1000;s2秒。","汉化"},
[1575922] = {"古拉巴什之怒","进入狂暴状态，造成伤害产生的所有怒气提高%，并使近战技能的爆击率提高%，持续d。\n\n此技能变形时可用。\n\n@ext:此技能使用鲁莽修正值。:ext@","汉化"},
[1575942] = {"战斗狂怒","破城者爆击使你获得1层怒击充能，并获得4秒的|cFFFFFFFF古拉巴什之怒|r。\n@s:1575922:0@","汉化"},
[1575987] = {"怒击猛攻","@req:2304836:req@\n使用嗜血有h%几率使你获得|cFFFFFFFF狂怒解放|r。击杀可获得经验或荣誉的对象有100%几率获得|cFFFFFFFF狂怒解放|r。\n\n@s:2304839:0:s@","汉化"},
[1576007] = {"狂暴猛冲","使用致死打击、斩杀、猛击、旋风斩和嗜血造成伤害时，现在有25%的几率产生一层狂暴打击充能。\n\n@ext:此效果每6秒仅能触发一次。:ext@","汉化"},
[1576077] = {"恶魔虹吸","当你的生命吸取造成伤害时，还会为你的召唤恶魔恢复其生命值的1576076s1%，并使其伤害提高1576076s2%，最多叠加1576076u次，持续1576076d。","汉化"},
[1576098] = {"受难之魂","吸取灵魂造成伤害会施加|cFFFFFFFF灵魂撕裂|r。\n\n@s:1576078:0@","汉化"},
[1576497] = {"地刺","你猛踏地面，在目标脚下引发岩刺迸发，造成%副手武器伤害。若副手武器附有石化武器，则伤害翻倍。\n\n@ext:使用熔岩猛击修正值:ext@","汉化"},
[1576573] = {"屠杀化身","被鲜血与白骨包裹，每秒对附近敌人造成1576574m1*scalingbp)+(AP*0.02点物理伤害，并治疗自身1576575m1*scalingbp)+(AP*0.02点生命值。持续d。","汉化"},
[1576816] = {"易碎护甲","你的物理技能对受到破甲效果影响的目标造成额外(PL*1.5+1576817m1)+(SP*0.05)+(AP*0.05)点物理伤害。","汉化"},
[1577291] = {"恶魔意志","烧尽造成伤害会牺牲你生命值最低的野生小鬼，使其爆炸并对8码范围内的所有敌人造成1577295m1*scalingbp+SP*0.25点火焰伤害。\n\n此外，你的召唤恶魔和野生小鬼的伤害提高1577293s1%，最多叠加4层。\n\n每存在1层，你的野生小鬼持续时间延长1秒。","汉化"},
[1577316] = {"古尔丹的异教徒","你的烧尽会使古尔丹之手的冷却时间缩短1秒。爆击使其冷却时间缩短2秒。","汉化"},
[1577339] = {"无尽烈焰","|cFFFFFFFF火焰冲撞|r和|cFFFFFFFF暗影烈焰|r的持续时间延长/1000;S1秒。另外，暗影烈焰造成的伤害提高%。","汉化"},
[1577360] = {"诅咒暗影","痛苦诅咒造成伤害会使你的下一个暗影箭的伤害提高1577340s1%。最多叠加1577340u次，持续1577340d。","汉化"},
[1577402] = {"火焰暗影","@req:1118096:req@\n你的|cFFFFFFFF火焰冲撞|r天赋还会使|cFFFFFFFF暗影箭|r的爆击率提高1577382s1%。","汉化"},
[1577465] = {"拘束之力","你的拘束元素爆击会使你获得|cFFFFFFFF元素空气|r。\n\n施放元素冲击使你获得|cFFFFFFFF元素协同|r。\n@s:1577466:0@\n@s:1577469:0@","汉化"},
[1577487] = {"源生余震","你的元素冲击和熔岩爆裂爆击会重置你的震击法术冷却时间。","汉化"},
[1577613] = {"手枪射击","@req:997610@\n射击手枪，造成相当于远程武器伤害%加的伤害。奖励点连击点。\n\n@ext:使用邪恶攻击修正值，并受益于穿刺射击天赋。:ext@","汉化"},
