[1577969] = {"冰霜火焰守卫：召唤","当你获得4层或以上|cFFFFFFFF凝聚意志|r或|cFFFFFFFF寒冬斗篷|r效果加持时，施放烈焰或极寒会使其施法时间缩短35%，并向附近敌人释放一轮弹幕攻击。","汉化"},
[1578104] = {"暗影炮击","向目标位置发射暗影炮击，造成(PL*3.5+m1)+(SP*0.45)+(AP*0.45)点暗影伤害，并在接下来的d内每秒对附近敌人造成额外的(PL*1.3+m2)+(SP*0.05)点暗影伤害。施放时恢复你基础法力值的35%。\n\n最大1次充能，45秒再充能时间。消耗3层|cFFFFFFFF暗影炮弹|r代替充能。\n\n@ext:受益于熔火之心天赋。命中超过5个目标时伤害分摊。:ext@","汉化"},
[1578497] = {"船长的决心","@req:997610@\n防御姿态的暴徒架势使你获得|cFFFFFFFF船长的决心|r和|cFFFFFFFF偏移|r伤害。\n\n@ext:变形或主属性为精神时不生效:ext@\n\n@s:277050:0@\n@s:1578477:0@","汉化"},
[1578501] = {"准备战斗！","使用惩戒痛击会使你的招架几率提高1578502s1%，持续1578502d。","汉化"},
[1578681] = {"灵魂虚空","吸取灵魂造成伤害现在会施加灵魂虚空。叠加至3层时施加枯萎灵魂效果，使你的生命吸取从目标身上转移的生命值提高1578683s1%，持续1578683d。\n\n@ext:带有枯萎灵魂效果的敌人不会获得灵魂虚空效果。:ext@","汉化"},
[1578703] = {"古尔丹的抉择","@req:1150796:req@\n施放混乱之箭会使你的毁灭系法术在1578704d内不消耗爆燃天赋。","汉化"},
[1578753] = {"致命毁灭","@req:1117962:req@\n施放燃烧会使你下一个灵魂之火的施法时间缩短40%并移除其灵魂碎片消耗。","汉化"},
[1578806] = {"元素领袖","施放风暴打击和熔岩猛击会使你的强效元素图腾的冷却时间减少/1000;277166S1秒。\n\n施放萨满震击和元素冲击会使你的强效元素图腾获得|cFFFFFFFF元素领袖|r。相同法术每20秒只能触发1次。\n@s:1578811:0@","汉化"},
[1578857] = {"灾变裂地","使用裂地术会在地面留下一片燃烧的熔岩区域，在1578858d内每秒对敌人造成1578858m1*scalingbp+SP*0.05点火焰伤害。","汉化"},
[1578906] = {"强化狼群","萨满附魔武器造成伤害会使你获得|cFFFFFFFF命令|r。此效果最多叠加1578909u层，持续1578909d。施放野性狼魂会消耗这些效果。\n\n@s:1578909:0@\n@s:277194:0@\n@s:277195:0@","汉化"},
[1578936] = {"发射爆炸陷阱","将你的爆炸陷阱直接发射至目标位置，而非放置在地面。陷阱将在命中时爆炸。","汉化"},
[1578938] = {"发射献祭陷阱","将你的献祭陷阱直接发射至目标，而非放置在地面。陷阱将在命中时爆炸。","汉化"},
[1578960] = {"无形刺客","脱离潜行或激活暗影之舞后的3秒内，你的飞镖投掷仅触发0.5秒公共冷却。","汉化"},
[1578980] = {"连飞带掷","使用致命投掷会使你接下来的2次飞镖投掷或飞刃额外产生1个连击点，资源消耗降低20%，伤害提高20%，持续1578981d。","汉化"},
[1579001] = {"体能训练","激活疾跑时基于移动速度提高致命投掷和飞镖投掷造成的伤害。","汉化"},
[1579022] = {"冰川瀑布","每第4次施放寒冰箭会触发寒冰箭瀑布，额外攻击3名附近的敌人。","汉化"},
[1579067] = {"苦无大师","使用冲动获得|cFFFFFFFF苦无大师|r。\n\n@s:1579068:0@","汉化"},
[1579090] = {"双重射击","如果你的杀戮射击未能击杀目标，其冷却将减少/1000;1579091S1秒。","汉化"},
[1579113] = {"清除障碍","在急速射击或急速杀戮效果影响下，你的飞刃将消耗穿刺射击的流血效果，造成全额伤害并提高*100;s1%。","汉化"},
[1579308] = {"弹幕过载","@req:1144425:req@\n每层奥术冲击充能会使你的奥术弹幕释放纯净的奥术能量爆发，造成1579311m1*scalingbp+SP*0.18点奥术伤害。","汉化"},
[1579429] = {"君王之灾","从你的匕首释放致死毒药并注入目标体内，立即造成m1*scalingbp+AP*0.2点自然伤害，并在1579430d内额外造成(1570530m1*scalingbp+AP*0.1)*6点自然伤害。\n\n每次对受君王之灾影响的目标施加致命、速效或致伤毒药时，君王之灾的伤害提高1579432s1%。\n\n获得1579429s3个连击点。","汉化"},
[1579560] = {"居高临下","当你位于目标5码以上的高处时，造成相当于原伤害%的额外打击。","汉化"},
[1579580] = {"双重雷击","移除闪电链的冷却，但使其法力消耗提高S2%。","汉化"},
[1579602] = {"北风","冰霜震击会使你的移动速度提高1579603s1%，但不再使目标减速。","汉化"},
[1579644] = {"决斗者","对玩家使用嘲讽后会在其位置插下一面决斗旗，若目标逃离该区域，减少其移动速度1579624s1%，持续1579624d。","汉化"},
[1579665] = {"由火焰净化","","汉化"},
[1579706] = {"碎颅者","猛击造成伤害会使死亡之愿和剑刃风暴的冷却时间减少/1000;1579686S2秒。","汉化"},
[1579726] = {"猎鸭‌","当你对高于你5码的敌人造成伤害的技能和自动射击会驱散缓落术，并额外造成相当于原伤害%的攻击。","汉化"},
[1579746] = {"叉状闪电","闪电链击中目标后，会持续从首个被击中的目标向额外目标弹射叉状闪电。","汉化"},
[1579811] = {"三重灼烧","炎爆术的持续伤害能叠加3层。","汉化"},
[1579878] = {"领导狼群","@req:1151533:req@\n风暴打击或熔岩猛击对怪物造成伤害会使野性狼魂的冷却减少/1000;1579882S2秒。","汉化"},
[1579923] = {"云爆","使你的雷霆风暴与可控风暴的伤害提高1579924s1%，星界风暴与落雷之云的伤害提高1579925s1%。雷霆风暴的法力恢复效果提高%，施法时间减少/1000;S1秒。\n\n@ext:使雷霆风暴与可控风暴对玩家造成的伤害提高1579924s2%，星界风暴与落雷之云对玩家造成的伤害提高1579925s2%。:ext@","汉化"},
[1579945] = {"无尽虚空","暗影魔的冷却减少%。","汉化"},
[1579985] = {"大地化身","土元素图腾的冷却时间减少S1%。","汉化"},
[1580005] = {"多重法术反射","法术反射现在可额外反射个法术，但冷却时间延长%。","汉化"},
[1580025] = {"树众","@req:1133831:req@\n使你从自然之力召唤的树人持续时间延长%。","汉化"},
[1580047] = {"曲魂者","吸取灵魂造成伤害或施放生命分流会使你获得|cFFFFFFFF灵魂能量|r。\n@s:1580048:0@","汉化"},
[1580093] = {"狙击手","站立静止3秒使你获得|cFFFFFFFF狙击手|r。\n@s:1580073:0@","汉化"},
[1580113] = {"坠星","当星辰坠落激活时，使其其持续时间延长你施放的奥术系法术的施法时间的一半，并使你的法术爆击率提高1580115s1%。\n\n@ext:引导类法术不会延长持续时间。:ext@","汉化"},
[1580266] = {"隐秘之线","@req:1151713:req@\n当暗影之舞激活时，你的绞喉会击中附近个目标。","汉化"},
[1580289] = {"姿态舞","","汉化"},
[1580395] = {"淬毒","毒药对流血目标造成额外%伤害，同时毒伤的能量消耗降低点。","汉化"},
[1580478] = {"最终护盾","对生命值低于20%的盟友施放真言术：盾时，还会移除他们身上的所有控制效果。\n\n@ext:此效果每30秒只能触发一次:ext@","汉化"},
[1580498] = {"目瞪口呆","盾击会使敌人的施法速度减少1580499s1%，持续1580499d。\n\n@ext:此效果不与其他类似效果叠加:ext@","汉化"},
[1580519] = {"倒地不起","当杀戮盛筵击中流血或中毒的敌人时，会额外造成本次攻击%的伤害。","汉化"},
[1580539] = {"并肩作战","挑战怒吼会使盟友受到的伤害降低1580540S1%，并且其冷却时间缩短%。","汉化"},
[1580604] = {"诅咒箭","远程自动攻击有10%几率诅咒目标，当目标死亡时，它会召唤一个骷髅守护者为你战斗。","汉化"},
[1580646] = {"冰封禁锢","当你的寒冰屏障结束时，你会释放冰霜新星。","汉化"},
[1580666] = {"冰河时代","对附近的敌人造成(PL*2+m1)+(SP*0.0965)+(AP*0.0627)点冰霜伤害，并将其冰冻最多4秒，造成的伤害可打断冰冻效果。\n\n冰河时代无法被驱散。\n\n@ext:使用冰霜新星修正值。:ext@","汉化"},
[1580686] = {"惊恐","施放恐惧会使你的目标变得|cFFFFFFFF惊恐|r。\n\n@s:1580687:0@","汉化"},
[1580772] = {"变形专家","变形消耗减少%。","汉化"},
[1580792] = {"魔杖攻击","魔杖攻击使你获得下一个法术施法速度提高1580793s1%的叠层，最多叠加1580793u层，持续1580793d。","汉化"},
[1580883] = {"法力吸取","你的法力燃烧会摧毁额外%法力值，但造成的伤害降低30%，法力消耗提高30%，且冷却额外增加/1000;S3秒。","汉化"},
[1580923] = {"充能完毕","@req:1153301:req@\n将爆炸射击转化为爆炸射击（充能完毕）\n@s:1580925:0@","汉化"},
[1580925] = {"爆炸射击（充能完毕）","你向敌方目标发射一枚爆炸弹头，造成RAP*0.12+m1-RAP*0.12+M1点火焰伤害。弹头激活期间，将在d内每秒对目标造成一次额外爆炸，并使你的攻击无视1580924s1%的护甲。\n\n可在近战范围内使用。","汉化"},
[1580965] = {"神圣之地","在你的|cFFFFFFFF奉献|r范围内的盟友受到你的治疗效果提高1580967s1%。\n\n你对奉献范围内盟友的直接治疗会辐射5名盟友，治疗本次治疗量的5%。","汉化"},
[1580989] = {"钟摆","当法力值高于50%时，获得1580968s1%法术急速。\n\n当法力值低于50%时，获得81326s1%法术爆击率。","汉化"},
[1581027] = {"纯净圣光","@req:1133150:req@\n圣光涌动会使快速治疗或惩击爆击，并且可以叠加2次。但是，圣光涌动的法力消耗只降低1333151s2%。","汉化"},
[1581236] = {"灵魂虹吸者","你的鬼影缠身还会为3名生命值最低的小队或团队成员恢复生命值。","汉化"},
[1581256] = {"精灵虫群","你的精灵之火（野性）会施加虫群。","汉化"},
[1581298] = {"锋锐之爪","你的重殴会刷新你的目标身上的斜掠持续时间。","汉化"},
[1581319] = {"愤怒之盾","@req:1131935:req@\n你的复仇者之盾冷却时间减少%，但不再减速或弹射额外目标。","汉化"},
[1581380] = {"战地军医","治疗效果提高%。有效的直接治疗会为你和8码内的盟友施加|cFFFFFFFF战地军师|r。\n@s:1581381:0@","汉化"},
[1581405] = {"战地手术","为a1码范围内的所有盟友每秒治疗(PL*1.46+m1)+(SP*0.04125)+(AP*0.01)点生命值，持续d。\n\n@ext:战地手术使用神圣系或自然系治疗量中较高者的修正值。:ext@","汉化"},
[1581425] = {"神秘同伴","你的驯服宠物的自动攻击现在造成奥术伤害。\n\n@ext:你的驯服宠物的自动攻击同时只能转换为一种伤害类型。:ext@\n\n@ext:驯服宠物包括：召唤恶魔、奴役恶魔、支配亡灵、统率龙类、拘束元素和驯服野兽:ext@","汉化"},
[1581445] = {"冒烟同伴","你的驯服宠物的自动攻击现在造成火焰伤害。\n\n@ext:你的驯服宠物的自动攻击同时只能转换为一种伤害类型。:ext@\n\n@ext:驯服宠物包括：召唤恶魔、奴役恶魔、支配亡灵、统率龙类、拘束元素和驯服野兽:ext@","汉化"},
[1581465] = {"冰川同伴","你的驯服宠物的自动攻击现在造成冰霜伤害。\n\n@ext:你的驯服宠物的自动攻击同时只能转换为一种伤害类型。:ext@\n\n@ext:驯服宠物包括：召唤恶魔、奴役恶魔、支配亡灵、统率龙类、拘束元素和驯服野兽:ext@","汉化"},
[1581485] = {"带电同伴","你的驯服宠物的自动攻击现在造成自然伤害。\n\n@ext:你的驯服宠物的自动攻击同时只能转换为一种伤害类型。:ext@\n\n@ext:驯服宠物包括：召唤恶魔、奴役恶魔、支配亡灵、统率龙类、拘束元素和驯服野兽:ext@","汉化"},
[1581505] = {"幽影同伴","你的驯服宠物自动攻击现在造成暗影伤害。\n\n@ext:你的驯服宠物自动攻击同时只能被转换成一种伤害类型:ext@\n\n@ext:驯服宠物包括：召唤恶魔、奴役恶魔、支配亡灵、统率龙类、拘束元素和驯服野兽:ext@","汉化"},
[1581525] = {"懦夫克星","你的战士技能有h%几率使背对逃离你的敌人眩晕3秒。","汉化"},
[1581566] = {"至高之力","强效治疗术的治疗量提高%，但其法力消耗提高%。","汉化"},
[1581586] = {"图腾大师：火焰","你的火焰图腾获得你%的生命值，但其法力消耗提高%。","汉化"},
[1581606] = {"乌索克的祝福","熊形态的耐力与护甲加成在离开熊形态后仍会持续3秒。","汉化"},
[1581647] = {"虔诚打击","你的十字军打击和复仇者之盾会对附近敌人造成其伤害%的神圣伤害，并恢复1581627s2%的基础法力值。此效果会产生高额威胁值。","汉化"},
[1581667] = {"无情割伤","使用割伤会使目标的护甲降低1581668s1%，并使你对该目标的近战攻击爆击率提高1581668s2%，持续1581668d，最多叠加1581668u次。","汉化"},
[1581707] = {"集体意志","你的宁静现在会在治疗时恢复15%的基础法力值。","汉化"},
[1581729] = {"混乱显现","@req:1150796:req@\n施放混乱之箭后，你会获得火焰或暗影增效，使该系法术造成的伤害提高1581709s1%，持续1581709d。","汉化"},
[1581770] = {"命运窃贼","从目标身上窃取有益魔法效果。被盗效果最多持续2分钟。\n\n不会中断潜行。\n\n@ext:使用偷窃修正值。:ext@","汉化"},
[1581790] = {"锯口枪管","你的多重射击会击退主目标，或在空中发射时将你击退。多重射击的射程减少S2码，且冷却时间翻倍。","汉化"},
[1581811] = {"生长的循环","使生命绽放的持续治疗效果提高%，但绽放的治疗效果降低%。\n\n你的愈合会刷新目标身上生命绽放的持续时间。若目标已受到你的愈合影响，则此效果不会触发。","汉化"},
[1581832] = {"绝望","@req:1123881:req@\n嗜血的爆击率提高%，并根据你已损失的生命值最多造成%的额外伤害。","汉化"},
[1581852] = {"监狱战术","毒刃造成伤害会使你获得|cFFFFFFFF监狱战术|r。\n@s:1581853:0@","汉化"},
[1581873] = {"暗言术：压制","你的暗言术：灭亡会腐化地面，使7码范围内的敌人移动速度降低1581874s1%。","汉化"},
[1581894] = {"死亡萦绕","暗言术：灭造成伤害时，将抵消目标受到的治疗效果，抵消量等同于暗言术：灭造成的伤害。","汉化"},
[1581956] = {"节俭性格","当你使用次级治疗波造成过量治疗时，你的目标将在1581957d内持续得该过量治疗50%的治疗量。","汉化"},
[1581977] = {"宽容性格","当你的次级治疗波未能将盟友的生命值治疗满时，你的下一个次级治疗波必爆，持续1581978d。","汉化"},
[1581997] = {"雷霆轰击","@req:1146968:req@\n当震荡波击中受你雷霆一击影响的敌人时，会额外造成一次相当于伤害%的自然打击。每有一个敌人被该额外打击命中，震荡波的冷却时间就会减少1秒，最多减少5秒。","汉化"},
[1582017] = {"鲁莽奔袭","鲁莽现在还会在持续时间内使你的移动速度提高%。","汉化"},
[1582084] = {"黑暗舞者","潜行时，暗影之舞的冷却速度翻倍。","汉化"},
[1582104] = {"冰霜储备","水之护盾每层使你造成的直接冰霜伤害提高%。直接冰霜法术伤害会消耗1层水之护盾。","汉化"},
[1582124] = {"补充泉水","@req:1100724:req@\n你的直接神圣治疗法术会使光明之泉的冷却时间减少/1000;1582125S1秒。","汉化"},
[1582145] = {"刺骨之寒","当你的深度冻结造成伤害时，其冷却减少33%。有施法时间的伤害性法术会使你获得|cFFFFFFFF刺骨之寒|r。\n\n@s:1582147:0@","汉化"},
[1582190] = {"狩猎","治疗宠物还会使你的驯服宠物造成的伤害提高1582191s1%。","汉化"},
[1582211] = {"成功气息","乘胜追击使你获得|cFFFFFFFF成功气息|r，并造成%额外威胁值。\n@s:1582212:0@","汉化"},
[1582232] = {"热力震慑","寒冰箭会消耗你在目标身上的点燃，并使其沉默并缴械1582233d。","汉化"},
[1582316] = {"荆棘爆裂","从你的盟友的护甲中长出荆棘，持续d，对附近的敌人造成伤害，并在被击中时获得|cFFFFFFFF荆棘|r。\n\n此技能可在变形时使用。\n\n@ext:荆棘每8秒只能触发一次，伤害效果每秒只能出现一次。:ext@\n\n@s:1582318:0@","汉化"},
[1582341] = {"信仰护甲","当你对虚弱灵魂效果的盟友施放治疗术、强效治疗术、快速治疗或苦修时，他们会获得|cFFFFFFFF信仰护甲|r，在下次受到伤害时触发，恢复该效果治疗量15%的生命值。若该效果由苦修触发，则治疗量翻倍。","汉化"},
[1582361] = {"灵魂恢复","对盟友施放圣光术、强效治疗术、治疗波或治疗之触会使其虚弱灵魂的持续时间减少2秒。","汉化"},
[1582381] = {"冰冻血肉","@req:1144572:req@\n你的深度冻结对你的目标施加|cFFFFFFFF冰冻血肉|r。\n@s:1582382:0@","汉化"},
[1582405] = {"巧击","使佯攻的冷却减少/1000;S2秒，且佯攻会激活还击技能，持续1582406d。以此方式使用的还击爆击率提高20%。","汉化"},
[1582426] = {"致命巧击","佯攻使你下一个还击的爆击率提高1582427s1%，持续1582427d。","汉化"},
[1582447] = {"急速佯攻","佯攻的冷却时间减少/1000;S1秒。","汉化"},
[1582467] = {"神圣惩戒","在施法者周围引发一次高威胁的圣光爆炸，对所有敌方目标造成15237s1点神圣伤害，并为23455a1码范围内的所有团队成员治疗23455s1点生命值。\n\n攻击强度会提高此法术的伤害，但会降低其治疗量。\n\n@ext:使用神圣新星修正值。:ext@","汉化"},
[1582468] = {"神圣惩戒","在施法者周围引发一次高威胁的圣光爆炸，对所有敌方目标造成15237s1点神圣伤害，并为23455a1码范围内的所有团队成员治疗23455s1点生命值。\n\n攻击强度会提高此法术的伤害，但会降低其治疗量。\n\n@ext:使用神圣新星修正值。:ext@","汉化"},
[1582469] = {"神圣惩戒","在施法者周围引发一次高威胁的圣光爆炸，对所有敌方目标造成15237s1点神圣伤害，并为23455a1码范围内的所有团队成员治疗23455s1点生命值。\n\n攻击强度会提高此法术的伤害，但会降低其治疗量。\n\n@ext:使用神圣新星修正值。:ext@","汉化"},
