[1582995] = {"奥术冲锋","冲锋在撞击时对附近敌人造成(PL*2+1582996m1)+(SP*0.12)+(AP*0.12)点奥术伤害，立即恢复你282884s1%的已损失法力值，并为附近盟友提供充能光辉效果，在282884d内每秒恢复282884s1%的已损失法力值。","汉化"},
