[1583722] = {"耀焰打击","发射照明弹，暴露a码范围内所有潜行和隐形的敌人，持续d。效果结束时召唤箭雨，造成1583720m1*scalingbp+RAP*0.8点物理伤害。被击中的敌人移动速度降低1583724s1%，并受到你造成的伤害提高1583724s2%，持续1583724d。\n\n对你的猎人印记目标的伤害提高25%。","汉化"},
