[1584208] = {"闪电释放","当施放闪电箭或闪电链时，你的闪电护盾会造成双倍伤害并释放纯净能量，使附近敌人昏迷1584210d。\n\n@ext:此效果每20秒只能触发一次。:ext@","汉化"},
