[1584544] = {"迅捷复仇者","@req:1131935:req@\n你的复仇者之盾会额外攻击个目标。每命中一个目标，你的移动速度提高1584545s1%，最多叠加1584545u次，持续1584545d。","汉化"},
[1584565] = {"盲目消散","消散的冷却减少/1000;S2秒。消散结束时，会释放一道暗影新星，使附近敌人致盲并迷惑1584566d。","汉化"},
