[1584647] = {"驱散爆裂","你的驱散射击会释放一道锥形烈焰，造成(PL*3+1584648m1)+(SP*0.15)+(AP*0.15)点火焰伤害，击退敌人，并使其受到你造成的伤害提高283451s1%，持续283451d。","汉化"},
[1584669] = {"蔓延根须","你的群体缠绕每3秒会扩散到附近敌人身上。束缚持续3秒，并且会继续蔓延到附近敌人。\n\n@ext:每名敌人每10秒最多被蔓延根须影响1次。:ext@","汉化"},
