[1584733] = {"法力之泉","你的光明之泉现在被法力灌注，其治疗效果还会获得|cFFFFFFFF法力之泉|r。\n@s:1584734:0@","汉化"},
[1584755] = {"致命飞跃","英勇飞跃对生命值低于25%的目标造成的伤害提高30%。英勇飞跃击杀敌人会重置其冷却。\n\n@ext:英勇飞跃对玩家造成的伤害提高15%。:ext@","汉化"},
[1584779] = {"根须之握","在你面前释放纠缠根须，将敌人束缚并造成(PL*4+1584781m2)+(SP*0.2)+(AP*0.13)点自然伤害。当根须收缩时，会将被束缚的敌人拉回到你的原始位置。\n\n@ext:可在变形时使用:ext@","汉化"},
