[1586308] = {"宇宙复仇","在日蚀期间，你受到物理攻击时，对攻击者触发一次阳炎爆裂，造成(PL*1+1586309m1)+(SP*0.05)+(AP*0.03253)点自然伤害，并使其攻击强度降低。\n\n在月蚀期间，你受到法术攻击时，对攻击者触发一次月光箭，燃烧攻击者的法力值，并造成这次损失法力值50%的奥术伤害。","汉化"},
[1586329] = {"噩梦乍醒","你的鬼影缠身会对目标施加噩梦乍醒。当敌人治疗你的噩梦乍醒目标时，治疗者将受到|cFFFFFFFF幻影噩梦|r影响。\n@s:1586331:0@","汉化"},
[1586397] = {"爆发虚空","触发你的反冲天赋会在虚空中撕开一个裂隙，击退附近的敌人并使其减速1586398s2%，持续1586398d，但会使反冲的冷却时间增加%。","汉化"},
[1586444] = {"集中连射","在1.5秒内向目标发射一连串子弹，每次射击造成1586443s2%武器伤害加上1586443s1点伤害。\n\n@ext:与多重射击和瞄准射击共享冷却时间:ext@","汉化"},
[1586518] = {"致命追击","立刻使用副手匕首发动攻击，并从主手与副手各施加2次毒药。\n\n最多2次充能，16秒秒再充能时间。终结技每消耗1个连击点，有5%的几率恢复1次充能。\n\n@ext:使用毒刃修正值。:ext@","汉化"},
[1586604] = {"毒药炸弹连击","施放剔骨、毒伤和猩红风暴会使毒液炸弹的剩余冷却时间减少/1000;1586605S1秒。","汉化"},
[1586625] = {"毒液炸弹","投掷毒药炸弹释放致命毒雾，立即施加1层致命毒药，并且每2秒对附近敌人额外施加1层，持续d。","汉化"},
[1586648] = {"冰川尖刺","召唤一个冰川尖刺，造成m1+(SP*0.25)+(AP*0.1625)点冰霜伤害，并使区域内的敌人减速S2%，持续d。\n\n在战斗外施放时，冻结敌人4秒。\n\n@ext:此技能使用冰锥术修正值。:ext@","汉化"},
[1586649] = {"冰川尖刺","召唤一个冰川尖刺，造成m1+(SP*0.129)+(AP*0.0838)点冰霜伤害，并使区域内的敌人减速S2%，持续d。\n\n非战斗状态施放冻结敌人4秒。\n\n@ext:此技能使用冰锥术修正值。:ext@","汉化"},
