[1586786] = {"希望的火花","当治疗生命值低于50%的盟友时，你的圣光闪现和圣光术的爆击率额外提高%。","汉化"},
[1586808] = {"技巧射击","多重射击命中3个或以上目标时，使你获得|cFFFFFFFF技巧射击|r。\n\n@s:1586809:0@","汉化"},
[1586857] = {"动荡唤醒","引导此法术时，使你对打断、沉默和昏迷免疫，并在d内恢复总法力值的m1*3%。完成动荡唤醒后，附近的敌人会受到(PL*3+1586836m1)+(SP*0)+(AP*0)点奥术伤害并被击退。\n\n@ext:使用唤醒修正值:ext@","汉化"},
[1586898] = {"炽焰逃脱","一触即燃还会在激活时使你的移动速度提高%，但其持续时间减少/100;S2%。","汉化"},
[1586918] = {"组合拳","@req:1120243:req@\n毁灭打击造成伤害会使你下一个单体近战技能的爆击率提高1586919s1%。","汉化"},
[1586944] = {"卑鄙行径","你的肾击还会使目标沉默最多1586945d。","汉化"},
[1586988] = {"慷慨之力","对一名盟友施放能量灌注使你获得|cFFFFFFFF慷慨之力|r。\n@s:1586989:0@","汉化"},
[1587050] = {"嗜血渴望","@req:1116511:req@\n连续使用两次出血可获得|cFFFFFFFF嗜血渴望|r。\n@s:1587051:0@","汉化"},
[1587055] = {"刺客冲动","@req:1113750:req@\n背刺会使冲动的冷却时间减少/1000;1587056m1秒。","汉化"},
[1587073] = {"罪恶转移","你的正义防御会将盟友至少%的威胁值转移给你。","汉化"},
[1587114] = {"集中","施放快速治疗、强效治疗术、苦修、治疗祷言、治疗之环和联结治疗使你获得|cFFFFFFFF集中|r.\n@s:1587115:0@","汉化"},
[1587135] = {"贪得无厌","目标受到你的撕裂影响，会使你的压制伤害提高%。当你的撕裂造成伤害时，你会获得/10;1587137s1点怒气值。此效果有1秒冷却时间。","汉化"},
[1587176] = {"急速碎冰","寒冰箭在空中尚未命中目标时立即连击另一个法术，会使该法术的伤害提高1587177s1%。","汉化"},
[1587198] = {"大招来了","@req:1123881:req@\n每第4次使用嗜血造成的伤害提高1587200s1%。","汉化"},
[1587220] = {"微风","风怒造成伤害使你获得|cFFFFFFFF微风|r。\n@s:1587221:0@","汉化"},
[1587280] = {"熔岩意志","你的心智变为熔岩，使你的法术爆击的治疗和伤害加成提高%并降低威胁值。法力值消耗降低%。\n\n@ext:不能与姿态或形态等其他动作条变换技能一起使用。:ext@","汉化"},
[1587301] = {"剑与雷霆","你的毁灭打击和复仇有h%几率重置雷霆一击冷却时间，并使你的下一个雷霆一击不消耗怒气。","汉化"},
[1587322] = {"敏锐思维","你的思维变得敏锐，法术急速提高%，法术消耗减少%，但受到的伤害提高%。\n\n@ext:不能与姿态或形态等其他条形变换技能同时使用。:ext@","汉化"},
[1587342] = {"扭曲心智","你的心智变得扭曲，法术强度提高PL*1。命中几率提高%，但治疗和吸收效果减少1587344s1%。\n\n@ext:不能与姿态或形态等其他动作条变换技能一起使用。:ext@","汉化"},
[1587364] = {"取骨来见！","你的伤害性猎人技能会使|cFFFFFFFF杀戮命令|r的冷却时间减少/1000;1587365S2秒。\n\n使用|cFFFFFFFF杀戮命令|r会使你的宠物冲向20码内的当前目标，并对其造成武器伤害。","汉化"},
[1587406] = {"无尽萨满之怒","你的法术爆击会使萨满之怒的持续时间延长3秒。\n\n@ext:此效果每5秒只能触发一次。:ext@","汉化"},
[1587427] = {"身手敏捷","使用英勇飞跃、巨人打击或破战者使你获得|cFFFFFFFF身手敏捷|r。\n@s:1587428:0@","汉化"},
[1587448] = {"灭战者","践踏地面，对附近的敌人造成%护甲穿刺武器伤害，并使你的攻击穿刺敌人的%护甲，持续d。\n\n@ext:使用巨人打击修正值：ext@","汉化"},
[1587522] = {"军刀猛刺","终结技，根据连击点数决定造成的伤害：\n1点：m1+2.5*PL+((2*PL+b1*1)+(AP*0.012)*1)+SP*0.006)*1-M1+2.5*PL+((2*PL+b1*1)+(AP*0.012)*1)+SP*0.006)*1点伤害\n2点：m1+2.5*PL+((4*PL+b1*2)+(AP*0.012)*2)+SP*0.006)*2-M1+2.5*PL+((4*PL+b1*2)+(AP*0.012)*2)+SP*0.006)*2点伤害\n3点：m1+2.5*PL+((6*PL+b1*3)+(AP*0.012)*3)+SP*0.006)*3-M1+2.5*PL+((6*PL+b1*3)+(AP*0.012)*3)+SP*0.006)*3点伤害\n4点：m1+2.5*PL+((8*PL+b1*4)+(AP*0.012)*4)+SP*0.006)*4-M1+2.5*PL+((8*PL+b1*4)+(AP*0.012)*4)+SP*0.006)*4点伤害\n5点：m1+2.5*PL+((10*PL+b1*5)+(AP*0.012)*5)+SP*0.006)*5-M1+2.5*PL+((10*PL+b1*5)+(AP*0.012)*5)+SP*0.006)*5点伤害\n\n当在5个连击点数使用时，你的破裂将传播到1587521i码附近的目标。","汉化"},
[1587566] = {"双重激活","对盟友施放激活也会使你获得|cFFFFFFFF双重激活|r。\n@s:1587567:0@","汉化"},
[1587655] = {"“潜行”","你变成了一个箱子，除非是最机敏的冒险者，否则无人能察觉。同时，由于没有腿，你无法移动。\n\n@ext:使用箱子修正值，非常适合有谋略的玩家。:ext@","汉化"},
[1587677] = {"法师之触","对敌人施放法师之触，会累积你对目标造成的50%的奥术伤害，持续d，然后爆炸，恢复1587678s2%的总法力值，并对目标和附近的敌人造成累积的奥术伤害。","汉化"},
