[1589116] = {"恶魔天谴","使用恶魔支配后，你的下一个古尔丹之手将召唤双倍数量的野生小鬼。施放古尔丹之手会使恶魔支配的冷却时间减少/1000;1589119s1秒。","汉化"},
[1589159] = {"元素平衡","在10秒内造成一次火焰、冰霜和自然系法术会使你的上述类型法术伤害提高1589160s1%，持续1589160d。","汉化"},
[1589181] = {"鬼魅痛击","以暗影之力造成%点武器伤害，并对目标释放|cFFFFFFFF鬼魅痛击|r。\n\n@ext:使用还击修正值:ext@\n\n@s:1589182:0@","汉化"},
[1589255] = {"自然涌动","@req:1155198req@\n使用潮汐之力或自然迅捷还会使你的法术急速提高1589258s1%，持续1589258d。\n\n次级治疗波、治疗波、治疗链或激流的瞬发效果进行治疗时，会使你的自然迅捷和潮汐之力的冷却时间减少/1000;1589256s1秒。","汉化"},
[1589331] = {"充能之潮","对怪物施放闪电箭或闪电链会使你的下一个治疗链或治疗波的施法时间和法力消耗减少1589333s1%，最多叠加3层。","汉化"},
[1589381] = {"源生之潮","@req:1161295req@\n每施放3次激流会使你获得|cFFFFFFFF源生之潮|r。\n@s:1589383:0@","汉化"},
[1589466] = {"冲动成瘾","@req:1113750:req@\n你的终结技每消耗1个连击点数有20%几率使冲动的冷却时间减少/1000;1589467m1秒。另外，冲动不再触发公共冷却。","汉化"},
[1589486] = {"疾速突袭","你的终结技每消耗一个连击点数有4%的几率使你获得|cFFFFFFFF洞察秋毫|r。\n@s:1589487:0@","汉化"},
[1589552] = {"牧师之光","向四面八方释放耀眼光芒，治疗10码内5名生命值最低的盟友PL*3.5+m1点生命值。\n\n@ext:使用圣光术修正值。:ext@","汉化"},
[1589573] = {"飞镖束","你的近战技能会使你获得|cFFFFFFFF隐秘飞镖|r。\n@s:1589575:0@","汉化"},
[1589649] = {"狂怒之势","使用死亡之愿、血之饥渴、血性狂暴、鲁莽、狂暴之怒或狂野怒火时，会随机使上述其他技能的冷却时间减少3秒。\n\n@ext:即使该技能未处于冷却或未学会，仍可能被选中。:ext@","汉化"},
[1589673] = {"十字军审判","你的审判会使你下一个法术的爆击率提高1589675s2%，并使其施法时间减少1589675s1%。","汉化"},
[1589721] = {"暴露弱点","你的远程攻击对生命值高于20%的目标有h%几率使你获得|cFFFFFFFF暴露弱点|r。此效果每15秒只能触发一次。\n\n@s:1589722:0@","汉化"},
[1589810] = {"圣锤风暴","神圣之锤环绕你d，使你的护甲提高%，每秒对附近敌人造成(PL*1+1589811m1)+(SP*0.05)+(AP*0.05)点神圣伤害。被击中的敌人移动速度降低1589811s2%，攻击速度降低1589811s3%，持续1589811d。","汉化"},
