[1589853] = {"乌索克的狂暴","使用重殴、横扫（熊）、裂伤（熊）或割伤会使激怒的冷却时间减少/1000;1589855S1秒。激怒还会使你的近战爆击率提高1589854s1%。","汉化"},
[1589878] = {"猛殴痛打","使用猛击会使你获得激怒，并强化裂伤（熊）额外攻击附近2个目标，持续1589879d。","汉化"},
[1589904] = {"剑刃漩涡","@req:1113877:req@\n当剑刃乱舞激活时，你的近战终结技每消耗一个连击点有20%几率使剑刃乱舞的冷却减少/1000;1589926s1秒，并制造一个|cFFFFFFFF剑刃旋涡|r。\n@s:1589905:0@","汉化"},
