[1589946] = {"缜密战术","伏击造成伤害会使你的下一个剔骨的能量消耗降低1589947s1点，并使割裂的持续时间延长/1000;1589948s1秒。","汉化"},
[1590028] = {"圣洁道标","当神恩术激活时，用神圣系治疗法术治疗你的圣光道标，会使道标目标和20码内的5名盟友额外获得30%的治疗量。","汉化"},
[1590048] = {"迅捷神恩","@req:1120216:req@\n你的神恩术同时会使你的下一个圣光闪现、圣光术或神圣震击的效果提高%。\n\n圣光闪现、圣光术和神圣震击的有效治疗会使神恩术的冷却时间缩短2秒。","汉化"},
[1590069] = {"回响之力","你的萨满震击技能造成%额外威胁值，并使你获得以下增益效果：\n\n|cFFFFFFFF大地震击|r：使你受到的物理伤害降低1590070s1%。\n\n|cFFFFFFFF冰霜震击|r：使目标的攻击强度降低4.5*PL-3点。\n\n|cFFFFFFFF烈焰震击|r：使你获得一个护盾，对近战攻击者造成火焰伤害。\n\n@ext:攻击强度降低效果不与类似效果叠加。:ext@","汉化"},
[1590179] = {"盾牌技巧","使用盾墙会重置盾牌格挡的冷却时间。\n\n使用盾牌格挡会重置盾牌猛击的冷却时间。","汉化"},
[1590210] = {"致命预兆","在猎豹形态下消耗清晰预兆，会使你的熊形态技能爆击率提高1590212s1%，持续1590212d。\n\n在熊形态下消耗清晰预兆，会使你的猎豹形态技能伤害提高1590218s1%，持续1590218d。","汉化"},
[1590223] = {"心灵清晰","使你的清晰预兆天赋触发几率额外提高%。","汉化"},
[1590237] = {"狂乱成长","野性成长的治疗效果提高%，但其持续时间减少/1000;S3秒，其治疗目标减少S1个。","汉化"},
[1590242] = {"剥皮黑暗","消耗|cFFFFFFFF黑暗|r现在会将你在1575565d内下一次心灵尖啸的引导时间减少25%。","汉化"},
[1590263] = {"战斗节奏","使用猫鼬撕咬或反击会使你的下一个奥术射击、爆炸射击或快速射击的伤害提高1590264s1%，法力值消耗降低1590264s2%。","汉化"},
[1590269] = {"快速拔枪","快速射击，造成%武器伤害。\n\n施放猫鼬撕咬或反击重置快速拔枪冷却时间。","汉化"},
