[1590292] = {"混乱灼烧","使用混沌之火灼烧敌人，造成(m1)+(SP*0.3)+(AP*0.195)点暗影烈焰伤害，并在1590293d内每1590293t1秒额外造成(m1)+(SP*0.3)+(AP*0.195)点伤害。混沌灼烧无法被抵抗，且可穿透所有吸收效果。\n\n@ext:使用混乱之箭的修正值:ext@","汉化"},
