[1590499] = {"暗影帷幕","以邪煞暗影魔法笼罩目标，在d内每t3秒造成m3+(SP*0.11)+(AP*0.0715)点暗影伤害。\n\n降低点所有魔法抗性，并使受到的魔法伤害提高%，同时施加|cFFFFFFFF腐化暗影|r效果。\n\n@ext:无法与类似效果叠加。使用元素诅咒修正值。:ext@\n@s:1590500:0@","汉化"},
[1590501] = {"暗影帷幕","以邪煞暗影魔法笼罩目标，在d内每t3秒造成m3+(SP*0.11)+(AP*0.0715)点暗影伤害。\n\n降低点所有魔法抗性，并使受到的魔法伤害提高%，同时施加|cFFFFFFFF腐化暗影|r效果。\n\n@ext:无法与类似效果叠加。使用元素诅咒修正值。:ext@\n@s:1590500:0@","汉化"},
