[1590509] = {"剧毒逃脱","你的疾跑会在身后留下毒气，每秒对附近敌人造成1590512m1*scalingbp+AP*0.05点自然伤害。\n\n造成伤害会使疾跑的冷却减少/1000;1590513S1秒，但每秒只能减少1次。\n\n@ext:潜行状态下不会触发此效果。:ext@","汉化"},
[1590527] = {"蛆虫陷阱","放置一个陷阱，会在首个敌人接近时释放毒蛆。毒蛆持续15秒，陷阱持续d。同时只能激活一个陷阱。","汉化"},
[1590555] = {"多头蛇钉刺","你的毒蛇钉刺最多命中个目标，且毒蛇钉刺造成伤害会使急速射击的冷却时间减少/1000;1590556s1秒。","汉化"},
[1590568] = {"流血之刃","使用冲锋后，你的下一次旋风斩会对命中的目标施加撕裂。","汉化"},
[1590589] = {"刃舞风暴","一阵匕首之雨倾泻在目标区域，引导期间每t3秒造成(1590590m1)+(SP*0.05985)+(AP*0.05985)点物理伤害，持续d。\n\n@ext:使用飓风修正值。:ext@","汉化"},
[1590592] = {"刃舞风暴","锋刃之雨倾泻在目标区域，引导期间每t3秒造成(1590596m1)+(SP*0.05985)+(AP*0.05985)点物理伤害，持续d。\n\n@ext:使用飓风修正值。:ext@","汉化"},
[1590593] = {"刃舞风暴","锋刃之雨倾泻在目标区域，引导期间每t3秒造成(1590597m1)+(SP*0.05985)+(AP*0.05985)点物理伤害，持续d。\n\n@ext:使用飓风修正值。:ext@","汉化"},
[1590594] = {"刃舞风暴","锋刃之雨倾泻在目标区域，引导期间每t3秒造成(1590598m1)+(SP*0.05985)+(AP*0.05985)点物理伤害，持续d。\n\n@ext:使用飓风修正值。:ext@","汉化"},
[1590595] = {"刃舞风暴","刀锋之雨倾泻而下，引导期间对目标区域内的敌人每t3秒造成(1590599m1)+(SP*0.05985)+(AP*0.05985)点物理伤害，持续d。\n\n@ext:使用飓风修正值。:ext@","汉化"},
[1590611] = {"图书馆肃静","向你的目标投掷一本书，造成((PL-16)*6+m2)+(SP*1)+(AP*1)点物理伤害，打断其施法并使其沉默，持续d。\n\n@ext:此技能与其他打断技能共享冷却时间。:ext@","汉化"},
[1590660] = {"守护者之光","治疗自己1590660m1*scalingbp+SP*0.5点生命值，并对圣骑士1590664a1码范围内的敌人造成相当于治疗量150%的高威胁伤害。同时，使受到的伤害降低1590659s2%，受到的治疗效果提高1590659s1%，持续1590659d。","汉化"},
[1590668] = {"猛烈复仇","@req:1120057:req@\n你的复仇天赋可额外叠加一层。\n@ext:@s:1120057:0@:ext@","汉化"},
[1590684] = {"燃火之引","施放伤害性物理系法术和技能会使你的火焰伤害提高1590678s1%。\n\n施放伤害性火焰系法术和技能会使你的物理伤害提高1590669s1%。\n\n这两个效果最多可叠加1590669u次，持续1590669d。","汉化"},
[1590690] = {"烈焰之种","施放伤害性自然系法术和技能会使你的火焰伤害提高1590678s1%。\n\n施放伤害性火焰系法术和技能会使你的自然伤害提高1590691s1%。\n\n这两个效果最多可叠加1590669u次，持续1590669d。","汉化"},
[1590703] = {"天生蛮力","施放造成伤害的自然法术和技能会使你的物理伤害提高1590669s1%。\n\n施放造成伤害的物理法术和技能会使你的自然伤害提高1590691s1%。\n\n两种效果均可叠加1590669u层，持续1590669d。","汉化"},
