[1590734] = {"暗影推进","施放伤害性暗影法术和技能会使你的火焰伤害提高1590678s1%。\n\n施放伤害性火焰法术和技能会使你的暗影伤害提高1590735s1%。\n\n这两种效果最多可叠加1590669u层，持续1590669d。","汉化"},
