[1590760] = {"冰冷咒术师","施放伤害性冰霜系法术和技能会使你的奥术伤害提高1590754s1%。\n\n施放伤害性奥术系法术和技能会使你的冰霜伤害提高1590710s1%。\n\n这两个效果最多可叠加1590669u层，持续1590669d。","汉化"},
[1590766] = {"自然秩序","施放具有伤害性的自然法术和技能会使你的奥术伤害提高2%.\n\n施放具有伤害性的奥术法术和技能会使你的自然伤害提高2%.\n\n这两种效果最多可叠加4次.","汉化"},
