[1590792] = {"局部风暴","在目标区域召唤一场猛烈的风暴，持续d，每t3秒对敌人造成1590797m1+1590797ppl1+sp*0.16点自然伤害，并使敌人的攻击速度降低%，移动速度降低1590791s1%。\n\n@ext:使用飓风修正值:ext@","汉化"},
