[1590816] = {"复仇之剑","当对带有5层复仇圣印或腐蚀圣印效果的目标使用审判时，将对目标和3码范围内的其他敌人造成AP*0.18+SP*0.108点额外神圣伤害。","汉化"},
[1590822] = {"泰坦化身","使用天神下凡会每3秒增加你的体型和所受伤害降低286233s1%.结束时,你会部分石化,持续286234d秒,使你的移动速度减慢286234s1%,并对5码内的敌人造成物理伤害并使其瘫痪,持续286235d秒.","汉化"},
[1590832] = {"纵火狂的印记","@req:1111129:req@\n使用|cFFFFFFFF焚化燃烧|r后，你接下来的3次炎爆术将额外攻击最多3个附近目标。\n\n|cFFFFFFFF炎爆术|r和|cFFFFFFFF霜火之箭|r的持续伤害会使|cFFFFFFFF焚化燃烧|r的冷却时间缩短1秒。","汉化"},
[1590838] = {"神圣灌注","使友方目标获得神圣之力，受到的所有伤害降低%，并获得60%抵抗敌方驱散的抗性，持续d。击飞玩家并使附近敌人的移动速度降低1590839s1%，持续1590839d。\n\n@ext:使用痛苦压制修正值。:ext@","汉化"},
[1590850] = {"伏击猛兽","斜掠或割裂（豹）造成伤害有15%几率、撕碎有h%的几率使你获得|cFFFFFFFF伏击猛兽|r。\n@s:1590851:0@","汉化"},
[1590858] = {"风暴涌动","快速连续使用闪电箭和闪电链造成伤害时，会引发一次|cFFFFFFFF风暴涌动|r，对目标造成((PL-20)*6+1590861m1)+(SP*0.316)+(AP*0.2054)点额外自然伤害。\n\n风暴涌动使用闪电箭修正值","汉化"},
[1590873] = {"黑寡妇打击","毒液打击，使你对该目标造成的所有伤害提高%，造成(PL*4.375+m1)+(RAP*0.2)点物理伤害，并在1590876d内每/1000;t2秒额外造成(PL*2+1590874m1)+(RAP*0.052)点自然伤害。\n\n@ext:使用黑箭修正值:ext@","汉化"},
[1590881] = {"狂怒突刺","对主目标造成1590882m2*1.5%武器伤害，并对面前最多3名敌人造成1590882s2%伤害。\n\n进入激怒可获得1次狂暴突刺使用次数。最多2次充能。\n\n@ext:使用怒击修正值:ext@","汉化"},
