[2110008] = {"暴雨图腾-释放","在你脚下召唤一个生命值为5的图腾，持续15秒，收集你所有治疗法术的能量。当图腾失效或死亡时，储存的能量会释放出来，治疗40码范围内所有受伤的盟友，治疗量为图腾激活时所有治疗量的30%，平均分配给各个目标。\n\n再次施放此法术时会召回图腾并释放治疗效果。","汉化"},
[2110009] = {"暴雨图腾","在你脚下召唤一个拥有5生命值值的图腾，持续15秒。收集你所有治疗法术的能量。当图腾失效或死亡时，储存的能量会释放出来。治疗40码范围内所有受伤的盟友。治疗量为图腾激活时所有自然治疗量的30%。平均分配给各个目标。\n\n第二次施放此法术时，会召回图腾并释放治疗效果。","汉化"},
