[2110080] = {"命运骨骰","掷出命运骰子，获得1、2个随机战斗增益效果，运气极佳时可获得5个。每消耗一个连击点数可延长持续时间：\n1点：6秒\n2点：12秒\n3点：18秒\n4点：24秒\n5点：30秒","汉化"},
