[2110216] = {"闪光术","将施法者向前传送a1码，路线上有阻挡物则会停止。\n\n此技能可以在施法时使用，但不能在引导时使用，并且不会触发公共冷却。\n\n与闪现术共享冷却时间。","汉化"},
[2304500] = {"盲目之光","向四面八方发射炫目之光，使10码范围内的敌人目盲，导致其迷惑6秒。","汉化"},
[2304501] = {"烟雾弹","在你周围8码范围内制造一片浓烟云雾，持续d。敌人无法锁定烟云内外的目标。","汉化"},
[2304504] = {"乌索尔的漩涡","在自己周围召唤一个持续d的狂风旋涡，使5码内所有敌人的移动速度降低%。当敌人离开漩涡时，狂风会将该敌人拉回漩涡中心。敌人每8秒只能被拉入漩涡1次。\n\n此技能在变形时可用。","汉化"},
[2304507] = {"群体缠绕","将目标及其8码范围内的所有敌人缠绕在原地，持续d。受到伤害可能会中断此效果。\n\n可在变形时使用。","汉化"},
[2304508] = {"狂奔怒吼","咆哮，使10码范围内所有成员的移动速度提高%，持续d。不会中断潜伏。","汉化"},
[2304510] = {"风行图腾","在施法者脚下召唤一个拥有5点生命值的空气图腾，持续d，为20码范围内的小队成员提供风行。在效果持续期间，他们的移动速度不会低于100%。","汉化"},
[2304512] = {"不灭决心","硬化你的皮肤，使你受到的所有伤害降低%，并免疫打断、沉默和击退效果，持续d。","汉化"},
[2304514] = {"颅骨战旗","在你脚下放置一面战旗，使40码内的小队或团队成员近战和远程爆击率提高2304515s1%，持续2304515d。\n\n获得此效果的盟友将进入疲劳状态，在2304568d内无法再次受益于颅骨战旗。\n\n你可以援护战旗。","汉化"},
[2304516] = {"血之恐惧","引导时，你将自身包裹在鲜血屏障中，免疫沉默、击晕和打断效果。每当954567r码范围内的敌人对你造成非持续性伤害时，你将吸取其生命值并使其因恐惧而逃跑，持续954567d。","汉化"},
[2304518] = {"电能图腾","召唤一个拥有5点生命值的空气图腾，施放在20码范围内。图腾会聚集周围空气中的电能，并在2秒后爆炸，对8码范围内的所有敌人造成自然伤害并使其昏迷，持续2304519d。","汉化"},
[2304520] = {"束缚元素","束缚元素目标最多50秒，被束缚的单位无法移动、攻击或施法，造成的任何伤害都会接触束缚效果。同时只能束缚一个目标。","汉化"},
[2304521] = {"恶魔之跃","展开恶魔之翼跃向空中，进行短距离冲刺。若在1秒内再次激活，可进行二次跳跃。","汉化"},
[2304522] = {"虚空转换","你和当前目标小队或团队成员交换生命值百分比，如果你和你的盟友的生命值低于25%，则将其生命值百分比提高到25%.","汉化"},
[2304523] = {"日光术","你召唤一束太阳光束，激活时使光束下的所有敌人沉默。日光术持续d。","汉化"},
[2304553] = {"斩击","终结技，根据连击点数造成伤害：\n1点：m1+((b1*1)+AP*0.056)*mult-M1+((b1*1)+AP*0.07)*mult点伤害\n2点：m1+((b1*2)+AP*0.112)*mult-M1+((b1*2)+AP*0.14)*mult点伤害\n3点：m1+((b1*3)+AP*0.168)*mult-M1+((b1*3)+AP*0.21)*mult点伤害\n4点：m1+((b1*4)+AP*0.224)*mult-M1+((b1*4)+AP*0.28)*mult点伤害\n5点：m1+((b1*5)+AP*0.28)*mult-M1+((b1*5)+AP*0.35)*mult点伤害\n\n对生命值低于35%的目标使用时，你的下一个剔骨或毒伤的伤害提高20%。斩击不消耗连击点数。","汉化"},
[2304555] = {"斩击","终结技，根据连击点数造成伤害：\n1点:m1+((b1*1)+AP*0.056)*mult-M1+((b1*1)+AP*0.07)*mult点伤害\n2点:m1+((b1*2)+AP*0.112)*mult-M1+((b1*2)+AP*0.14)*mult点伤害\n3点:m1+((b1*3)+AP*0.168)*mult-M1+((b1*3)+AP*0.21)*mult点伤害\n4点:m1+((b1*4)+AP*0.224)*mult-M1+((b1*4)+AP*0.28)*mult点伤害\n5点:m1+((b1*5)+AP*0.28)*mult-M1+((b1*5)+AP*0.35)*mult点伤害\n\n若对生命值低于35%的目标使用，你的下一次剔骨或毒伤造成的伤害提高20%。终结技不消耗连击点数。","汉化"},
