[2304562] = {"血之恐惧","引导时，你将自身包裹在鲜血屏障中，免疫沉默、击晕和打断效果。每当954567r码范围内的敌人对你造成非持续性伤害时，你将吸取其生命值并使其因恐惧而逃跑，持续954567d。","汉化"},
[2304564] = {"血之恐惧","引导时，你将自身包裹在鲜血屏障中，免疫沉默、击晕和打断效果。每当954567r码范围内的敌人对你造成非持续性伤害时，你将吸取其生命值并使其因恐惧而逃跑，持续954567d。","汉化"},
[2304566] = {"血之恐惧","引导时，你将自身包裹在鲜血屏障中，免疫沉默、击晕和打断效果。每当954567r码范围内的敌人对你造成非持续性伤害时，你将吸取其生命值并使其因恐惧而逃跑，持续954567d。","汉化"},
[2304570] = {"地震术","你会使目标位置的大地颤抖和破碎。每1秒对敌人造成一次自然伤害，并使他们在半径为8码的范围内移动速度降低%，持续d。\n\n受到伤害的敌人会受到战栗的影响。叠加3层后他们会昏迷3秒。从任意地震术效果中每10秒只能触发一次。","汉化"},
[2304571] = {"地震术","你会使目标位置的大地颤抖和破碎。每1秒对敌人造成一次自然伤害，并使他们在半径为8码的范围内移动速度降低%，持续d。\n\n受到伤害的敌人会受到战栗的影响。叠加3层后他们会昏迷3秒。从任意地震术效果中每10秒只能触发一次。","汉化"},
