[2304584] = {"血之恐惧","引导时，你将自身包裹在鲜血屏障中，免疫沉默、击晕和打断效果。每当954567r码范围内的敌人对你造成非持续性伤害时，你将吸取其生命值并使其因恐惧而逃跑，持续954567d。","汉化"},
[2304587] = {"倒刺射击","|cffffffff2次充能\n10秒再充能|r\n发射一发穿透射击，使敌人流血，在d内造成总计(2304587m1*scalingbp+RAP*0.04)*4点物理伤害。\n\n这会使你的宠物进入狂乱，攻击速度提高2304687s1%，持续2304687d，最多可叠加3层。","汉化"},
[2304588] = {"电能图腾","召唤一个拥有5点生命值的空气图腾，施放在20码范围内。图腾会聚集周围空气中的电能，并在2秒后爆炸，对8码范围内的所有敌人造成自然伤害并使其昏迷，持续2304519d。","汉化"},
[2304589] = {"电能图腾","召唤一个拥有5点生命值的空气图腾，施放在20码范围内。图腾会聚集周围空气中的电能，并在2秒后爆炸，对8码范围内的所有敌人造成自然伤害并使其昏迷，持续2304519d。","汉化"},
[2304590] = {"电能图腾","召唤一个拥有5点生命值的空气图腾，施放在20码范围内。图腾会聚集周围空气中的电能，并在2秒后爆炸，对8码范围内的所有敌人造成自然伤害并使其昏迷，持续2304519d。","汉化"},
