[2304594] = {"电能图腾","召唤一个拥有5点生命值的空气图腾，施放在20码范围内。图腾会聚集周围空气中的电能，并在2秒后爆炸，对8码范围内的所有敌人造成自然伤害并使其昏迷，持续2304519d。","汉化"},
[2304611] = {"古尔丹之手","召唤一颗恶魔陨石轰击目标区域，对2304612a1码范围内的敌人造成2304612m1*scalingbp+SP*0.36点暗影烈焰伤害，并召唤2304612s2只狂野小鬼加入战斗，持续2304612d。","汉化"},
[2304614] = {"灵魂交换","你将复制目标身上的持续伤害效果，保留其强度和剩余持续时间。\n\n在接下来的d内，你下一次施放灵魂交换：释出将复制的持续伤害效果施加到新目标上。\n\n无法对同一目标重复使用灵魂交换。","汉化"},
[2304616] = {"灵魂交换傀儡","","汉化"},
[2304800] = {"星涌术","对目标造成点星界伤害。","汉化"},
[2304801] = {"圣光之锤","将一把注入圣光的锤子砸进地面，用圣光冲击10码区域，持续10秒。\n\n对敌人造成神圣伤害，并使其移动速度降低50%，持续954848d。同时每2秒最多治疗5名盟友。","汉化"},
[2304806] = {"爆燃冲刺","每秒消耗4%的最大生命值，使移动速度提高50%。移动限制效果无法使你的移动速度低于正常速度的100%。持续直到取消。","汉化"},
[2304807] = {"元素冲击","驾驭并引导元素之力攻击敌方目标，造成元素伤害，并使施法者的爆击率或施法速度提高8秒。","汉化"},
[2304814] = {"浴血奋战","施放后的d内，你的近战技能在2304815d内造成AP*0.05+2304815m1点流血伤害并使目标的移动移速减少2304815s2%，持续2304815d。","汉化"},
[2304817] = {"处决宣判","一柄战锤从天缓缓而降，在10秒内造成神圣伤害。最终会爆发一次范围伤害，对5码内的敌人造成伤害。驱散该效果会立即触发最终爆发。\n\n对受处决宣判影响的目标使用审判，仅触发该技能一半的冷却时间。","汉化"},
[2304821] = {"飞刃","你向目标投掷两把飞刃，每把都会造成2304824s1%武器伤害。","汉化"},
[2304831] = {"空气升腾","你将自己的身体形态交给元素的力量。转化为原始元素能量的存在，持续d。\n\n你的风暴打击现在有30码射程，并造成额外自然伤害。\n\n使用任意萨满震击、闪电箭或闪电链，将重置风暴打击的冷却时间。","汉化"},
[2304835] = {"飞镖投掷","对敌方目标造成物理伤害的远程攻击。奖励个连击点数。","汉化"},
[2304836] = {"怒击","猛力一击，同时使用两把近战武器对目标造成2304837s1%武器伤害。","汉化"},
[2304853] = {"灵魂交换：释放","从目标身上复制你的持续伤害效果，并保留其强度和持续时间。\n\n在5秒之后，你对下一个目标施放灵魂交换：释放时，会将复制的持续伤害效果施加到该目标身上。\n\n你无法对同一目标重复使用灵魂交换。","汉化"},
[2304876] = {"破城者","全力挥动武器猛击目标，造成%武器伤害并将其击退。\n\n目标碰撞到的敌人会被轻微击退并受到2304902s3%武器伤害。","汉化"},
[2304883] = {"猩红风暴","终结技，对8码范围内的所有敌人进行割裂攻击，造成物理伤害并根据连击点数使敌人流血：\n1点:m1+b11+(AP)110.0012物理伤害和(m3+b31+(AP)110.0012)*4流血伤害，持续d。\n2点:m1+b12+(AP)220.0012物理伤害和(m3+b32+(AP)220.0012)*4流血伤害，持续d。\n3点:m1+b13+(AP)330.0012物理伤害和(m3+b33+(AP)330.0012)*4流血伤害，持续d。\n4点:m1+b14+(AP)440.0012物理伤害和(m3+b34+(AP)440.0012)*4流血伤害，持续d。\n5点:m1+b15+(AP)550.0012物理伤害和(m3+b35+(AP)550.0012)*4流血伤害，持续d。","汉化"},
[2304884] = {"猩红风暴","终结技，对8码范围内的所有敌人进行割裂攻击，造成物理伤害并根据连击点数使敌人流血：\n1点:m1+b11+(AP)110.0012物理伤害和(m3+b31+(AP)110.0012)*4流血伤害，持续d。\n2点:m1+b12+(AP)220.0012物理伤害和(m3+b32+(AP)220.0012)*4流血伤害，持续d。\n3点:m1+b13+(AP)330.0012物理伤害和(m3+b33+(AP)330.0012)*4流血伤害，持续d。\n4点:m1+b14+(AP)440.0012物理伤害和(m3+b34+(AP)440.0012)*4流血伤害，持续d。\n5点:m1+b15+(AP)550.0012物理伤害和(m3+b35+(AP)550.0012)*4流血伤害，持续d。","汉化"},
[2304885] = {"猩红风暴","终结技，对8码范围内的所有敌人进行割裂攻击，造成物理伤害并根据连击点数使敌人流血：\n1点:m1+b11+(AP)110.0012物理伤害，和(m3+b31+(AP)110.0012)*4流血伤害，持续d。\n2点:m1+b12+(AP)220.0012物理伤害，和(m3+b32+(AP)220.0012)*4流血伤害，持续d。\n3点:m1+b13+(AP)330.0012物理伤害，和(m3+b33+(AP)330.0012)*4流血伤害，持续d。\n4点:m1+b14+(AP)440.0012物理伤害，和(m3+b34+(AP)440.0012)*4流血伤害，持续d。\n5点:m1+b15+(AP)550.0012物理伤害，和(m3+b35+(AP)550.0012)*4流血伤害，持续d。","汉化"},
