[2304903] = {"圣光之锤","将一把注入圣光的锤子砸进地面，用圣光冲击10码区域，持续10秒。\n\n对敌人造成神圣伤害，并使其移动速度降低50%，持续954848d。同时每2秒最多治疗5名盟友。","汉化"},
[2304904] = {"圣光之锤","将一把注入圣光的锤子砸进地面，用圣光冲击10码区域，持续10秒。\n\n对敌人造成神圣伤害，并使其移动速度降低50%，持续954848d。同时每2秒最多治疗5名盟友。","汉化"},
