[2304972] = {"处决宣判","一柄战锤从天缓缓而降，在10秒内造成神圣伤害。最终会爆发一次范围伤害，对5码内的敌人造成伤害。驱散该效果会立即触发最终爆发。\n\n对受处决宣判影响的目标使用审判，仅触发该技能一半的冷却时间。","汉化"},
