[2305032] = {"奥术宝珠","从你的位置向前发射一颗奥术宝珠，最多行进35码，对接触的敌人造成奥术伤害，并使其受到你造成的奥术伤害提高2305054s1%。连续命中相同目标会使伤害减少50%。","汉化"},
[2305036] = {"奥术宝珠","从你的位置向前发射一颗奥术宝珠，最多行进35码，对接触的敌人造成奥术伤害，并使其受到你造成的奥术伤害提高2305054s1%。连续命中相同目标会使伤害减少50%。","汉化"},
