[2305062] = {"挫志战旗","扔下一面战旗，使30码范围内所有敌人的护甲降低2304805s1%，爆击率降低2304805s2%，持续d。此效果不会与类似效果叠加。\n\n你可以援护你的战旗。\n\n此技能在变形时可用。","汉化"},
[2305072] = {"催眠","强迫敌方目标睡眠d（对玩家为8秒）。受到的任何伤害将增加%，但会唤醒目标。同时只能强迫一个目标睡眠。此法术可在移动时施放。","汉化"},
[2306046] = {"石化图腾","在脚下召唤一个拥有点生命值的石化图腾，持续d，使5729a1码范围内的敌人减速。3秒后，图腾会将敌人|cFFFFFFFF石化|r5秒。\n@ext:@s:2304121:0@:ext@\n@ext:此技能在变形时可用。:ext@","汉化"},
[2315425] = {"复原","消耗目标身上的连击点数的终结技，每3秒恢复%的基础生命值，每个连击点数使持续时间延长：\n1点:3秒\n2点:6秒\n3点:9秒\n4点:12秒\n5点:15秒","汉化"},
[2347612] = {"灵魂碎片生成器","该法术可以生成灵魂碎片，并允许施放需要灵魂碎片生成器的法术。","汉化"},
    }
